package tidecode

import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

const maxPlanBytes = 512 << 10

var planPathRx = regexp.MustCompile(`(?i)^\.tidecode[\\/]plans[\\/]plan-\d{3}\.md$`)

type PlanService struct{}

func planDocument(content, title string) string {
	content = strings.TrimSpace(normalizeText(content))
	body := "---\nstatus: draft\n---\n\n"
	if strings.TrimSpace(title) != "" {
		body += "# " + strings.TrimSpace(title) + "\n\n"
	}
	body += content
	if !strings.HasSuffix(body, "\n") {
		body += "\n"
	}
	return body
}

func (PlanService) ExecuteCreate(root, content string, title ...string) (ToolResult, error) {
	workspace, err := resolveWorkspace(root)
	if err != nil {
		return ToolResult{}, err
	}
	mu := workspaceLock(workspace)
	mu.Lock()
	defer mu.Unlock()
	dir, err := ensureManagedPathNoLinks(workspace, ".tidecode/plans")
	if err != nil {
		return failure(err.Error()), nil
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return ToolResult{}, err
	}
	var target, rel string
	for i := 1; i <= 999; i++ {
		rel = fmt.Sprintf(".tidecode/plans/plan-%03d.md", i)
		target, err = ensureManagedPathNoLinks(workspace, rel)
		if err != nil {
			return failure(err.Error()), nil
		}
		f, e := os.OpenFile(target, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
		if e == nil {
			f.Close()
			break
		}
		if !os.IsExist(e) {
			return ToolResult{}, e
		}
		target = ""
	}
	if target == "" {
		return failure("No available plan number"), nil
	}
	t := ""
	if len(title) > 0 {
		t = title[0]
	}
	doc := planDocument(content, t)
	if len(doc) > maxPlanBytes {
		os.Remove(target)
		return failure("plan exceeds 512 KiB"), nil
	}
	if err := os.WriteFile(target, []byte(doc), 0o600); err != nil {
		return ToolResult{}, err
	}
	r := withSubject(withBody(success("Created "+rel), "created: "+rel), "plan", rel)
	r.Semantics = map[string]any{"operation": "create"}
	return r, nil
}

func setPlanTitleContent(content, title string) string {
	normalizedTitle := strings.Join(strings.Fields(title), " ")
	content = strings.TrimSpace(normalizeText(content))
	if normalizedTitle == "" {
		return content
	}
	separator := string(rune(10))
	lines := strings.Split(content, separator)
	for i, line := range lines {
		if strings.HasPrefix(line, "# ") {
			lines[i] = "# " + normalizedTitle
			return strings.Join(lines, separator)
		}
	}
	return "# " + normalizedTitle + separator + separator + content
}

func (PlanService) ExecuteEdit(root, path, content string, title ...string) (ToolResult, error) {
	normalized := strings.ReplaceAll(path, "\\", "/")
	if !planPathRx.MatchString(path) || strings.Contains(normalized, "../") {
		return failure("Plan paths must match .tidecode/plans/plan-###.md"), nil
	}
	workspace, err := resolveWorkspace(root)
	if err != nil {
		return ToolResult{}, err
	}
	mu := workspaceLock(workspace)
	mu.Lock()
	defer mu.Unlock()
	target, err := ensureManagedPathNoLinks(workspace, normalized)
	if err != nil {
		return failure(err.Error()), nil
	}
	if _, err := os.Stat(target); err != nil {
		return failure("Plan not found"), nil
	}
	t := ""
	if len(title) > 0 {
		t = title[0]
	}
	if strings.TrimSpace(t) != "" {
		content = setPlanTitleContent(content, t)
	}
	doc := planDocument(content, "")
	if len(doc) > maxPlanBytes {
		return failure("plan exceeds 512 KiB"), nil
	}
	if err := os.WriteFile(target, []byte(doc), 0o600); err != nil {
		return ToolResult{}, err
	}
	rel := filepath.ToSlash(normalized)
	r := withSubject(withBody(success("Updated "+rel), "updated: "+rel), "plan", rel)
	r.Semantics = map[string]any{"operation": "edit"}
	return r, nil
}

