var workspaceSkillDirectories = []string{"skills", ".tidecode/skills", ".codex/skills", ".agents/skills", ".claude/skills"}

type Skill struct {
	Name          string
	Description   string
	Content       string
	Location      string
	BaseDirectory string
	Source        string
	SourceLabel   string
}

type SkillDiscovery struct {
	Skills       []Skill
	ErrorMessage string
}

type SkillInput struct {
	Action string `json:"action"`
	Query  string `json:"query,omitempty"`
	Name   string `json:"name,omitempty"`
	Page   int    `json:"page,omitempty"`
}

type SkillService struct {
	WorkspaceRoot string
}

type skillSearchRoot struct {
	Directory   string
	Source      string
	SourceLabel string
}

type cachedSkillDiscovery struct {
	At    time.Time
	State SkillDiscovery
}

var skillCache = struct {
	sync.Mutex
	states map[string]cachedSkillDiscovery
}{states: map[string]cachedSkillDiscovery{}}

func getAgentsSkillsDirectory() string {
	home, _ := os.UserHomeDir()
	return filepath.Join(home, ".agents", "skills")
}

func clearSkillDiscoveryCache() {
	skillCache.Lock()
	defer skillCache.Unlock()
	skillCache.states = map[string]cachedSkillDiscovery{}
}

func parseSkillDocument(raw, location string) Skill {
	content := raw
	name := ""
	description := ""
	normalized := strings.ReplaceAll(raw, "\r\n", "\n")
	if strings.HasPrefix(normalized, "---\n") {
		if end := strings.Index(normalized[4:], "\n---"); end >= 0 {
			frontmatter := normalized[4 : 4+end]
			afterNormalized := normalized[4+end+4:]
			if strings.HasPrefix(afterNormalized, "\n") {
				afterNormalized = afterNormalized[1:]
			}

			for _, rawLine := range strings.Split(frontmatter, "\n") {
				line := strings.TrimSpace(rawLine)
				if line == "" || strings.HasPrefix(line, "#") {
					continue
				}

				parts := strings.SplitN(line, ":", 2)
				if len(parts) != 2 {
					continue
				}

				value := strings.TrimSpace(parts[1])
				if len(value) >= 2 && ((value[0] == '"' && value[len(value)-1] == '"') || (value[0] == '\'' && value[len(value)-1] == '\'')) {
					value = strings.TrimSpace(value[1 : len(value)-1])
				}

				switch strings.TrimSpace(parts[0]) {
				case "name":
					name = value
				case "description":
					description = value
				}
			}

			originalEnd := frontmatterEnd(raw)
			if originalEnd >= 0 {
				content = strings.TrimLeft(raw[originalEnd:], "\r\n")
			} else {
				content = afterNormalized
			}
		}
	}

	if name == "" {
		name = filepath.Base(filepath.Dir(location))
	}
	if description == "" {
		for _, line := range strings.Split(content, "\n") {
			trimmed := strings.TrimSpace(strings.TrimSuffix(line, "\r"))
			if trimmed != "" && !strings.HasPrefix(trimmed, "#") {
				description = trimmed
				break
			}
		}
	}
	if description == "" {
		description = "No description provided."
	}
	skillContent := strings.TrimSpace(content)
	if skillContent == "" {
		skillContent = strings.TrimSpace(raw)
	}

	cleanLocation := filepath.Clean(location)
	return Skill{
		Name:          name,
		Description:   description,
		Content:       skillContent,
		Location:      cleanLocation,
		BaseDirectory: filepath.Dir(cleanLocation),
	}
}

func frontmatterEnd(raw string) int {
	if !strings.HasPrefix(raw, "---") {
		return -1
	}
	position := 3
	for position < len(raw) {
		index := strings.Index(raw[position:], "\n---")
		if index < 0 {
			return -1
		}
		end := position + index + 4
		if end == len(raw) || raw[end] == '\n' || raw[end] == '\r' {
			return end
		}
		position = end
	}
	return -1
}

func normalizeWorkspacePath(workspacePath string) string {
	trimmed := strings.TrimSpace(workspacePath)
	if trimmed == "" {
		return ""
	}
	absolute, err := filepath.Abs(trimmed)
	if err != nil {
		return filepath.Clean(trimmed)
	}
	return filepath.Clean(absolute)
}

func skillSearchRoots(workspacePath string) []skillSearchRoot {
	roots := []skillSearchRoot{}
	seen := map[string]bool{}

	addRoot := func(directory, source, sourceLabel string) {
		clean := filepath.Clean(directory)
		key := strings.ToLower(clean)
		if seen[key] {
			return
		}
		seen[key] = true
		roots = append(roots, skillSearchRoot{Directory: clean, Source: source, SourceLabel: sourceLabel})
	}

	normalizedWorkspace := normalizeWorkspacePath(workspacePath)
	if normalizedWorkspace != "" {
		for _, relativeDirectory := range workspaceSkillDirectories {
			addRoot(filepath.Join(normalizedWorkspace, filepath.FromSlash(relativeDirectory)), "workspace", "Workspace")
		}
	}

	home, _ := os.UserHomeDir()
	for _, relativeDirectory := range globalSkillDirectories {
		addRoot(filepath.Join(home, filepath.FromSlash(relativeDirectory)), "global", "Global")
	}

	return roots
}

func collectSkillFiles(root string) ([]string, error) {
	matches := []string{}
	err := filepath.WalkDir(root, func(path string, entry os.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if entry.Type()&os.ModeSymlink != 0 {
			if entry.IsDir() {
				return filepath.SkipDir
			}
			return nil
		}
		if entry.IsDir() {
			return nil
		}
		if entry.Type().IsRegular() && entry.Name() == skillFileName {
			matches = append(matches, filepath.Clean(path))
		}
		return nil
	})
	return matches, err
}

func readSkillSummary(location string, root skillSearchRoot) (Skill, bool) {
	raw, err := os.ReadFile(location)
	if err != nil {
		return Skill{}, false
	}

	skill := parseSkillDocument(string(raw), location)
	if strings.TrimSpace(skill.Name) == "" {
		return Skill{}, false
	}
	skill.Name = strings.TrimSpace(skill.Name)
	skill.Source = root.Source
	skill.SourceLabel = root.SourceLabel
	return skill, true
}

func discoverAvailableSkills(workspacePath string) SkillDiscovery {
	discovered := []Skill{}

	for _, root := range skillSearchRoots(workspacePath) {
		info, err := os.Stat(root.Directory)
		if os.IsNotExist(err) {
			continue
		}
		if err != nil {
			return SkillDiscovery{Skills: []Skill{}, ErrorMessage: err.Error()}
		}
		if !info.IsDir() {
			continue
		}

		files, err := collectSkillFiles(root.Directory)
		if err != nil {
			return SkillDiscovery{Skills: []Skill{}, ErrorMessage: err.Error()}
		}
		for _, file := range files {
			if skill, ok := readSkillSummary(file, root); ok {
				discovered = append(discovered, skill)
			}
		}
	}

	byName := map[string]Skill{}
	order := []string{}
	for _, skill := range discovered {
		key := strings.ToLower(strings.TrimSpace(skill.Name))
		if key == "" {
			continue
		}
		if _, exists := byName[key]; exists {
			continue
		}
		byName[key] = skill
		order = append(order, key)
	}

	deduped := make([]Skill, 0, len(order))
	for _, key := range order {
		deduped = append(deduped, byName[key])
	}
	sort.Slice(deduped, func(i, j int) bool {
		return deduped[i].Name < deduped[j].Name
	})

	return SkillDiscovery{Skills: deduped}
}

