	Data     []byte
}

type ToolResult struct {
	Body        string         `json:"body,omitempty"`
	DisplayBody string         `json:"displayBody,omitempty"`
	Semantics   map[string]any `json:"semantics,omitempty"`
	Status      string         `json:"status"`
	Subject     *Subject       `json:"subject,omitempty"`
	Summary     string         `json:"summary"`
	Truncated   bool           `json:"truncated,omitempty"`
	Media       []MediaPayload `json:"-"`
}

func success(summary string) ToolResult             { return ToolResult{Status: "success", Summary: summary} }
func failure(summary string) ToolResult             { return ToolResult{Status: "error", Summary: summary} }
func withBody(r ToolResult, body string) ToolResult { r.Body = body; return r }
func withSubject(r ToolResult, kind, path string) ToolResult {
	r.Subject = &Subject{Kind: kind, Path: path}
	return r
}
func withSemantics(r ToolResult, s map[string]any) ToolResult { r.Semantics = s; return r }

func prettyJSON(v any) string {
	b, err := json.MarshalIndent(v, "", "  ")
	if err != nil {
		return fmt.Sprint(v)
	}
	return string(b)
}

func normalizeText(s string) string {
	return strings.ReplaceAll(strings.ReplaceAll(s, "\r\n", "\n"), "\r", "\n")
}

