package tidecode

import (
	"encoding/json"
	"fmt"
	"math"
	"strings"
)

func copyKnownArgs(toolName string, input map[string]any, allowed ...string) (map[string]any, error) {
	known := make(map[string]bool, len(allowed))
	for _, key := range allowed {
		known[key] = true
	}
	out := make(map[string]any, len(input))
	for key, value := range input {
		if known[key] {
			out[key] = value
			continue
		}
		if flag, ok := value.(bool); ok && !flag {
			continue
		}
		return nil, fmt.Errorf("Invalid arguments for %s: additional property %q is not supported", toolName, key)
	}
	return out, nil
}

func strictInt(value any) (int, bool) {
	switch number := value.(type) {
	case int:
		return number, true
	case int8:
		return int(number), true
	case int16:
		return int(number), true
	case int32:
		return int(number), true
	case int64:
		return int(number), true
	case uint:
		return int(number), true
	case uint8:
		return int(number), true
	case uint16:
		return int(number), true
	case uint32:
		return int(number), true
	case uint64:
		if uint64(int(number)) != number {
			return 0, false
		}
		return int(number), true
	case float32:
		v := float64(number)
		if math.Trunc(v) != v {
			return 0, false
		}
		return int(v), true
	case float64:
		if math.Trunc(number) != number || math.IsNaN(number) || math.IsInf(number, 0) {
			return 0, false
		}
		return int(number), true
	case json.Number:
		v, err := number.Int64()
		if err != nil {
			return 0, false
		}
		return int(v), true
	default:
		return 0, false
	}
}

func optionalString(args map[string]any, key string) error {
	value, exists := args[key]
	if !exists {
		return nil
	}
	if _, ok := value.(string); !ok {
		return fmt.Errorf("%s must be a string", key)
	}
	return nil
}

func optionalBool(args map[string]any, key string) error {
	value, exists := args[key]
	if !exists {
		return nil
	}
	if _, ok := value.(bool); !ok {
		return fmt.Errorf("%s must be a boolean", key)
	}
	return nil
}

func integerRange(args map[string]any, key string, minimum, maximum int, allowZero bool) error {
	value, exists := args[key]
	if !exists {
		return nil
	}
	number, ok := strictInt(value)
	if !ok {
		return fmt.Errorf("%s must be an integer", key)
	}
	if allowZero && number == 0 {
		return nil
	}
	if number < minimum || (maximum > 0 && number > maximum) {
		if maximum > 0 {
			return fmt.Errorf("%s must be between %d and %d", key, minimum, maximum)
		}
		return fmt.Errorf("%s must be at least %d", key, minimum)
	}
	return nil
}

func validateStrings(args map[string]any, keys ...string) error {
	for _, key := range keys {
		if err := optionalString(args, key); err != nil {
			return err
		}
	}
	return nil
}

func validateEnum(args map[string]any, key string, values ...string) error {
	value, exists := args[key]
	if !exists {
		return nil
	}
	text, ok := value.(string)
	if !ok {
		return fmt.Errorf("%s must be a string", key)
	}
	for _, candidate := range values {
		if text == candidate {
			return nil
		}
	}
	return fmt.Errorf("%s must be one of %s", key, strings.Join(values, ", "))
}

