		if err := validateStrings(clean, "targetContent", "replacementContent"); err != nil {
			return nil, fmt.Errorf("edit %d %w", index+1, err)
		}
		if err := optionalBool(clean, "allowMultiple"); err != nil {
			return nil, fmt.Errorf("edit %d %w", index+1, err)
		}
		if err := optionalBool(clean, "replaceAll"); err != nil {
			return nil, fmt.Errorf("edit %d %w", index+1, err)
		}
		if err := integerRange(clean, "startLine", 1, 0, false); err != nil {
