var ignoredDirs = map[string]bool{
	".git": true, ".next": true, ".nuxt": true, ".turbo": true, ".cache": true,
	".parcel-cache": true, ".vite": true, "__pycache__": true, ".pytest_cache": true, ".mypy_cache": true,
	".ruff_cache": true, ".venv": true, "venv": true, "env": true, "node_modules": true, "target": true,
	"bin": true, "obj": true, "vendor": true, "Pods": true, "DerivedData": true,
}
var ignoredFileRx = regexp.MustCompile(`(?i)\.(pyc|pyo|class|o|obj|pdb|ilk)$|(^|\.)coverage($|\.)`)

func hiddenName(name string) bool {
	return ignoredDirs[name] || ignoredFileRx.MatchString(name)
}

func walkVisible(workspace, root string, fn func(string, os.DirEntry) bool) error {
	return filepath.WalkDir(root, func(path string, d os.DirEntry, err error) error {
		if err != nil {
			return nil
		}
		if path == root {
			return nil
		}
		if !genericReadVisible(workspace, path) {
			if d.IsDir() {
				return filepath.SkipDir
			}
			return nil
		}
		if d.Type()&os.ModeSymlink != 0 {
			if d.IsDir() {
				return filepath.SkipDir
			}
			return nil
		}
		if hiddenName(d.Name()) {
			if d.IsDir() {
				return filepath.SkipDir
			}
			return nil
		}
		if !fn(path, d) && d.IsDir() {
			return filepath.SkipDir
		}
		return nil
	})
}

