	"syscall"
	"time"
)

var transientFilesystemRetryDelays = []time.Duration{10 * time.Millisecond, 25 * time.Millisecond, 50 * time.Millisecond, 100 * time.Millisecond}

var atomicRenameFile = os.Rename
var atomicRemoveFile = os.Remove

func isTransientFilesystemError(err error) bool {
	if err == nil {
		return false
	}
	if errors.Is(err, fs.ErrPermission) || errors.Is(err, syscall.EACCES) || errors.Is(err, syscall.EBUSY) || errors.Is(err, syscall.EPERM) {
		return true
	}
	if runtime.GOOS == "windows" {
		var errno syscall.Errno
		if errors.As(err, &errno) {
			switch uintptr(errno) {
			case 5, 32, 33:
				return true
			}
		}
	}
	return false
}

func retryTransientFilesystemOperation[T any](operation func() (T, error)) (T, error) {
	var zero T
	for attempt := 0; ; attempt++ {
		value, err := operation()
		if err == nil {
			return value, nil
		}
		if attempt >= len(transientFilesystemRetryDelays) || !isTransientFilesystemError(err) {
			return zero, err
		}
		time.Sleep(transientFilesystemRetryDelays[attempt])
	}
}

func retryTransientFilesystemAction(operation func() error) error {
	_, err := retryTransientFilesystemOperation(func() (struct{}, error) {
		return struct{}{}, operation()
	})
	return err
}

func writeTextFileAtomically(absolutePath, content string) error {
	directory := filepath.Dir(absolutePath)
	basename := filepath.Base(absolutePath)
	if err := os.MkdirAll(directory, 0o755); err != nil {
		return err
	}

	mode := fs.FileMode(0o644)
	if info, err := os.Stat(absolutePath); err == nil {
		mode = info.Mode().Perm()
	}

	temporary, err := os.CreateTemp(directory, "."+basename+".tidecode-*.tmp")
	if err != nil {
		return err
	}
	temporaryPath := temporary.Name()
	cleanup := func() { _ = os.Remove(temporaryPath) }
	defer cleanup()

	if err := temporary.Chmod(mode); err != nil {
		_ = temporary.Close()
		return err
	}
	if _, err := temporary.WriteString(content); err != nil {
		_ = temporary.Close()
		return err
	}
	if err := temporary.Sync(); err != nil {
		_ = temporary.Close()
		return err
	}
	if err := temporary.Close(); err != nil {
		return err
	}

	staged, err := retryTransientFilesystemOperation(func() ([]byte, error) {
		return os.ReadFile(temporaryPath)
	})
	if err != nil {
		return err
	}
	if string(staged) != content {
		return errors.New("Temporary write verification failed: staged file content does not match the requested content.")
	}

	if err := retryTransientFilesystemAction(func() error {
		return atomicRenameFile(temporaryPath, absolutePath)
	}); err != nil {
		return err
	}

	persisted, err := retryTransientFilesystemOperation(func() ([]byte, error) {
		return os.ReadFile(absolutePath)
	})
	if err != nil {
		return err
	}
	if string(persisted) != content {
		return fmt.Errorf("Post-write verification failed for %s: persisted file content does not match the requested content.", absolutePath)
	}
	return nil
}

func removeFileWithRetry(absolutePath string, force bool) error {
	err := retryTransientFilesystemAction(func() error {
		return atomicRemoveFile(absolutePath)
	})
	if force && os.IsNotExist(err) {
		return nil
	}
	return err
}

