func (s *TerminalService) lookup(owner, root string, id int) (*terminalSession, error) {
	workspace, err := resolveWorkspace(root)
	if err != nil {
		return nil, err
	}
	s.mu.Lock()
	sess := s.sessions[id]
	if sess == nil || sess.owner != owner {
		s.mu.Unlock()
		return nil, errors.New("terminal session not found for this caller")
	}
	if !strings.EqualFold(sess.workspace, workspace) {
		s.mu.Unlock()
		return nil, errors.New("terminal session belongs to another workspace")
	}
	sess.mu.Lock()
	sess.lastActivity = time.Now()
	sess.mu.Unlock()
	s.mu.Unlock()
	return sess, nil
}
func (s *TerminalService) Read(owner string, in TerminalReadInput) (ToolResult, error) {
	sess, err := s.lookup(owner, in.WorkspacePath, in.SessionID)
	if err != nil {
		return ToolResult{}, err
	}
	wait := in.WaitSeconds
	if wait < 0 {
		wait = 0
	}
	sess.mu.Lock()
	hasUnread := sess.unread < len(sess.lines)
	sess.mu.Unlock()
	if !hasUnread && wait > 0 {
		before := snapshotTerminal(sess)
		waitForChange(sess, wait, before)
	}
	return sess.result(wait), nil
}
func keyBytes(name string) []byte {
	switch strings.ToUpper(name) {
	case "ENTER":
		return []byte("\r")
	case "TAB":
		return []byte("	")
	case "SPACE":
		return []byte(" ")
	case "BACKSPACE":
		return []byte{0x7f}
	case "ESC":
		return []byte{0x1b}
	case "CTRL_C":
		return []byte{0x03}
	case "CTRL_D":
		return []byte{0x04}
	case "CTRL_L":
		return []byte{0x0c}
	case "UP":
		return []byte("[A")
	case "DOWN":
		return []byte("[B")
	case "RIGHT":
		return []byte("[C")
	case "LEFT":
		return []byte("[D")
	case "HOME":
		return []byte("[H")
	case "END":
		return []byte("[F")
	case "ALT_LEFT":
		return []byte("b")
	case "ALT_RIGHT":
		return []byte("f")
	}
	return nil
}
func (s *TerminalService) Interact(owner string, in TerminalInteractInput) (ToolResult, error) {
	sess, err := s.lookup(owner, in.WorkspacePath, in.SessionID)
	if err != nil {
		return ToolResult{}, err
	}
	sess.mu.Lock()
	completed := sess.state == "completed"
	sess.mu.Unlock()
	if completed {
		if in.Text != "" || len(in.Keys) > 0 {
			return failure("terminal session has already completed; start a new command with execute_terminal"), nil
		}
		return sess.result(0), nil
	}
	before := snapshotTerminal(sess)
	if in.Cols > 0 || in.Rows > 0 {
		cols, rows := in.Cols, in.Rows
		if cols == 0 {
			cols = 220
		}
		if rows == 0 {
			rows = 50
		}
		if err := sess.pty.Resize(cols, rows); err != nil {
			return ToolResult{}, err
		}
	}
	if in.Text != "" {
		if _, err := sess.pty.Write([]byte(in.Text)); err != nil {
			return ToolResult{}, err
		}
	}
	for _, k := range in.Keys {
		b := keyBytes(k)
		if b == nil {
			return failure("unsupported terminal key: " + k), nil
		}
		if _, err := sess.pty.Write(b); err != nil {
			return ToolResult{}, err
		}
	}
	wait := in.WaitSeconds
	if wait < 0 {
		wait = 0
	}
	waitForChange(sess, wait, before)
	return sess.result(wait), nil
}
func (s *TerminalService) Terminate(owner, root string, id int) (ToolResult, error) {
	sess, err := s.lookup(owner, root, id)
	if err != nil {
		return ToolResult{}, err
	}
	s.removeSession(id, sess)
	sess.closeResources(true)
	r := withSubject(success("Terminated terminal session "+strconv.Itoa(id)), "session", strconv.Itoa(id))
	r.Semantics = map[string]any{"session_id": id, "state": "terminated"}
	return r, nil
}
func (s *TerminalService) Close() error {
	s.mu.Lock()
	if s.closed {
		s.mu.Unlock()
		return nil
	}
	s.closed = true
	close(s.stopCh)
	sessions := make([]*terminalSession, 0, len(s.sessions))
	for _, x := range s.sessions {
		sessions = append(sessions, x)
	}
	s.sessions = map[int]*terminalSession{}
	s.mu.Unlock()
	for _, x := range sessions {
		x.closeResources(true)
	}
	<-s.doneCh
	return nil
}

