func truthy(value any) bool {
	if value == nil || isUndefined(value) {
		return false
	}
	switch v := value.(type) {
	case bool:
		return v
	case string:
		return v != ""
	case float64:
		return v != 0 && !math.IsNaN(v)
	case float32:
		return v != 0 && !math.IsNaN(float64(v))
	case int:
		return v != 0
	case int64:
		return v != 0
	}
	return true
}

func numberValue(value any) float64 {
	if value == nil {
		return 0
	}
	if isUndefined(value) {
		return math.NaN()
	}
	switch v := value.(type) {
	case float64:
		return v
	case float32:
		return float64(v)
	case int:
		return float64(v)
	case int8:
		return float64(v)
	case int16:
		return float64(v)
	case int32:
		return float64(v)
	case int64:
		return float64(v)
	case uint:
		return float64(v)
	case uint8:
		return float64(v)
	case uint16:
		return float64(v)
	case uint32:
		return float64(v)
	case uint64:
		return float64(v)
	case bool:
		if v {
			return 1
		}
		return 0
	case string:
		trimmed := strings.TrimSpace(v)
		if trimmed == "" {
			return 0
		}
		if n, err := strconv.ParseFloat(trimmed, 64); err == nil {
			return n
		}
		return math.NaN()
	default:
		return math.NaN()
	}
}

func stringValue(value any) string {
	if isUndefined(value) {
		return "undefined"
	}
	if value == nil {
		return "null"
	}
	switch v := value.(type) {
	case string:
		return v
	case bool:
		if v {
			return "true"
		}
		return "false"
	case float64:
		if math.IsNaN(v) {
			return "NaN"
		}
		if math.IsInf(v, 1) {
			return "Infinity"
		}
		if math.IsInf(v, -1) {
			return "-Infinity"
		}
		return strconv.FormatFloat(v, 'f', -1, 64)
	case int:
		return strconv.Itoa(v)
	case int64:
		return strconv.FormatInt(v, 10)
	}
	if data, err := finalJSONValue(value, 0, map[any]bool{}); err == nil {
		if b, err := json.Marshal(data); err == nil {
			return string(b)
		}
	}
	return "[object Object]"
}

func numericEqual(a, b any) bool {
	na, oka := a.(float64)
	nb, okb := b.(float64)
	if oka && okb {
		return na == nb
	}
	return false
}

func strictEqual(a, b any) bool {
	if isUndefined(a) || isUndefined(b) {
		return isUndefined(a) && isUndefined(b)
	}
	if a == nil || b == nil {
		return a == nil && b == nil
	}
	if numericEqual(a, b) {
		return true
	}
	switch av := a.(type) {
	case string:
		bv, ok := b.(string)
		return ok && av == bv
	case bool:
		bv, ok := b.(bool)
		return ok && av == bv
	case *codeArray:
		bv, ok := b.(*codeArray)
		return ok && av == bv
	case *codeObject:
		bv, ok := b.(*codeObject)
		return ok && av == bv
	}
	return false
}

const maxCodeModeValueDepth = 32

func boundaryCopy(value any, label string, depth int, seen map[any]bool) (any, error) {
	if depth > maxCodeModeValueDepth {
		return nil, cmError("TypeError", fmt.Sprintf("%s exceeds the maximum data depth of %d.", label, maxCodeModeValueDepth), nil)
	}
	if value == nil || isUndefined(value) {
		return value, nil
	}
	switch v := value.(type) {
	case string, bool:
		return v, nil
	case float64:
		if math.IsNaN(v) || math.IsInf(v, 0) {
			return nil, nil
		}
		return v, nil
	case float32:
		n := float64(v)
		if math.IsNaN(n) || math.IsInf(n, 0) {
			return nil, nil
		}
		return n, nil
	case int:
		return float64(v), nil
	case int8:
		return float64(v), nil
	case int16:
		return float64(v), nil
	case int32:
		return float64(v), nil
	case int64:
		return float64(v), nil
	case uint:
		return float64(v), nil
	case uint8:
		return float64(v), nil
	case uint16:
		return float64(v), nil
	case uint32:
		return float64(v), nil
	case uint64:
		return float64(v), nil
	case *codePromise:
		return nil, cmError("TypeError", label+" contains an un-awaited Promise. Await tool calls before using their results.", nil)
	case *codeArray:
		out := make([]any, len(v.items))
		for i := range v.items {
			item, err := boundaryCopy(v.items[i], label, depth+1, seen)
			if err != nil {
				return nil, err
			}
			out[i] = item
		}
		return out, nil
	case *codeObject:
		out := make(map[string]any, len(v.props))
		for key, item := range v.props {
			if blockedCodeModeMembers[key] {
				return nil, cmError("TypeError", fmt.Sprintf("%s contains blocked property '%s'.", label, key), nil)
			}
			copied, err := boundaryCopy(item, label, depth+1, seen)
			if err != nil {
				return nil, err
			}
			out[key] = copied
		}
		return out, nil
	case []any:
		key := any(&v)
		if seen[key] {
			return nil, cmError("TypeError", label+" contains a circular value.", nil)
		}
		out := make([]any, len(v))
		for i := range v {
			item, err := boundaryCopy(v[i], label, depth+1, seen)
			if err != nil {
				return nil, err
			}
			out[i] = item
		}
		return out, nil
	case map[string]any:
		out := make(map[string]any, len(v))
		for key, item := range v {
			if blockedCodeModeMembers[key] {
				return nil, cmError("TypeError", fmt.Sprintf("%s contains blocked property '%s'.", label, key), nil)
			}
			copied, err := boundaryCopy(item, label, depth+1, seen)
			if err != nil {
				return nil, err
			}
			out[key] = copied
		}
		return out, nil
	default:
		return nil, cmError("TypeError", label+" must contain data values only.", nil)
	}
}

func internalizeData(value any) any {
	switch v := value.(type) {
	case []any:
		out := newCodeArray()
		out.items = make([]any, len(v))
		for i, item := range v {
			out.items[i] = internalizeData(item)
		}
		return out
	case map[string]any:
		out := newCodeObject()
		for key, item := range v {
			out.props[key] = internalizeData(item)
		}
		return out
	default:
		return value
	}
}

func hostData(value any, label string) (any, error) {
	copied, err := boundaryCopy(value, label, 0, map[any]bool{})
	if err != nil {
		return nil, err
	}
	return finalJSONValue(copied, 0, map[any]bool{})
}

func finalJSONValue(value any, depth int, seen map[any]bool) (any, error) {
	if depth > maxCodeModeValueDepth {
		return nil, cmError("TypeError", "Code Mode result exceeds the maximum data depth.", nil)
	}
	if isUndefined(value) {
		return codeUndefined, nil
	}
	if value == nil {
		return nil, nil
	}
	switch v := value.(type) {
	case string, bool:
		return v, nil
	case float64:
		if math.IsNaN(v) || math.IsInf(v, 0) {
			return nil, nil
		}
		return v, nil
	case *codeArray:
		out := make([]any, len(v.items))
		for i, item := range v.items {
			converted, err := finalJSONValue(item, depth+1, seen)
			if err != nil {
				return nil, err
			}
			if isUndefined(converted) {
				converted = nil
			}
			out[i] = converted
		}
		return out, nil
	case *codeObject:
		out := make(map[string]any, len(v.props))
		for key, item := range v.props {
			if blockedCodeModeMembers[key] {
				return nil, cmError("TypeError", fmt.Sprintf("Code Mode result contains blocked property '%s'.", key), nil)
			}
			converted, err := finalJSONValue(item, depth+1, seen)
			if err != nil {
				return nil, err
			}
			if isUndefined(converted) {
				continue
			}
			out[key] = converted
		}
		return out, nil
	case []any:
		out := make([]any, len(v))
		for i, item := range v {
			converted, err := finalJSONValue(item, depth+1, seen)
			if err != nil {
				return nil, err
			}
			if isUndefined(converted) {
				converted = nil
			}
			out[i] = converted
		}
		return out, nil
	case map[string]any:
		out := make(map[string]any, len(v))
		for key, item := range v {
			if blockedCodeModeMembers[key] {
				return nil, cmError("TypeError", fmt.Sprintf("Code Mode result contains blocked property '%s'.", key), nil)
			}
			converted, err := finalJSONValue(item, depth+1, seen)
			if err != nil {
				return nil, err
			}
			if isUndefined(converted) {
				continue
			}
			out[key] = converted
		}
		return out, nil
	default:
		return nil, cmError("TypeError", "Code Mode result must contain data values only.", nil)
	}
}

func safeErrorValue(err error) map[string]any {
	if runtimeErr, ok := err.(*codeModeRuntimeError); ok {
		return map[string]any{"name": runtimeErr.Kind, "message": runtimeErr.Message}
	}
	if thrown, ok := err.(*programThrow); ok {
		if record, ok := thrown.value.(map[string]any); ok {
			name, _ := record["name"].(string)
			message, _ := record["message"].(string)
			if name == "" {
				name = "Error"
			}
			return map[string]any{"name": name, "message": message}
		}
		return map[string]any{"name": "Error", "message": stringValue(thrown.value)}
	}
	return map[string]any{"name": "Error", "message": err.Error()}
}

