type codeModeCallable struct {
	fn     *codeFunction
	native *nativeFunction
}

func asCodeModeCallable(value any) (codeModeCallable, bool) {
	switch fn := value.(type) {
	case *codeFunction:
		return codeModeCallable{fn: fn}, true
	case *nativeFunction:
		return codeModeCallable{native: fn}, true
	default:
		return codeModeCallable{}, false
	}
}
func (i *codeModeInterpreter) invokeArrayCallback(callback codeModeCallable, args []any, node ast.Node, resolveAsync bool) (any, error) {
	if callback.native != nil {
		return callback.native.invoke(args, node)
	}
	if callback.fn.async {
		promise := startCodePromise(func() (any, error) { return i.invokeFunction(callback.fn, args, node) })
		if resolveAsync {
			return promise.await()
		}
		return promise, nil
	}
	return i.invokeFunction(callback.fn, args, node)
}

