var supportedBinaryOperators = map[string]bool{
	"+": true, "-": true, "*": true, "/": true, "%": true, "**": true,
	"<": true, "<=": true, ">": true, ">=": true, "==": true, "!=": true, "===": true, "!==": true,
	"|": true, "&": true, "^": true, "<<": true, ">>": true, ">>>": true, "in": true,
