}

var supportedAssignmentOperators = map[string]bool{
	"=": true, "+=": true, "-=": true, "*=": true, "/=": true, "%=": true, "**=": true, "|=": true, "&=": true, "^=": true,
	"<<=": true, ">>=": true, ">>>=": true, "&&=": true, "||=": true, "??=": true,
}

type parsedCodeModeProgram struct {
	statements []ast.Statement
	fileSet    *file.FileSet
}

func parseCodeModeProgram(source string) (*parsedCodeModeProgram, error) {
	prefix := "async function __tidecode_code_mode__(){\n"
	wrapped := prefix + source + "\n}"
	files := new(file.FileSet)
	program, err := parser.ParseFile(files, "codemode.js", wrapped, 0)
	if err != nil {
		runtimeErr := cmError("ParseError", err.Error(), nil)
		switch parseErr := err.(type) {
		case parser.ErrorList:
			if len(parseErr) > 0 {
				line := parseErr[0].Position.Line - 1
				if line < 1 {
					line = 1
				}
				runtimeErr.Message = parseErr[0].Message
				runtimeErr.Position = &CodeModePosition{Line: line, Column: max(1, parseErr[0].Position.Column)}
			}
		case *parser.Error:
			line := parseErr.Position.Line - 1
			if line < 1 {
				line = 1
			}
			runtimeErr.Message = parseErr.Message
			runtimeErr.Position = &CodeModePosition{Line: line, Column: max(1, parseErr.Position.Column)}
		}
		return nil, runtimeErr
	}
	if len(program.Body) != 1 {
		return nil, cmError("ParseError", "Code Mode source did not parse as a program.", nil)
	}
	declaration, ok := program.Body[0].(*ast.FunctionDeclaration)
	if !ok || declaration.Function == nil || declaration.Function.Body == nil {
		return nil, cmError("ParseError", "Code Mode source did not parse as a program.", nil)
	}
	for _, statement := range declaration.Function.Body.List {
		if err := validateCodeModeNode(statement); err != nil {
			return nil, err
		}
	}
	return &parsedCodeModeProgram{statements: declaration.Function.Body.List, fileSet: files}, nil
}

func unsupportedCodeModeNode(node ast.Node, detail string) error {
	if detail == "" {
		typ := reflect.TypeOf(node)
		name := "unknown"
		if typ != nil {
			if typ.Kind() == reflect.Pointer {
				typ = typ.Elem()
			}
			name = typ.Name()
		}
		detail = fmt.Sprintf("Syntax '%s' is not supported in Tidecode Code Mode.", name)
	}
	return cmError("UnsupportedSyntax", detail, node, "Use JavaScript-style orchestration with variables, loops, functions, await, try/catch, and tools.* capabilities.")
}

func validateCodeModeNode(node ast.Node) error {
	if node == nil {
		return nil
	}
	switch n := node.(type) {
	case *ast.ExpressionStatement, *ast.EmptyStatement, *ast.BlockStatement,
		*ast.VariableStatement, *ast.LexicalDeclaration, *ast.Binding,
		*ast.Identifier, *ast.StringLiteral, *ast.NumberLiteral, *ast.BooleanLiteral, *ast.NullLiteral,
		*ast.ArrayLiteral, *ast.ObjectLiteral, *ast.PropertyShort, *ast.SpreadElement,
		*ast.DotExpression, *ast.BracketExpression, *ast.CallExpression, *ast.NewExpression,
		*ast.ArrowFunctionLiteral, *ast.AwaitExpression, *ast.ConditionalExpression,
		*ast.SequenceExpression, *ast.TemplateLiteral, *ast.TemplateElement,
		*ast.IfStatement, *ast.SwitchStatement, *ast.CaseStatement,
		*ast.ForStatement, *ast.ForOfStatement, *ast.ForInStatement,
		*ast.ForLoopInitializerExpression, *ast.ForLoopInitializerLexicalDecl, *ast.ForLoopInitializerVarDeclList,
		*ast.ForIntoExpression, *ast.ForIntoVar, *ast.ForDeclaration,
		*ast.WhileStatement, *ast.DoWhileStatement, *ast.BranchStatement,
		*ast.ReturnStatement, *ast.ThrowStatement, *ast.TryStatement, *ast.CatchStatement,
		*ast.FunctionDeclaration, *ast.ArrayPattern, *ast.ObjectPattern, *ast.ExpressionBody,
		*ast.Optional, *ast.OptionalChain:
		_ = n
	case *ast.FunctionLiteral:
		if n.Generator {
			return unsupportedCodeModeNode(node, "Generator functions are not supported in Tidecode Code Mode.")
		}
	case *ast.PropertyKeyed:
		if fmt.Sprint(n.Kind) != "value" {
			return unsupportedCodeModeNode(node, "Object getters, setters, and method syntax are not supported. Use function-valued properties instead.")
		}
	case *ast.RegExpLiteral:
		return unsupportedCodeModeNode(node, "Regular expression literals are not supported in Tidecode Code Mode. Use string operations or tools.grep instead.")
	case *ast.UnaryExpression:
		operator := n.Operator.String()
		if operator == "delete" {
			return unsupportedCodeModeNode(node, "delete is not supported in Tidecode Code Mode.")
		}
		if operator != "!" && operator != "+" && operator != "-" && operator != "~" && operator != "typeof" && operator != "void" && operator != "++" && operator != "--" {
			return unsupportedCodeModeNode(node, fmt.Sprintf("Unary operator '%s' is not supported.", operator))
		}
	case *ast.BinaryExpression:
		if !supportedBinaryOperators[n.Operator.String()] {
			return unsupportedCodeModeNode(node, fmt.Sprintf("Binary operator '%s' is not supported in Tidecode Code Mode.", n.Operator.String()))
		}
	case *ast.AssignExpression:
		if !supportedAssignmentOperators[n.Operator.String()] {
			return unsupportedCodeModeNode(node, fmt.Sprintf("Assignment operator '%s' is not supported in Tidecode Code Mode.", n.Operator.String()))
		}
	default:
		return unsupportedCodeModeNode(node, "")
	}
	if literal, ok := node.(*ast.TemplateLiteral); ok && literal.Tag != nil {
		return unsupportedCodeModeNode(node, "Tagged template literals are not supported in Tidecode Code Mode.")
	}
	if call, ok := node.(*ast.CallExpression); ok {
		if id, ok := call.Callee.(*ast.Identifier); ok {
			name := id.Name.String()
			if name == "eval" || name == "Function" {
				return unsupportedCodeModeNode(node, name+" is not available in Tidecode Code Mode.")
			}
		}
	}
	return validateCodeModeChildren(node)
}

func validateCodeModeChildren(node ast.Node) error {
	value := reflect.ValueOf(node)
	if value.Kind() == reflect.Pointer {
		value = value.Elem()
	}
	if !value.IsValid() || value.Kind() != reflect.Struct {
		return nil
	}
	typ := value.Type()
	for i := 0; i < value.NumField(); i++ {
		fieldInfo := typ.Field(i)
		if fieldInfo.PkgPath != "" || fieldInfo.Name == "DeclarationList" || fieldInfo.Name == "Source" || fieldInfo.Name == "File" {
			continue
		}
		if err := validateCodeModeChildValue(value.Field(i)); err != nil {
			return err
		}
	}
	return nil
}

func validateCodeModeChildValue(value reflect.Value) error {
	if !value.IsValid() {
		return nil
	}
	if value.Kind() == reflect.Interface {
		if value.IsNil() {
			return nil
		}
		if node, ok := value.Interface().(ast.Node); ok {
			return validateCodeModeNode(node)
		}
		return validateCodeModeChildValue(value.Elem())
	}
	if value.Kind() == reflect.Pointer {
		if value.IsNil() {
			return nil
		}
		if value.CanInterface() {
			if node, ok := value.Interface().(ast.Node); ok {
				return validateCodeModeNode(node)
			}
		}
		return nil
	}
	if value.Kind() == reflect.Slice {
		for i := 0; i < value.Len(); i++ {
			if err := validateCodeModeChildValue(value.Index(i)); err != nil {
				return err
			}
		}
		return nil
	}
	if value.Kind() == reflect.Struct && value.CanAddr() && value.Addr().CanInterface() {
		if node, ok := value.Addr().Interface().(ast.Node); ok {
			return validateCodeModeNode(node)
		}
	}
	return nil
}

type codeModeInterpreter struct {
	tools     *codeModeToolRuntime
	payloads  *payloadNamespace
	limits    CodeModeLimits
	ctx       context.Context
	files     *file.FileSet
	mu        sync.Mutex
	steps     int
	callDepth int
	global    *environment
}

func newCodeModeInterpreter(ctx context.Context, tools *codeModeToolRuntime, payloads map[string]string, limits CodeModeLimits, files *file.FileSet) *codeModeInterpreter {
	copiedPayloads := make(map[string]string, len(payloads))
	for key, value := range payloads {
		copiedPayloads[key] = value
	}
	i := &codeModeInterpreter{tools: tools, payloads: &payloadNamespace{values: copiedPayloads}, limits: limits, ctx: ctx, files: files, global: newEnvironment(nil, true)}
	i.installGlobals()
	return i
}

func (i *codeModeInterpreter) position(node ast.Node) *CodeModePosition {
	if node == nil || i.files == nil {
		return nil
	}
	pos := i.files.Position(node.Idx0())
	line := pos.Line - 1
	if line < 1 {
		line = 1
	}
	column := pos.Column
	if column < 1 {
		column = 1
	}
	return &CodeModePosition{Line: line, Column: column}
}

func (i *codeModeInterpreter) attach(err error, node ast.Node) error {
	if runtimeErr, ok := err.(*codeModeRuntimeError); ok && runtimeErr.Position == nil {
		runtimeErr.Position = i.position(node)
		if runtimeErr.Node == nil {
			runtimeErr.Node = node
		}
	}
	return err
}

func (i *codeModeInterpreter) tick(node ast.Node) error {
	i.mu.Lock()
	i.steps++
	steps := i.steps
	i.mu.Unlock()
	if steps > i.limits.MaxSteps {
		return i.attach(cmError("StepLimitExceeded", fmt.Sprintf("Code Mode exceeded the %d-step limit.", i.limits.MaxSteps), node), node)
	}
	select {
	case <-i.ctx.Done():
		if errors.Is(i.ctx.Err(), context.DeadlineExceeded) {
			return i.attach(cmError("TimeoutExceeded", fmt.Sprintf("Code Mode exceeded the %dms timeout.", i.limits.Timeout.Milliseconds()), node), node)
		}
		return i.attach(cmError("Cancelled", "Code Mode execution was aborted.", node), node)
	default:
		return nil
	}
}

func (i *codeModeInterpreter) execute(statements []ast.Statement) (any, int, error) {
	var value any = codeUndefined
	err := i.executeStatements(statements, i.global)
	if signal, ok := err.(*returnSignal); ok {
		value = signal.value
		if promise, ok := value.(*codePromise); ok {
			value, err = promise.await()
		} else {
			err = nil
		}
	}
	i.mu.Lock()
	steps := i.steps
	i.mu.Unlock()
	if err != nil {
		return nil, steps, i.attach(err, nil)
	}
	final, err := finalJSONValue(value, 0, map[any]bool{})
	if err != nil {
		return nil, steps, err
	}
	return final, steps, nil
}

