// decodeRedundantTripleQuoteDelimiterEscapes removes one generated escaping
// layer from a pseudo triple-quoted body only when every occurrence of the
// matching delimiter quote is escaped. That is the characteristic shape of
// source accidentally emitted as className=\\\"card\\\" inside a \"\"\"...\"\"\"
// payload. If the body already contains any real delimiter quote, preserve it
// byte-for-byte so intentional escapes inside source strings are not changed.
func decodeRedundantTripleQuoteDelimiterEscapes(body string, delimiter byte) string {
	escapedCount := 0
	hasUnescaped := false
	for i := 0; i < len(body); i++ {
		if body[i] != delimiter {
			continue
		}
		if isEscapedAt(body, i) {
			escapedCount++
		} else {
			hasUnescaped = true
		}
	}
	if escapedCount == 0 || hasUnescaped {
		return body
	}

	var out strings.Builder
	out.Grow(len(body))
	for i := 0; i < len(body); {
		if body[i] != '\\' {
			out.WriteByte(body[i])
			i++
			continue
		}

		runStart := i
		for i < len(body) && body[i] == '\\' {
			i++
		}
		runLength := i - runStart
		if i < len(body) && body[i] == delimiter && runLength%2 == 1 {
			out.WriteString(strings.Repeat("\\", runLength-1))
			out.WriteByte(delimiter)
			i++
			continue
		}
		out.WriteString(body[runStart:i])
	}
	return out.String()
}

func repairPythonTripleQuotedStringsGo(code string) string {
