				quote = ch
			}
			i++
		}

		if openingIndex < 0 {
			out.WriteString(code[cursor:])
			break
		}

		bodyStart := openingIndex + len(delimiter)
		closingIndex := -1
		searchFrom := bodyStart
		for searchFrom <= len(code)-len(delimiter) {
