	"image/png"
	"os"

	xdraw "golang.org/x/image/draw"
	_ "golang.org/x/image/webp"
)

const maxImageSourceBytes = 64 << 20
const maxImageOutputBytes = 4 << 20
const maxImageLongEdge = 4096
const maxImagePixels int64 = 40_000_000

func imageMIMEType(format string) string {
	switch format {
	case "png":
		return "image/png"
	case "jpeg":
		return "image/jpeg"
	case "gif":
		return "image/gif"
	case "webp":
		return "image/webp"
	default:
		return ""
	}
}

func detectSupportedImage(path string) (image.Config, string, bool) {
	f, err := os.Open(path)
	if err != nil {
		return image.Config{}, "", false
	}
	defer f.Close()
	cfg, format, err := image.DecodeConfig(f)
	if err != nil || imageMIMEType(format) == "" {
		return image.Config{}, "", false
	}
	return cfg, format, true
}

func scaledDimensions(width, height, maxEdge int) (int, int) {
	if width <= maxEdge && height <= maxEdge {
		return width, height
	}
	if width >= height {
		return maxEdge, maxInt(1, height*maxEdge/width)
	}
	return maxInt(1, width*maxEdge/height), maxEdge
}

func maxInt(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func resizeImage(src image.Image, width, height int) image.Image {
	bounds := src.Bounds()
	if bounds.Dx() == width && bounds.Dy() == height {
		return src
	}
	dst := image.NewNRGBA(image.Rect(0, 0, width, height))
	xdraw.CatmullRom.Scale(dst, dst.Bounds(), src, bounds, xdraw.Over, nil)
	return dst
}

func encodePNG(src image.Image) ([]byte, error) {
	var buf bytes.Buffer
	encoder := png.Encoder{CompressionLevel: png.BestCompression}
	if err := encoder.Encode(&buf, src); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

func flattenForJPEG(src image.Image) image.Image {
	bounds := src.Bounds()
	dst := image.NewRGBA(image.Rect(0, 0, bounds.Dx(), bounds.Dy()))
	draw.Draw(dst, dst.Bounds(), image.NewUniform(color.White), image.Point{}, draw.Src)
	draw.Draw(dst, dst.Bounds(), src, bounds.Min, draw.Over)
	return dst
}

func encodeJPEG(src image.Image, quality int) ([]byte, error) {
	var buf bytes.Buffer
	if err := jpeg.Encode(&buf, flattenForJPEG(src), &jpeg.Options{Quality: quality}); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

func compressImage(src image.Image, originalFormat string, width, height int) ([]byte, string, int, int, error) {
	width, height = scaledDimensions(width, height, maxImageLongEdge)
	working := resizeImage(src, width, height)

	if originalFormat == "png" {
		encoded, err := encodePNG(working)
		if err != nil {
			return nil, "", 0, 0, err
		}
		if len(encoded) <= maxImageOutputBytes {
			return encoded, "image/png", width, height, nil
		}
	}

	qualities := []int{90, 82, 74, 66, 58}
	for attempts := 0; attempts < 8; attempts++ {
		for _, quality := range qualities {
			encoded, err := encodeJPEG(working, quality)
			if err != nil {
				return nil, "", 0, 0, err
			}
			if len(encoded) <= maxImageOutputBytes {
				return encoded, "image/jpeg", width, height, nil
			}
		}
		nextWidth := maxInt(1, width*4/5)
		nextHeight := maxInt(1, height*4/5)
		if nextWidth == width && nextHeight == height {
			break
		}
		width, height = nextWidth, nextHeight
		working = resizeImage(working, width, height)
	}
	return nil, "", 0, 0, fmt.Errorf("image could not be compressed below %d bytes", maxImageOutputBytes)
}

func readImageFile(target, rel string, sourceBytes int64, cfg image.Config, format string) (ToolResult, error) {
	if sourceBytes > maxImageSourceBytes {
		return failure(fmt.Sprintf("Image exceeds source read limit of %d bytes", maxImageSourceBytes)), nil
	}
	if cfg.Width <= 0 || cfg.Height <= 0 || int64(cfg.Width)*int64(cfg.Height) > maxImagePixels {
		return failure(fmt.Sprintf("Image dimensions exceed safe decode limit of %d pixels", maxImagePixels)), nil
	}
	data, err := os.ReadFile(target)
	if err != nil {
		return ToolResult{}, err
	}
	mimeType := imageMIMEType(format)
	output := data
	outputWidth, outputHeight := cfg.Width, cfg.Height
	transformed := len(data) > maxImageOutputBytes || cfg.Width > maxImageLongEdge || cfg.Height > maxImageLongEdge
	if transformed {
		decoded, decodedFormat, err := image.Decode(bytes.NewReader(data))
		if err != nil {
			return failure("Cannot decode image file: " + rel), nil
		}
		if imageMIMEType(decodedFormat) != "" {
			format = decodedFormat
		}
		output, mimeType, outputWidth, outputHeight, err = compressImage(decoded, format, cfg.Width, cfg.Height)
		if err != nil {
			return failure("Cannot prepare image for model input: " + err.Error()), nil
		}
	}

	body := fmt.Sprintf("Image %s: %dx%d, %s, %d bytes", rel, outputWidth, outputHeight, mimeType, len(output))
	r := withSubject(withBody(success("Read image "+rel), body), "file", rel)
	r.Media = []MediaPayload{{Kind: "image", MIMEType: mimeType, Data: output}}
	r.Semantics = map[string]any{
		"is_directory":       false,
		"media_type":         "image",
		"mime_type":          mimeType,
		"original_mime_type": imageMIMEType(format),
		"original_width":     cfg.Width,
		"original_height":    cfg.Height,
		"width":              outputWidth,
		"height":             outputHeight,
		"original_bytes":     sourceBytes,
		"output_bytes":       len(output),
		"compressed":         transformed,
		"resized":            outputWidth != cfg.Width || outputHeight != cfg.Height,
