package tidecode

import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"sync"
	"time"
)

const MemoryIndexPath = ".tidecode/memory/MEMORY.md"
const maxMemoryBytes = 512 << 10

var memoryLocks sync.Map

func workspaceLock(root string) *sync.Mutex {
	v, _ := memoryLocks.LoadOrStore(strings.ToLower(root), &sync.Mutex{})
	return v.(*sync.Mutex)
}

var logicalIDRx = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$`)
var windowsReserved = regexp.MustCompile(`(?i)^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])$`)

func validLogicalID(v string) bool {
	return v != "" && v == strings.TrimSpace(v) && logicalIDRx.MatchString(v) && !strings.Contains(v, "..") && !windowsReserved.MatchString(v)
}
func memoryRelative(folder, name string) (string, error) {
	if !validLogicalID(folder) || !validLogicalID(name) {
		return "", fmt.Errorf("memory uses logical folder and name identifiers, not filesystem paths")
	}
	name = strings.TrimSuffix(name, ".md")
	return fmt.Sprintf(".tidecode/memory/folders/%s/%s.md", folder, name), nil
}

type MemoryInput struct {
	WorkspacePath string `json:"workspace_path,omitempty"`
	Action        string `json:"action"`
	Folder        string `json:"folder,omitempty"`
	Name          string `json:"name,omitempty"`
	Title         string `json:"title,omitempty"`
	Content       string `json:"content,omitempty"`
	OldText       string `json:"old_text,omitempty"`
	NewText       string `json:"new_text,omitempty"`
	Path          string `json:"path,omitempty"`
}
type MemoryService struct{}

func (MemoryService) Execute(in MemoryInput) (ToolResult, error) {
	root, err := resolveWorkspace(in.WorkspacePath)
	if err != nil {
		return ToolResult{}, err
	}
	if in.Path != "" {
		return failure("memory accepts only logical folder and name; arbitrary path is not allowed"), nil
	}
	mu := workspaceLock(root)
	mu.Lock()
	defer mu.Unlock()
	if in.Action == "read_index" {
		return readMemoryIndex(root), nil
	}
	rel, err := memoryRelative(in.Folder, in.Name)
	if err != nil {
		return failure(err.Error()), nil
	}
	target, err := ensureManagedPathNoLinks(root, rel)
	if err != nil {
		return failure(err.Error()), nil
	}
	switch in.Action {
	case "write":
		content := strings.TrimSpace(normalizeText(in.Content))
		if in.Title != "" {
			content = "# " + strings.TrimSpace(in.Title) + "\n\n" + content
		}
		if content != "" {
			content += "\n"
		}
		if len(content) > maxMemoryBytes {
			return failure("memory content exceeds 512 KiB"), nil
		}
		op := "created"
		if _, e := os.Stat(target); e == nil {
			op = "updated"
		}
		if err := os.MkdirAll(filepath.Dir(target), 0o755); err != nil {
			return ToolResult{}, err
		}
		if err := os.WriteFile(target, []byte(content), 0o600); err != nil {
			return ToolResult{}, err
		}
		if err := rebuildMemoryIndex(root); err != nil {
			return ToolResult{}, err
		}
		r := withSubject(withBody(success("Memory "+op+": "+filepath.ToSlash(rel)), op+": "+filepath.ToSlash(rel)), "memory", filepath.ToSlash(rel))
		r.Semantics = map[string]any{"operation": in.Action}
		return r, nil
	case "read":
		b, err := os.ReadFile(target)
		if err != nil {
			if os.IsNotExist(err) {
				return failure("Memory not found"), nil
			}
			return ToolResult{}, err
		}
		r := withSubject(withBody(success("Read memory "+filepath.ToSlash(rel)), string(b)), "memory", filepath.ToSlash(rel))
		r.Semantics = map[string]any{"operation": "read"}
		return r, nil
	case "edit":
		b, err := os.ReadFile(target)
		if err != nil {
			return failure("Memory not found"), nil
		}
		text := string(b)
		if in.OldText == "" {
			return failure("old_text is required for memory edit"), nil
		}
		if strings.Count(text, in.OldText) != 1 {
			return failure("old_text must match memory content exactly once"), nil
		}
		text = strings.Replace(text, in.OldText, in.NewText, 1)
		if len(text) > maxMemoryBytes {
			return failure("memory content exceeds 512 KiB"), nil
		}
		if err := os.WriteFile(target, []byte(text), 0o600); err != nil {
			return ToolResult{}, err
		}
		_ = rebuildMemoryIndex(root)
		return withBody(success("Edited memory "+filepath.ToSlash(rel)), "updated: "+filepath.ToSlash(rel)), nil
	case "forget":
		if err := os.Remove(target); err != nil && !os.IsNotExist(err) {
			return ToolResult{}, err
		}
		_ = rebuildMemoryIndex(root)
		return withBody(success("Forgot memory "+filepath.ToSlash(rel)), "forgotten: "+filepath.ToSlash(rel)), nil
	default:
		return failure("memory action must be read, write, edit, forget, or read_index"), nil
	}
}

func readMemoryIndex(root string) ToolResult {
	p, err := ensureManagedPathNoLinks(root, MemoryIndexPath)
	if err != nil {
		return failure(err.Error())
	}
	b, err := os.ReadFile(p)
	if os.IsNotExist(err) {
		return withSubject(withBody(success("Memory index is empty"), "# Memory Index\n\nNo memories recorded.\n"), "memory_index", MemoryIndexPath)
	}
	if err != nil {
		return failure(err.Error())
	}
	return withSubject(withBody(success("Read memory index"), string(b)), "memory_index", MemoryIndexPath)
}

func rebuildMemoryIndex(root string) error {
	dir, err := ensureManagedPathNoLinks(root, ".tidecode/memory/folders")
	if err != nil {
		return err
	}
	type entry struct {
		rel, title string
		mtime      time.Time
	}
	entries := []entry{}
	_ = filepath.WalkDir(dir, func(p string, d os.DirEntry, e error) error {
		if e != nil {
			return nil
		}
		if d.IsDir() {
			return nil
		}
		if strings.EqualFold(filepath.Ext(p), ".md") {
			b, _ := os.ReadFile(p)
			title := ""
			for _, line := range strings.Split(string(b), "\n") {
				if strings.HasPrefix(line, "# ") {
					title = strings.TrimSpace(strings.TrimPrefix(line, "# "))
					break
				}
			}
			st, _ := os.Stat(p)
			rel := filepath.ToSlash(mustRel(filepath.Join(root, ".tidecode", "memory", "folders"), p))
			entries = append(entries, entry{rel, title, st.ModTime()})
		}
		return nil
	})
	sort.Slice(entries, func(i, j int) bool { return entries[i].rel < entries[j].rel })
	var b strings.Builder
	b.WriteString("# Memory Index\n\n")
	if len(entries) == 0 {
		b.WriteString("No memories recorded.\n")
	} else {
		for _, e := range entries {
			label := e.rel
			if e.title != "" {
				label += " - " + e.title
			}
			b.WriteString(fmt.Sprintf("- %s (%s)\n", label, e.mtime.UTC().Format(time.RFC3339)))
		}
	}
	index, _ := ensureManagedPathNoLinks(root, MemoryIndexPath)
	if err := os.MkdirAll(filepath.Dir(index), 0o755); err != nil {
		return err
	}
	return os.WriteFile(index, []byte(b.String()), 0o600)
}

