package tidecode

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
)

type applyPatchHunk struct {
	Type     string
	Path     string
	MovePath string
	Contents string
	Chunks   []applyPatchUpdateChunk
}

type applyPatchContextMapping struct {
	NewLineIndex int
	OldLineIndex int
}

type applyPatchUpdateChunk struct {
	ChangeContext   string
	OffsetStartLine int
	OffsetLineCount int
	IsEndOfFile     bool
	NewLines        []string
	OldLines        []string
	ContextMappings []applyPatchContextMapping
}

type parsedApplyPatch struct {
	Hunks []applyPatchHunk
}

type parsedPatchHeader struct {
	FilePath string
	MovePath string
	Next     int
	Type     string
}

var unifiedPatchHeaderRx = regexp.MustCompile("^-(\\d+)(?:,(\\d+))?(?:\\s+\\+\\d+(?:,\\d+)?)?(?:\\s*@@)?(.*)$")

func outerPatchMarkerKind(line string) string {
	compact := strings.ReplaceAll(strings.TrimSpace(line), "*", "")
	compact = strings.Join(strings.Fields(compact), "")
	switch compact {
	case "BeginPatch":
		return "begin"
	case "EndPatch":
		return "end"
	default:
		return ""
	}
}

func normalizeApplyPatchInput(value string) (string, error) {
	if strings.TrimSpace(value) == "" {
		return "", fmt.Errorf("patch requires a non-empty raw patch string")
	}
	normalized := normalizeText(value)
	lines := strings.Split(strings.TrimSpace(normalized), "\n")

	leading := 0
	hasCanonicalBegin := false
	for leading < len(lines) && outerPatchMarkerKind(lines[leading]) == "begin" {
		if strings.TrimSpace(lines[leading]) == "*** Begin Patch" {
			hasCanonicalBegin = true
		}
		leading++
	}
	if hasCanonicalBegin && leading > 0 {
		lines = append([]string{"*** Begin Patch"}, lines[leading:]...)
	}

	trailingStart := len(lines)
	hasCanonicalEnd := false
	for trailingStart > 0 && outerPatchMarkerKind(lines[trailingStart-1]) == "end" {
		if strings.TrimSpace(lines[trailingStart-1]) == "*** End Patch" {
			hasCanonicalEnd = true
		}
		trailingStart--
	}
	if hasCanonicalEnd && trailingStart < len(lines) {
		lines = append(append([]string{}, lines[:trailingStart]...), "*** End Patch")
	}
	return strings.Join(lines, "\n"), nil
}

func isStandardPatchBoundary(line string) bool {
	return line == "*** End Patch" ||
		strings.HasPrefix(line, "*** Add File: ") ||
		strings.HasPrefix(line, "*** Delete File: ") ||
		strings.HasPrefix(line, "*** Update File: ")
}

func parseStandardPatchHeader(lines []string, index int) (*parsedPatchHeader, error) {
	if index < 0 || index >= len(lines) {
		return nil, nil
	}
	line := lines[index]
	definitions := []struct {
		Prefix string
