	for index < len(lines) && !isStandardPatchBoundary(lines[index]) {
		if !strings.HasPrefix(lines[index], "+") {
			return "", index, fmt.Errorf("Invalid add-file line: %s", lines[index])
		}
		content = append(content, strings.TrimPrefix(lines[index], "+"))
		index++
	}
	return strings.Join(content, "\n"), index, nil
}

func parsePatchChunkHeader(line string) (changeContext string, startLine, lineCount int) {
	headerText := strings.TrimSpace(strings.TrimPrefix(line, "@@"))
	match := unifiedPatchHeaderRx.FindStringSubmatch(headerText)
	if len(match) > 1 && match[1] != "" {
		startLine, _ = strconv.Atoi(match[1])
		lineCount = 1
		if len(match) > 2 && match[2] != "" {
			lineCount, _ = strconv.Atoi(match[2])
		}
		return "", startLine, lineCount
	}
	return headerText, 0, 0
}

func createApplyPatchUpdateChunk(lines []string, start int, changeContext string, startLine, lineCount int) (applyPatchUpdateChunk, int, error) {
	chunk := applyPatchUpdateChunk{
		ChangeContext:   changeContext,
		OffsetStartLine: startLine,
		OffsetLineCount: lineCount,
		NewLines:        []string{},
		OldLines:        []string{},
		ContextMappings: []applyPatchContextMapping{},
	}
	index := start
	for index < len(lines) && !strings.HasPrefix(lines[index], "@@") && !isStandardPatchBoundary(lines[index]) {
		line := lines[index]
		if line == "*** End of File" {
			if len(chunk.OldLines) == 0 && len(chunk.NewLines) == 0 {
				return chunk, index, fmt.Errorf("Update hunk does not contain any lines")
			}
			chunk.IsEndOfFile = true
			index++
			break
		}
		switch {
		case line == "":
			chunk.OldLines = append(chunk.OldLines, "")
			chunk.NewLines = append(chunk.NewLines, "")
		case strings.HasPrefix(line, " "):
			chunk.ContextMappings = append(chunk.ContextMappings, applyPatchContextMapping{NewLineIndex: len(chunk.NewLines), OldLineIndex: len(chunk.OldLines)})
			value := line[1:]
			chunk.OldLines = append(chunk.OldLines, value)
			chunk.NewLines = append(chunk.NewLines, value)
		case strings.HasPrefix(line, "-"):
			chunk.OldLines = append(chunk.OldLines, line[1:])
		case strings.HasPrefix(line, "+"):
			chunk.NewLines = append(chunk.NewLines, line[1:])
		default:
			return chunk, index, fmt.Errorf("Invalid patch body line: %s", line)
		}
		index++
	}
	if len(chunk.OldLines) == 0 && len(chunk.NewLines) == 0 {
		return chunk, index, fmt.Errorf("Update hunk does not contain any lines")
	}
	return chunk, index, nil
}

func parseUpdatedPatchFile(lines []string, start int) ([]applyPatchUpdateChunk, int, error) {
	chunks := []applyPatchUpdateChunk{}
	index := start
	for index < len(lines) && !isStandardPatchBoundary(lines[index]) {
		if len(chunks) == 0 && strings.TrimSpace(lines[index]) == "" {
			index++
			continue
		}
		hasHeader := strings.HasPrefix(lines[index], "@@")
		if !hasHeader && len(chunks) > 0 {
			return nil, index, fmt.Errorf("Expected \"@@\" chunk header, found: %s", lines[index])
		}
		changeContext := ""
		startLine, lineCount := 0, 0
		if hasHeader {
			changeContext, startLine, lineCount = parsePatchChunkHeader(lines[index])
			index++
		}
		chunk, next, err := createApplyPatchUpdateChunk(lines, index, changeContext, startLine, lineCount)
		if err != nil {
			return nil, index, err
		}
		chunks = append(chunks, chunk)
		index = next
	}
	if len(chunks) == 0 {
		return nil, index, fmt.Errorf("Update file hunk is empty")
	}
	return chunks, index, nil
}

func parseApplyPatch(patchText string) (parsedApplyPatch, error) {
	normalized, err := normalizeApplyPatchInput(patchText)
	if err != nil {
		return parsedApplyPatch{}, err
	}
	lines := strings.Split(strings.TrimSpace(normalized), "\n")
	if len(lines) < 2 || strings.TrimSpace(lines[0]) != "*** Begin Patch" || strings.TrimSpace(lines[len(lines)-1]) != "*** End Patch" {
		return parsedApplyPatch{}, fmt.Errorf("Invalid patch format: expected \"*** Begin Patch\" / \"*** End Patch\" markers")
	}

	parsed := parsedApplyPatch{Hunks: []applyPatchHunk{}}
	index := 1
	end := len(lines) - 1
	for index < end {
		header, err := parseStandardPatchHeader(lines, index)
		if err != nil {
			return parsedApplyPatch{}, err
		}
		if header == nil {
			if strings.TrimSpace(lines[index]) == "" {
				index++
				continue
			}
			return parsedApplyPatch{}, fmt.Errorf("Unexpected patch line: %s", lines[index])
		}
		switch header.Type {
		case "add":
			contents, next, err := parseAddedPatchFile(lines, header.Next)
			if err != nil {
				return parsedApplyPatch{}, err
			}
			parsed.Hunks = append(parsed.Hunks, applyPatchHunk{Type: "add", Path: header.FilePath, Contents: contents})
			index = next
		case "delete":
			parsed.Hunks = append(parsed.Hunks, applyPatchHunk{Type: "delete", Path: header.FilePath})
			index = header.Next
		case "update":
			chunks, next, err := parseUpdatedPatchFile(lines, header.Next)
			if err != nil {
				return parsedApplyPatch{}, err
			}
			parsed.Hunks = append(parsed.Hunks, applyPatchHunk{Type: "update", Path: header.FilePath, MovePath: header.MovePath, Chunks: chunks})
			index = next
		default:
			return parsedApplyPatch{}, fmt.Errorf("Unsupported patch hunk type: %s", header.Type)
		}
	}
	if len(parsed.Hunks) == 0 {
		return parsedApplyPatch{}, fmt.Errorf("Patch did not contain any file hunks")
	}
	return parsed, nil
}

