func sortStrings(values []string) {
	for x := 1; x < len(values); x++ {
		for y := x; y > 0 && values[y] < values[y-1]; y-- {
			values[y], values[y-1] = values[y-1], values[y]
		}
	}
}

func (i *codeModeInterpreter) functionFromLiteral(fn *ast.FunctionLiteral, env *environment) *codeFunction {
	out := &codeFunction{closure: env, async: fn.Async, block: fn.Body}
	if fn.ParameterList != nil {
		out.params = fn.ParameterList.List
		out.rest = fn.ParameterList.Rest
	}
	return out
}

func (i *codeModeInterpreter) functionFromArrow(fn *ast.ArrowFunctionLiteral, env *environment) (*codeFunction, error) {
	out := &codeFunction{closure: env, async: fn.Async}
	if fn.ParameterList != nil {
		out.params = fn.ParameterList.List
		out.rest = fn.ParameterList.Rest
	}
	switch body := fn.Body.(type) {
	case *ast.BlockStatement:
		out.block = body
	case *ast.ExpressionBody:
		out.expression = body.Expression
	default:
		return nil, unsupportedCodeModeNode(body, "")
	}
	return out, nil
}

func (i *codeModeInterpreter) invokeFunction(fn *codeFunction, args []any, node ast.Node) (any, error) {
	i.mu.Lock()
	i.callDepth++
	depth := i.callDepth
	i.mu.Unlock()
	if depth > i.limits.MaxCallDepth {
		i.mu.Lock()
		i.callDepth--
		i.mu.Unlock()
		return nil, i.attach(cmError("StepLimitExceeded", fmt.Sprintf("Code Mode exceeded the %d-call-depth limit.", i.limits.MaxCallDepth), node), node)
	}
	defer func() { i.mu.Lock(); i.callDepth--; i.mu.Unlock() }()
	scope := newEnvironment(fn.closure, true)
	argIndex := 0
	for _, binding := range fn.params {
		value := any(codeUndefined)
		if argIndex < len(args) {
			value = args[argIndex]
		}
		argIndex++
		if err := i.bindTarget(binding.Target, value, scope, "let", binding.Initializer); err != nil {
			return nil, err
		}
	}
	if fn.rest != nil {
		rest := newCodeArray()
		if argIndex < len(args) {
			rest.items = append(rest.items, args[argIndex:]...)
		}
		if err := i.bindExpressionPattern(fn.rest, rest, scope, "let", nil); err != nil {
			return nil, err
		}
	}
	if fn.expression != nil {
		return i.evaluate(fn.expression, scope)
	}
	err := i.executeStatement(fn.block, scope)
	if signal, ok := err.(*returnSignal); ok {
		return signal.value, nil
	}
	return codeUndefined, err
}

func (i *codeModeInterpreter) bindTarget(target ast.BindingTarget, value any, env *environment, kind string, defaultExpr ast.Expression) error {
	if isUndefined(value) && defaultExpr != nil {
		evaluated, err := i.evaluate(defaultExpr, env)
		if err != nil {
			return err
		}
		value = evaluated
	}
	switch pattern := target.(type) {
	case *ast.Identifier:
		name := pattern.Name.String()
		if kind == "var" {
			env.declareVar(name, value)
			return nil
		}
		return env.declare(name, value, kind != "const")
	case *ast.ArrayPattern:
		return i.bindArrayPattern(pattern, value, env, kind)
	case *ast.ObjectPattern:
		return i.bindObjectPattern(pattern, value, env, kind)
	default:
		return unsupportedCodeModeNode(target, "Unsupported binding pattern.")
	}
}

func (i *codeModeInterpreter) bindExpressionPattern(pattern ast.Expression, value any, env *environment, kind string, defaultExpr ast.Expression) error {
	if isUndefined(value) && defaultExpr != nil {
		evaluated, err := i.evaluate(defaultExpr, env)
		if err != nil {
			return err
		}
		value = evaluated
	}
	switch p := pattern.(type) {
	case *ast.Identifier:
		if kind == "assign" {
			return env.set(p.Name.String(), value, p)
		}
		if kind == "var" {
			env.declareVar(p.Name.String(), value)
			return nil
		}
		return env.declare(p.Name.String(), value, kind != "const")
	case *ast.ArrayPattern:
		return i.bindArrayPattern(p, value, env, kind)
	case *ast.ObjectPattern:
		return i.bindObjectPattern(p, value, env, kind)
	case *ast.AssignExpression:
		if p.Operator.String() != "=" {
			return unsupportedCodeModeNode(p, "Unsupported assignment pattern.")
		}
		chosen := value
		if isUndefined(chosen) {
			v, err := i.evaluate(p.Right, env)
			if err != nil {
				return err
			}
			chosen = v
		}
		return i.bindExpressionPattern(p.Left, chosen, env, kind, nil)
	default:
		if kind == "assign" {
			return i.writeLValue(p, value, env)
		}
		return unsupportedCodeModeNode(pattern, "Unsupported binding pattern.")
	}
}

func (i *codeModeInterpreter) bindArrayPattern(pattern *ast.ArrayPattern, value any, env *environment, kind string) error {
	array, ok := value.(*codeArray)
	if !ok {
		return i.attach(cmError("TypeError", "Array destructuring expects an array.", pattern), pattern)
	}
	for index, element := range pattern.Elements {
		if element == nil {
			continue
		}
		item := any(codeUndefined)
		if index < len(array.items) {
			item = array.items[index]
		}
		if err := i.bindExpressionPattern(element, item, env, kind, nil); err != nil {
			return err
