func (i *codeModeInterpreter) bindObjectPattern(pattern *ast.ObjectPattern, value any, env *environment, kind string) error {
	object, ok := value.(*codeObject)
	if !ok {
		return i.attach(cmError("TypeError", "Object destructuring expects a data object.", pattern), pattern)
	}
	used := map[string]bool{}
	for _, property := range pattern.Properties {
		switch prop := property.(type) {
		case *ast.PropertyShort:
			key := prop.Name.Name.String()
			used[key] = true
			item := object.props[key]
