		runes := []rune(value)
		if name == "length" {
			return float64(len(runes)), nil
		}
		if index, ok := canonicalArrayIndex(name); ok {
			if index < len(runes) {
				return string(runes[index]), nil
			}
			return codeUndefined, nil
		}
		if stringMethodAllowed(name) {
			return &intrinsicReference{receiver: value, name: name}, nil
		}
		return nil, i.attach(cmError("TypeError", fmt.Sprintf("String method/property '%s' is not available in Tidecode Code Mode.", name), node), node)
	case *codeObject:
		if item, ok := value.props[name]; ok {
			return item, nil
		}
		return codeUndefined, nil
	case nil:
		return nil, i.attach(cmError("TypeError", "Cannot read properties of null or undefined.", node), node)
	case codeUndefinedValue:
		return nil, i.attach(cmError("TypeError", "Cannot read properties of null or undefined.", node), node)
	default:
		return nil, i.attach(cmError("TypeError", fmt.Sprintf("Cannot read property '%s' from this value.", name), node), node)
