}

func (i *codeModeInterpreter) evaluateCall(n *ast.CallExpression, env *environment) (any, error) {
	callee, err := i.evaluate(n.Callee, env)
	if err != nil {
		return nil, err
	}
	args := []any{}
	for _, argument := range n.ArgumentList {
		if spread, ok := argument.(*ast.SpreadElement); ok {
			value, evalErr := i.evaluate(spread.Expression, env)
			if evalErr != nil {
				return nil, evalErr
			}
			array, ok := value.(*codeArray)
			if !ok {
				return nil, i.attach(cmError("TypeError", "Call spread expects an array.", spread), spread)
			}
			args = append(args, array.items...)
		} else {
			value, evalErr := i.evaluate(argument, env)
			if evalErr != nil {
				return nil, evalErr
			}
			args = append(args, value)
		}
	}
	switch fn := callee.(type) {
	case *toolReference:
		return i.tools.call(fn, args, n)
	case *codeFunction:
		if fn.async {
			return startCodePromise(func() (any, error) { return i.invokeFunction(fn, args, n) }), nil
		}
		return i.invokeFunction(fn, args, n)
	case *nativeFunction:
		return fn.invoke(args, n)
	case *intrinsicReference:
		return i.invokeIntrinsic(fn, args, n)
	default:
		return nil, i.attach(cmError("TypeError", "Attempted to call a value that is not callable in Tidecode Code Mode.", n), n)
	}
}

func (i *codeModeInterpreter) evaluateNew(n *ast.NewExpression, env *environment) (any, error) {
	callee, err := i.evaluate(n.Callee, env)
	if err != nil {
		return nil, err
	}
	fn, ok := callee.(*nativeFunction)
	if !ok || !map[string]bool{"Error": true, "TypeError": true, "RangeError": true, "SyntaxError": true, "ReferenceError": true}[fn.name] {
		return nil, unsupportedCodeModeNode(n, "Only standard Error values may be constructed with new in Tidecode Code Mode.")
	}
	args := []any{}
	for _, argument := range n.ArgumentList {
		value, evalErr := i.evaluate(argument, env)
		if evalErr != nil {
			return nil, evalErr
		}
		args = append(args, value)
	}
	return fn.invoke(args, n)
}

