package relay

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"

	"github.com/modelcontextprotocol/go-sdk/mcp"

	"tidecode-fs-mcp-go/internal/tidecode"
)

const gatewayServerName = "tidecode-gateway"
const gatewayServerVersion = "0.1.0"

func gatewayBool(v bool) *bool { return &v }

func gatewayFailure(message string) *mcp.CallToolResult {
	return &mcp.CallToolResult{
		Content: []mcp.Content{&mcp.TextContent{Text: message}},
		IsError: true,
	}
}

func gatewayRequireString(input map[string]any, key string) (string, error) {
	value, ok := input[key].(string)
	if !ok || strings.TrimSpace(value) == "" {
		return "", fmt.Errorf("%s must be a non-empty string", key)
	}
	return value, nil
}

func proxyGatewayTool(ctx context.Context, broker *Broker, method string, input map[string]any) *mcp.CallToolResult {
	deviceID, err := gatewayRequireString(input, "device_id")
	if err != nil {
		return gatewayFailure(err.Error())
	}
	arguments := make(map[string]any, len(input)-1)
	for key, value := range input {
		if key != "device_id" {
			arguments[key] = value
		}
	}
	jobResult, err := broker.Submit(ctx, deviceID, method, arguments)
	if err != nil {
		return gatewayFailure(err.Error())
	}
	if jobResult.Error != "" {
		return gatewayFailure(jobResult.Error)
	}
	var result mcp.CallToolResult
	if err := json.Unmarshal(jobResult.RawResult, &result); err != nil {
		return gatewayFailure("agent returned an invalid MCP tool result: " + err.Error())
	}
	return &result
}

func NewGatewayMCPServer(broker *Broker, scopes tidecode.ScopeSet, instructionsPath string) *mcp.Server {
	instructions := "This is a Tidecode device gateway. MANDATORY FIRST STEP: before calling devices_list, tcode_mode, write, apply_patch, or any other Tidecode tool for the first time in a conversation, call tcode_instructions and wait for its result. Do not perform any Tidecode operation before tcode_instructions has been read. Follow the returned instructions as the authoritative Tidecode usage guide. For normal follow-up work in the same conversation, reuse those instructions and established context instead of calling tcode_instructions again unless the instructions are no longer present in context or the user explicitly asks to refresh them."
	server := mcp.NewServer(&mcp.Implementation{Name: gatewayServerName, Version: gatewayServerVersion}, &mcp.ServerOptions{Instructions: instructions})

	instructionsTool := &mcp.Tool{
		Name:        "tcode_instructions",
		Title:       "Read Tidecode usage instructions",
		Description: "Read the authoritative Tidecode usage guide from the gateway's editable config file. Use it when establishing or refreshing Tidecode context.",
		InputSchema: map[string]any{
			"type":                 "object",
			"additionalProperties": false,
			"properties":           map[string]any{},
		},
		Annotations: &mcp.ToolAnnotations{ReadOnlyHint: true, DestructiveHint: gatewayBool(false), IdempotentHint: true},
	}
	mcp.AddTool[map[string]any, any](server, instructionsTool, func(ctx context.Context, req *mcp.CallToolRequest, input map[string]any) (*mcp.CallToolResult, any, error) {
		if !scopes.Allows("planner:read") {
			return gatewayFailure("Missing required scope: planner:read"), nil, nil
		}
		body, err := loadTidecodeInstructions(instructionsPath)
		if err != nil {
			return gatewayFailure(err.Error()), nil, nil
		}
		structured := map[string]any{"instructions": body}
		return &mcp.CallToolResult{
			Content:           []mcp.Content{&mcp.TextContent{Text: body}},
			StructuredContent: structured,
		}, nil, nil
	})

	devicesTool := &mcp.Tool{
		Name:        "devices_list",
		Title:       "List Tidecode devices",
		Description: "List registered Tidecode devices and their online status. This never discovers or returns filesystem paths or workspaces.",
		InputSchema: map[string]any{
			"type":                 "object",
			"additionalProperties": false,
			"properties":           map[string]any{},
		},
		Annotations: &mcp.ToolAnnotations{ReadOnlyHint: true, DestructiveHint: gatewayBool(false), IdempotentHint: true},
	}
	mcp.AddTool[map[string]any, any](server, devicesTool, func(ctx context.Context, req *mcp.CallToolRequest, input map[string]any) (*mcp.CallToolResult, any, error) {
		if !scopes.Allows("planner:read") {
			return gatewayFailure("Missing required scope: planner:read"), nil, nil
		}
		devices := broker.ListDevices()
		structured := map[string]any{"devices": devices}
		body, _ := json.MarshalIndent(structured, "", "  ")
		return &mcp.CallToolResult{
			Content:           []mcp.Content{&mcp.TextContent{Text: string(body)}},
			StructuredContent: structured,
		}, nil, nil
	})

	tcodeTool := &mcp.Tool{
		Name:        "tcode_mode",
		Title:       "Run Tidecode Code Mode on a device",
		Description: "Execute Tidecode Code Mode on the selected device and an absolute workspace.",
		InputSchema: map[string]any{
			"type":                 "object",
			"additionalProperties": false,
			"properties": map[string]any{
				"device_id":      map[string]any{"type": "string", "minLength": 1, "description": "Stable target device ID from devices_list."},
				"workspace_path": map[string]any{"type": "string", "minLength": 1, "description": "Absolute project root for the selected device. Reuse an established trusted workspace when available."},
				"code":           map[string]any{"type": "string", "minLength": 1, "description": "Free-form temporary asynchronous Tidecode Code Mode JavaScript."},
				"payloads": map[string]any{
					"type":                 "object",
					"description":          "Optional opaque text payloads forwarded unchanged to the local Tidecode MCP.",
					"additionalProperties": map[string]any{"type": "string"},
				},
			},
			"required": []string{"device_id", "workspace_path", "code"},
		},
		Annotations: &mcp.ToolAnnotations{ReadOnlyHint: false, DestructiveHint: gatewayBool(true), IdempotentHint: false},
	}
	mcp.AddTool[map[string]any, any](server, tcodeTool, func(ctx context.Context, req *mcp.CallToolRequest, input map[string]any) (*mcp.CallToolResult, any, error) {
		if !scopes.Allows("planner:terminal") {
			return gatewayFailure("tcode_mode requires the planner:terminal OAuth scope because it can invoke terminal-capable structured tools."), nil, nil
		}
		return proxyGatewayTool(ctx, broker, "tcode_mode", input), nil, nil
	})

	writeTool := &mcp.Tool{
		Name:        "write",
		Title:       "Write complete file on a device",
		Description: "Create or replace one complete file through the selected device's local Tidecode MCP.",
		InputSchema: map[string]any{
			"type":                 "object",
			"additionalProperties": false,
			"properties": map[string]any{
				"device_id":      map[string]any{"type": "string", "minLength": 1, "description": "Stable target device ID from devices_list."},
				"workspace_path": map[string]any{"type": "string", "minLength": 1, "description": "Absolute project root for the selected device. Reuse an established trusted workspace when available."},
				"path":           map[string]any{"type": "string", "minLength": 1, "description": "Workspace-relative file path."},
				"content":        map[string]any{"type": "string", "description": "Complete exact file contents."},
			},
			"required": []string{"device_id", "workspace_path", "path", "content"},
		},
		Annotations: &mcp.ToolAnnotations{ReadOnlyHint: false, DestructiveHint: gatewayBool(true), IdempotentHint: false},
	}
	mcp.AddTool[map[string]any, any](server, writeTool, func(ctx context.Context, req *mcp.CallToolRequest, input map[string]any) (*mcp.CallToolResult, any, error) {
		if !scopes.Allows("planner:write") {
			return gatewayFailure("Missing required scope: planner:write"), nil, nil
		}
		return proxyGatewayTool(ctx, broker, "write", input), nil, nil
	})

	patchTool := &mcp.Tool{
		Name:        "apply_patch",
		Title:       "Apply targeted patch on a device",
		Description: "Apply one exact raw Codex patch through the selected device's local Tidecode MCP. Use *** Add File only for a new path; every file-content line in an Add File hunk must start with +, including an added blank line represented as +. Use *** Update File for edits to an existing path.",
		InputSchema: map[string]any{
			"type":                 "object",
			"additionalProperties": false,
			"properties": map[string]any{
				"device_id":      map[string]any{"type": "string", "minLength": 1, "description": "Stable target device ID from devices_list."},
				"workspace_path": map[string]any{"type": "string", "minLength": 1, "description": "Absolute project root for the selected device. Reuse an established trusted workspace when available."},
				"patch":          map[string]any{"type": "string", "minLength": 1, "description": "Exact raw Codex patch string."},
			},
			"required": []string{"device_id", "workspace_path", "patch"},
		},
