	deviceID := strings.TrimSpace(r.Header.Get("X-Tidecode-Device-ID"))
	secret := bearerToken(r)
	if deviceID == "" || secret == "" || !h.broker.Authenticate(deviceID, secret) {
		w.Header().Set("WWW-Authenticate", "Bearer")
		writeAgentJSON(w, http.StatusUnauthorized, map[string]string{"error": "invalid device credentials"})
