	}
	switch mode {
	case gatewayTransportDirect, gatewayTransportBrowser, gatewayTransportAuto:
		return mode, nil
	default:
		return "", fmt.Errorf("unsupported gateway transport %q; expected direct, browser, or auto", value)
	}
