	if err != nil || (parsedGateway.Scheme != "http" && parsedGateway.Scheme != "https") || parsedGateway.Host == "" {
		return nil, errors.New("gateway URL must be an absolute HTTP or HTTPS URL")
	}
	if config.DeviceID == "" {
		return nil, errors.New("device ID is required")
	}
	if config.DeviceSecret == "" {
		return nil, errors.New("device secret is required")
	}
	if config.DeviceName == "" {
		config.DeviceName = config.DeviceID
	}
	if config.LocalMCPURL == "" {
		config.LocalMCPURL = "http://127.0.0.1:3009/mcp"
	}
	parsedLocal, err := url.Parse(config.LocalMCPURL)
	if err != nil || parsedLocal.Scheme != "http" || parsedLocal.Host == "" {
		return nil, errors.New("local MCP URL must be an absolute HTTP URL")
