	// Drain a bounded amount so the transport can reuse the connection, but do
	// not put a gateway response body in an agent error. Error bodies can contain
	// details that are not appropriate for agent logs.
	_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 32*1024))
	return &gatewayHTTPError{statusCode: resp.StatusCode}
}

func diagnosticError(err error) string {
	if err == nil {
		return "unknown error"
	}
	var gatewayErr *gatewayHTTPError
	if errors.As(err, &gatewayErr) {
		return fmt.Sprintf("HTTP %d", gatewayErr.statusCode)
	}
	if errors.Is(err, context.DeadlineExceeded) {
		return "request timed out"
	}
	if errors.Is(err, context.Canceled) {
		return "request canceled"
	}
	var networkErr net.Error
	if errors.As(err, &networkErr) {
		if networkErr.Timeout() {
			return "network timeout"
		}
		return "network error: " + networkErr.Error()
	}
	message := strings.Join(strings.Fields(err.Error()), " ")
	if len(message) > 256 {
		message = message[:256] + "..."
	}
	return message
}

