func strictInt(value any) (int, bool) {
	switch number := value.(type) {
	case int:
		return number, true
	case int8:
		return int(number), true
	case int16:
		return int(number), true
	case int32:
		return int(number), true
	case int64:
		return int(number), true
	case uint:
		return int(number), true
	case uint8:
		return int(number), true
	case uint16:
		return int(number), true
	case uint32:
		return int(number), true
	case uint64:
		if uint64(int(number)) != number {
			return 0, false
		}
		return int(number), true
	case float32:
		v := float64(number)
		if math.Trunc(v) != v {
			return 0, false
		}
		return int(v), true
	case float64:
		if math.Trunc(number) != number || math.IsNaN(number) || math.IsInf(number, 0) {
			return 0, false
		}
		return int(number), true
	case json.Number:
		v, err := number.Int64()
		if err != nil {
			return 0, false
		}
		return int(v), true
	default:
		return 0, false
	}
