		}
		if opts[0].Limit > 0 {
			limit = opts[0].Limit
			if limit > maxReadLines {
				limit = maxReadLines
			}
		}
	}
	start := offset - 1
	if start > len(names) {
		start = len(names)
	}
	end := start + limit
	if end > len(names) {
		end = len(names)
	}
