	compare := func(left, right string) bool {
		leftIndex, rightIndex := 0, 0
		collapsed := false
		for leftIndex < len(left) && rightIndex < len(right) {
			if left[leftIndex] == '\\' || right[rightIndex] == '\\' {
				if left[leftIndex] != '\\' || right[rightIndex] != '\\' {
