package tidecode

import (
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"
	"runtime"
	"strconv"
	"strings"
	"sync"
	"time"

	ptylib "github.com/aymanbagabas/go-pty"
)

const defaultTerminalWait = 15
const maxTerminalWait = 300
const maxTranscriptChars = 300000
const terminalCompletionSettle = 100 * time.Millisecond
const terminalReapInterval = 30 * time.Second
const completedTerminalRetention = 2 * time.Minute
const activeTerminalIdleTimeout = 30 * time.Minute

type TerminalExecuteInput struct {
	Command       string `json:"command"`
	Cwd           string `json:"cwd,omitempty"`
	WorkspacePath string `json:"workspace_path,omitempty"`
}
type TerminalReadInput struct {
	SessionID     int    `json:"session_id"`
	WaitSeconds   int    `json:"wait_seconds,omitempty"`
	WorkspacePath string `json:"workspace_path,omitempty"`
}
type TerminalInteractInput struct {
	SessionID     int      `json:"session_id"`
	Text          string   `json:"text,omitempty"`
	Keys          []string `json:"keys,omitempty"`
	Cols          int      `json:"cols,omitempty"`
	Rows          int      `json:"rows,omitempty"`
	WaitSeconds   int      `json:"wait_seconds,omitempty"`
	WorkspacePath string   `json:"workspace_path,omitempty"`
}

type terminalSession struct {
	mu              sync.Mutex
	id              int
	owner           string
	workspace       string
	pty             ptylib.Pty
	cmd             *ptylib.Cmd
	lines           []string
	partial         string
	unread          int
	state           string
	exitStatus      string
	startMarker     string
	marker          string
	started         bool
	lastActivity    time.Time
	closed          bool
	resourcesClosed bool
	onComplete      func(*terminalSession)
}

type TerminalService struct {
	mu       sync.Mutex
	sessions map[int]*terminalSession
	next     int
	closed   bool
	stopCh   chan struct{}
	doneCh   chan struct{}
}

func NewTerminalService() *TerminalService {
	s := &TerminalService{
		sessions: map[int]*terminalSession{},
		next:     10000,
		stopCh:   make(chan struct{}),
		doneCh:   make(chan struct{}),
	}
	go s.reapLoop()
	return s
}

func (s *terminalSession) closeResources(killProcess bool) {
	s.mu.Lock()
	if s.resourcesClosed {
		s.mu.Unlock()
		return
	}
	s.resourcesClosed = true
	cmd := s.cmd
	pty := s.pty
	s.mu.Unlock()

	if killProcess && cmd != nil && cmd.Process != nil {
		_ = cmd.Process.Kill()
	}
	if pty != nil {
		_ = pty.Close()
	}
}

func (s *TerminalService) reapLoop() {
	ticker := time.NewTicker(terminalReapInterval)
	defer ticker.Stop()
	defer close(s.doneCh)
	for {
		select {
		case now := <-ticker.C:
			s.reapTerminalSessions(now)
		case <-s.stopCh:
			return
		}
	}
}

func (s *TerminalService) reapTerminalSessions(now time.Time) {
	stale := make([]*terminalSession, 0)
	s.mu.Lock()
	for id, session := range s.sessions {
		session.mu.Lock()
		state := session.state
		lastActivity := session.lastActivity
		session.mu.Unlock()

		completedExpired := state == "completed" && now.Sub(lastActivity) >= completedTerminalRetention
		activeExpired := state != "completed" && now.Sub(lastActivity) >= activeTerminalIdleTimeout
		if completedExpired || activeExpired {
			delete(s.sessions, id)
			stale = append(stale, session)
		}
	}
	s.mu.Unlock()

	for _, session := range stale {
		session.closeResources(true)
	}
}

func (s *TerminalService) removeSession(id int, expected *terminalSession) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	current := s.sessions[id]
	if current == nil || (expected != nil && current != expected) {
		return false
	}
	delete(s.sessions, id)
	return true
}

func shellCandidate() (string, []string, string, error) {
	if runtime.GOOS == "windows" {
		for _, name := range []string{"pwsh.exe", "pwsh", "powershell.exe", "powershell"} {
			if p, err := exec.LookPath(name); err == nil {
				return p, []string{"-NoLogo", "-NoProfile", "-NoExit"}, "powershell", nil
			}
		}
		if p, err := exec.LookPath("cmd.exe"); err == nil {
			return p, []string{"/Q"}, "cmd", nil
		}
		return "", nil, "", errors.New("no supported Windows shell found")
	}
	for _, name := range []string{os.Getenv("SHELL"), "zsh", "bash", "sh"} {
		if name == "" {
			continue
		}
		if p, err := exec.LookPath(name); err == nil {
			return p, []string{}, "unix", nil
		}
	}
	return "", nil, "", errors.New("no supported shell found")
}

func (s *TerminalService) allocate() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	for i := 0; i < 90000; i++ {
		s.next++
		if s.next > 99999 {
			s.next = 10000
		}
		if _, ok := s.sessions[s.next]; !ok {
			return s.next
		}
	}
	return 0
}

func (s *TerminalService) Execute(owner string, in TerminalExecuteInput) (ToolResult, error) {
	root, err := resolveWorkspace(in.WorkspacePath)
	if err != nil {
		return ToolResult{}, err
	}
	if strings.TrimSpace(in.Command) == "" {
		return failure("command must be non-empty"), nil
	}
	cwd := root
	if strings.TrimSpace(in.Cwd) != "" {
		cwd, err = resolveReadPath(root, in.Cwd, true)
		if err != nil {
			return ToolResult{}, err
		}
		info, statErr := os.Stat(cwd)
		if statErr != nil {
			return ToolResult{}, statErr
		}
		if !info.IsDir() {
			return ToolResult{}, fmt.Errorf("Terminal cwd must be a directory: %s", slashRelative(root, cwd))
		}
	}
	p, err := ptylib.New()
	if err != nil {
		return ToolResult{}, err
	}
	_ = p.Resize(220, 50)
	shell, args, kind, err := shellCandidate()
	if err != nil {
		p.Close()
		return ToolResult{}, err
	}
	cmd := p.Command(shell, args...)
	cmd.Dir = cwd
	cmd.Env = os.Environ()
	if err := cmd.Start(); err != nil {
		p.Close()
		return ToolResult{}, err
	}
	id := s.allocate()
	if id == 0 {
		if cmd.Process != nil {
			_ = cmd.Process.Kill()
		}
		_ = p.Close()
		return ToolResult{}, errors.New("no terminal session slots are available")
	}
	nonce := time.Now().UnixNano()
	startMarker := fmt.Sprintf("__TIDECODE_START_%d_%d__", id, nonce)
	marker := fmt.Sprintf("__TIDECODE_DONE_%d_%d__", id, nonce)
	sess := &terminalSession{id: id, owner: owner, workspace: root, pty: p, cmd: cmd, unread: 0, state: "active", startMarker: startMarker, marker: marker, lastActivity: time.Now()}
	sess.onComplete = func(completed *terminalSession) {
		completed.closeResources(true)
	}
	s.mu.Lock()
	if s.closed {
		s.mu.Unlock()
		sess.closeResources(true)
		return ToolResult{}, errors.New("terminal service is closed")
	}
	s.sessions[id] = sess
	s.mu.Unlock()
	go sess.readLoop()
	go sess.waitLoop()
	var line string
	switch kind {
	case "powershell":
		line = "Write-Output \"" + startMarker + "\"; $global:LASTEXITCODE = 0; " + in.Command + "; $tcodeSuccess = $?; $tcodeNativeExit = $LASTEXITCODE; if ($tcodeSuccess) { $tcodeExit = 0 } elseif ($null -ne $tcodeNativeExit -and [int]$tcodeNativeExit -ne 0) { $tcodeExit = [int]$tcodeNativeExit } else { $tcodeExit = 1 }; Write-Output (\"" + marker + ":\" + $tcodeExit)\r\n"
	case "cmd":
		line = "echo " + startMarker + " & " + in.Command + " & call echo " + marker + ":%%errorlevel%%\r\n"
	default:
		line = "printf '" + startMarker + "\\n'; " + in.Command + "; tcodeExit=$?; printf '\\n" + marker + ":%s\\n' \"$tcodeExit\"\n"
	}
	if _, err := p.Write([]byte(line)); err != nil {
		s.removeSession(id, sess)
		sess.closeResources(true)
		return ToolResult{}, err
	}
	sess.mu.Lock()
	sess.lastActivity = time.Now()
	sess.mu.Unlock()
	waitForInitial(sess, defaultTerminalWait)
	return sess.result(defaultTerminalWait), nil
}

func (s *terminalSession) readLoop() {
	buf := make([]byte, 8192)
	for {
		n, err := s.pty.Read(buf)
		if n > 0 {
			s.consume(string(buf[:n]))
		}
		if err != nil {
			if err != io.EOF {
				s.mu.Lock()
				if s.exitStatus == "" {
					s.exitStatus = err.Error()
				}
				s.mu.Unlock()
			}
			return
		}
	}
}
func stripANSI(v string) string {
	var b strings.Builder
	esc := false
	csi := false
	stringControl := false
	stringEscape := false
	for _, r := range v {
		if stringControl {
			if stringEscape {
				if r == '\\' {
					stringControl = false
				}
				stringEscape = false
				continue
			}
			if r == 0x07 {
				stringControl = false
				continue
			}
			if r == 0x1b {
				stringEscape = true
			}
			continue
		}
		if esc {
			esc = false
			if r == '[' {
				csi = true
				continue
			}
			if r == ']' || r == 'P' || r == '^' || r == '_' {
				stringControl = true
				continue
			}
			continue
		}
		if csi {
			if r >= 0x40 && r <= 0x7e {
				csi = false
			}
			continue
		}
		if r == 0x1b {
			esc = true
			continue
		}
		if r < 0x20 && r != '\n' && r != '\r' && r != '\t' && r != '\b' {
			continue
		}
		b.WriteRune(r)
	}
	return b.String()
}

func terminalLineText(raw string) string {
	runes := make([]rune, 0, len(raw))
	for _, r := range raw {
		switch r {
		case rune(13):
			continue
		case rune(8):
			if len(runes) > 0 {
				runes = runes[:len(runes)-1]
			}
		default:
			runes = append(runes, r)
		}
	}
	return strings.TrimRight(string(runes), string([]rune{32, 9}))
}

func (s *terminalSession) appendTerminalLineLocked(raw string) {
	line := terminalLineText(raw)
	trimmed := strings.TrimSpace(line)
	if !s.started {
		if trimmed == s.startMarker {
			s.started = true
		}
		return
	}
	if s.state == "completed" {
		return
	}
	if strings.HasPrefix(trimmed, s.marker+":") {
		status := strings.TrimSpace(trimmed[len(s.marker)+1:])
		if _, err := strconv.Atoi(status); err == nil {
			s.exitStatus = status
			s.state = "completed"
			return
		}
	}
	s.lines = append(s.lines, line)
}

func (s *terminalSession) finalizePartialLocked() {
	if s.partial == "" {
		return
	}
	s.appendTerminalLineLocked(s.partial)
	s.partial = ""
	s.trimTranscript()
}

func (s *terminalSession) consume(chunk string) {
	s.mu.Lock()
	wasCompleted := s.state == "completed"
	text := stripANSI(s.partial + chunk)
	parts := strings.Split(text, string(rune(10)))
	s.partial = parts[len(parts)-1]
	for _, line := range parts[:len(parts)-1] {
		s.appendTerminalLineLocked(line)
	}
	s.lastActivity = time.Now()
	s.trimTranscript()
	completedNow := !wasCompleted && s.state == "completed"
	onComplete := s.onComplete
	s.mu.Unlock()
	if completedNow && onComplete != nil {
		onComplete(s)
	}
}
func (s *terminalSession) trimTranscript() {
	total := 0
	for i := len(s.lines) - 1; i >= 0; i-- {
		total += len(s.lines[i]) + 1
		if total > maxTranscriptChars {
			removed := i + 1
			s.lines = append([]string(nil), s.lines[removed:]...)
			s.unread -= removed
			if s.unread < 0 {
				s.unread = 0
			}
			break
		}
	}
}
func (s *terminalSession) waitLoop() {
	err := s.cmd.Wait()
	s.mu.Lock()
	if s.state != "completed" {
		s.state = "completed"
		if err != nil {
			s.exitStatus = err.Error()
		} else if s.exitStatus == "" {
			s.exitStatus = "0"
		}
	}
	s.closed = true
	s.lastActivity = time.Now()
	s.mu.Unlock()
	s.closeResources(false)
}
func waitForInitial(s *terminalSession, seconds int) {
	if seconds < 0 {
		seconds = 0
	}
	if seconds > maxTerminalWait {
		seconds = maxTerminalWait
	}
	deadline := time.Now().Add(time.Duration(seconds) * time.Second)
	for {
		s.mu.Lock()
		partial := strings.TrimSpace(s.partial)
		interaction := s.state != "completed" && partial != "" && !strings.HasPrefix(partial, "PS ") && (strings.HasSuffix(partial, ":") || strings.HasSuffix(partial, "?"))
		completed := s.state == "completed"
		quiet := completed && time.Since(s.lastActivity) >= terminalCompletionSettle
		s.mu.Unlock()
		if interaction || quiet {
			return
		}
		if seconds == 0 || time.Now().After(deadline) {
			return
		}
		time.Sleep(20 * time.Millisecond)
	}
}

type terminalSnapshot struct {
	lines   int
	partial string
	state   string
}

func snapshotTerminal(s *terminalSession) terminalSnapshot {
	s.mu.Lock()
	defer s.mu.Unlock()
	return terminalSnapshot{lines: len(s.lines), partial: s.partial, state: s.state}
