func (s *TerminalService) lookup(owner, root string, id int) (*terminalSession, error) {
	workspace, err := resolveWorkspace(root)
	if err != nil {
		return nil, err
	}
	s.mu.Lock()
	sess := s.sessions[id]
	if sess == nil || sess.owner != owner {
		s.mu.Unlock()
		return nil, errors.New("terminal session not found for this caller")
	}
	if !strings.EqualFold(sess.workspace, workspace) {
		s.mu.Unlock()
		return nil, errors.New("terminal session belongs to another workspace")
	}
	sess.mu.Lock()
	sess.lastActivity = time.Now()
	sess.mu.Unlock()
	s.mu.Unlock()
	return sess, nil
}
