package tidecode

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"sync/atomic"
	"time"
)

const defaultCodeBytes = 100_000
const defaultPayloadBytes = 2_000_000
const defaultPayloadCount = 64
const defaultPayloadKeyBytes = 128
const defaultOutputBytes = 1_000_000
const defaultMediaBytes = 16 << 20
const defaultMediaItems = 8
const defaultToolCalls = 100
const defaultConcurrentToolCalls = 8
const defaultSteps = 100_000
const defaultCallDepth = 100
const defaultTimeout = 300 * time.Second

type CodeModeLimits struct {
	MaxCodeBytes           int
	MaxPayloadBytes        int
	MaxOutputBytes         int
	MaxToolCalls           int
	MaxConcurrentToolCalls int
	MaxSteps               int
	MaxCallDepth           int
	Timeout                time.Duration
}

type ToolCallReceipt struct {
	Name       string
	Arguments  any
	Status     string
	Summary    string
	Body       string
	DurationMS int64
	Semantics  map[string]any
	Subject    *Subject
	Media      []MediaPayload
	CallIndex  int
}

type CodeModeResult struct {
	Status        string
	Summary       string
	Output        any
	OutputPresent bool
	ToolCalls     []ToolCallReceipt
	ExecutionID   string
	Truncated     bool
	Engine        string
	Steps         int
	Diagnostic    *CodeModeDiagnostic
	Error         string
}

type CodeModeExecutor struct {
	Registry      *ToolRegistry
	Allowed       map[string]bool
	WorkspaceRoot string
	limits        CodeModeLimits
}

var execCounter atomic.Uint64

func defaultCodeModeLimits() CodeModeLimits {
	return CodeModeLimits{
		MaxCodeBytes:           defaultCodeBytes,
		MaxPayloadBytes:        defaultPayloadBytes,
		MaxOutputBytes:         defaultOutputBytes,
		MaxToolCalls:           defaultToolCalls,
		MaxConcurrentToolCalls: defaultConcurrentToolCalls,
		MaxSteps:               defaultSteps,
		MaxCallDepth:           defaultCallDepth,
		Timeout:                defaultTimeout,
	}
}

func NewCodeModeExecutor(reg *ToolRegistry, allowed []string, workspace string) *CodeModeExecutor {
	permitted := map[string]bool{}
	for _, name := range allowed {
		permitted[name] = true
	}
	return &CodeModeExecutor{
		Registry:      reg,
		Allowed:       permitted,
		WorkspaceRoot: workspace,
		limits:        defaultCodeModeLimits(),
	}
}

func executionID() string                  { return fmt.Sprintf("go-%d-%d", time.Now().UnixNano(), execCounter.Add(1)) }
func (e *CodeModeExecutor) Dispose() error { return nil }

func mergeCodeModeLimits(base CodeModeLimits, override CodeModeLimits) CodeModeLimits {
	if override.MaxCodeBytes > 0 {
		base.MaxCodeBytes = override.MaxCodeBytes
	}
	if override.MaxPayloadBytes > 0 {
		base.MaxPayloadBytes = override.MaxPayloadBytes
	}
	if override.MaxOutputBytes > 0 {
		base.MaxOutputBytes = override.MaxOutputBytes
	}
	if override.MaxToolCalls > 0 {
		base.MaxToolCalls = override.MaxToolCalls
	}
	if override.MaxConcurrentToolCalls > 0 {
		base.MaxConcurrentToolCalls = override.MaxConcurrentToolCalls
	}
	if override.MaxSteps > 0 {
		base.MaxSteps = override.MaxSteps
	}
	if override.MaxCallDepth > 0 {
		base.MaxCallDepth = override.MaxCallDepth
	}
	if override.Timeout > 0 {
		base.Timeout = override.Timeout
	}
	return base
}

func formatCodeModeDiagnostic(diagnostic CodeModeDiagnostic) string {
	where := ""
	if diagnostic.Location != nil {
		where = fmt.Sprintf(" (line %d, col %d)", diagnostic.Location.Line, diagnostic.Location.Column)
	}
	return fmt.Sprintf("%s: %s%s", diagnostic.Kind, diagnostic.Message, where)
}

func codeModeDiagnosticFromError(err error) CodeModeDiagnostic {
	if runtimeErr, ok := err.(*codeModeRuntimeError); ok {
		return CodeModeDiagnostic{
			Kind:        runtimeErr.Kind,
			Message:     runtimeErr.Message,
			Location:    runtimeErr.Position,
			Suggestions: append([]string(nil), runtimeErr.Suggestions...),
		}
	}
	if thrown, ok := err.(*programThrow); ok {
		message := stringValue(thrown.value)
		if record, ok := thrown.value.(*codeObject); ok {
			if value, exists := record.props["message"]; exists {
				message = stringValue(value)
			}
		}
		return CodeModeDiagnostic{Kind: "ExecutionError", Message: "Uncaught: " + message}
	}
	if errors.Is(err, context.DeadlineExceeded) {
		return CodeModeDiagnostic{Kind: "TimeoutExceeded", Message: "Code Mode execution timed out."}
	}
	if errors.Is(err, context.Canceled) {
		return CodeModeDiagnostic{Kind: "Cancelled", Message: "Code Mode execution was aborted."}
	}
	return CodeModeDiagnostic{Kind: "ExecutionError", Message: err.Error()}
}

func errorCodeModeResult(id string, diagnostic CodeModeDiagnostic, toolCalls []ToolCallReceipt, steps int) CodeModeResult {
	formatted := formatCodeModeDiagnostic(diagnostic)
	status := "error"
	if diagnostic.Kind == "Cancelled" {
		status = "aborted"
	}
	return CodeModeResult{
		Status:      status,
		Summary:     formatted,
		ToolCalls:   toolCalls,
		ExecutionID: id,
		Engine:      "v2",
		Steps:       steps,
		Diagnostic:  &diagnostic,
		Error:       formatted,
	}
}

func (e *CodeModeExecutor) Run(source string, overrides ...CodeModeLimits) CodeModeResult {
	return e.RunWithPayloads(source, nil, overrides...)
}

func (e *CodeModeExecutor) RunWithPayloads(source string, payloads map[string]string, overrides ...CodeModeLimits) CodeModeResult {
	id := executionID()
	limits := e.limits
	if len(overrides) > 0 {
		limits = mergeCodeModeLimits(limits, overrides[0])
	}
	if strings.TrimSpace(source) == "" {
		return errorCodeModeResult(id, CodeModeDiagnostic{Kind: "ParseError", Message: "Code Mode requires a non-empty program."}, nil, 0)
	}
	if len([]byte(source)) > limits.MaxCodeBytes {
		return errorCodeModeResult(id, CodeModeDiagnostic{Kind: "ParseError", Message: fmt.Sprintf("Code Mode source exceeded the %d-byte limit.", limits.MaxCodeBytes)}, nil, 0)
	}
	if len(payloads) > defaultPayloadCount {
		return errorCodeModeResult(id, CodeModeDiagnostic{Kind: "InvalidToolArguments", Message: fmt.Sprintf("Code Mode payloads exceeded the %d-item limit.", defaultPayloadCount)}, nil, 0)
	}
	payloadBytes := 0
	for key, value := range payloads {
		if strings.TrimSpace(key) == "" {
			return errorCodeModeResult(id, CodeModeDiagnostic{Kind: "InvalidToolArguments", Message: "Code Mode payload keys must be non-empty."}, nil, 0)
		}
		if len([]byte(key)) > defaultPayloadKeyBytes {
			return errorCodeModeResult(id, CodeModeDiagnostic{Kind: "InvalidToolArguments", Message: fmt.Sprintf("Code Mode payload key '%s' exceeded the %d-byte limit.", key, defaultPayloadKeyBytes)}, nil, 0)
		}
		if blockedCodeModeMembers[key] {
			return errorCodeModeResult(id, CodeModeDiagnostic{Kind: "InvalidToolArguments", Message: fmt.Sprintf("Code Mode payload key '%s' is reserved.", key)}, nil, 0)
		}
		payloadBytes += len([]byte(key)) + len([]byte(value))
		if payloadBytes > limits.MaxPayloadBytes {
			return errorCodeModeResult(id, CodeModeDiagnostic{Kind: "InvalidToolArguments", Message: fmt.Sprintf("Code Mode payloads exceeded the %d-byte limit.", limits.MaxPayloadBytes)}, nil, 0)
		}
	}
	// Backward compatibility for older clients that still embed a complete
	// apply_patch envelope in a template literal. New callers should use the
	// opaque payloads sidecar so arbitrary text never enters JavaScript syntax.
	source = normalizeCodeModePatchTemplateLiterals(source)

	parsed, err := parseCodeModeProgram(source)
	if err != nil {
		return errorCodeModeResult(id, codeModeDiagnosticFromError(err), nil, 0)
	}

	ctx, cancel := context.WithTimeout(context.Background(), limits.Timeout)
	defer cancel()
	runtime := newCodeModeToolRuntime(ctx, e.Registry, e.Allowed, e.WorkspaceRoot, id, limits)
	if unavailable := runtime.unavailableAllowedTool(); unavailable != "" {
		diagnostic := CodeModeDiagnostic{Kind: "UnknownTool", Message: fmt.Sprintf("Code Mode allowed tool '%s' is unavailable in this registry.", unavailable)}
		return errorCodeModeResult(id, diagnostic, nil, 0)
	}

	interpreter := newCodeModeInterpreter(ctx, runtime, payloads, limits, parsed.fileSet)
	output, steps, runErr := interpreter.execute(parsed.statements)
	runtime.drain()
	toolCalls := runtime.getReceipts()
	if runErr != nil {
		return errorCodeModeResult(id, codeModeDiagnosticFromError(runErr), toolCalls, steps)
	}
	if ctx.Err() != nil {
		diagnostic := codeModeDiagnosticFromError(ctx.Err())
		if errors.Is(ctx.Err(), context.DeadlineExceeded) {
			diagnostic.Message = fmt.Sprintf("Code Mode exceeded the %dms timeout.", limits.Timeout.Milliseconds())
		}
		return errorCodeModeResult(id, diagnostic, toolCalls, steps)
	}

	outputPresent := !isUndefined(output)
	truncated := false
	if outputPresent {
		encoded, encodeErr := json.Marshal(output)
		if encodeErr != nil {
			diagnostic := CodeModeDiagnostic{Kind: "TypeError", Message: "Code Mode returned non-serializable data: " + encodeErr.Error() + ". Await every tools.* call and return JSON-compatible data."}
			return errorCodeModeResult(id, diagnostic, toolCalls, steps)
		}
		if len(encoded) > limits.MaxOutputBytes {
			output = map[string]any{"message": fmt.Sprintf("Code Mode output exceeded the %d-byte limit. Return a smaller summary from the program.", limits.MaxOutputBytes)}
			truncated = true
		}
	} else {
		output = nil
	}

	failedCalls := 0
	for _, call := range toolCalls {
		if call.Status == "error" {
			failedCalls++
		}
	}
	summary := fmt.Sprintf("Code Mode V2 completed with %d tool call", len(toolCalls))
	if len(toolCalls) != 1 {
		summary += "s"
	}
	summary += "."
	if failedCalls > 0 {
		summary = fmt.Sprintf("Code Mode V2 completed after handling %d failed tool call", failedCalls)
		if failedCalls != 1 {
			summary += "s"
		}
		summary += "."
	}
	return CodeModeResult{
		Status:        "success",
		Summary:       summary,
		Output:        output,
		OutputPresent: outputPresent,
		ToolCalls:     toolCalls,
		ExecutionID:   id,
		Truncated:     truncated,
		Engine:        "v2",
		Steps:         steps,
	}
}

