func startCodePromise(work func() (any, error)) *codePromise {
	p := &codePromise{done: make(chan struct{})}
	go func() {
		defer func() {
			if recovered := recover(); recovered != nil {
				p.err = cmError("ExecutionError", fmt.Sprint(recovered), nil)
			}
			close(p.done)
		}()
		p.value, p.err = work()
	}()
	return p
}

func resolvedCodePromise(value any) *codePromise {
	p := &codePromise{done: make(chan struct{}), value: value}
	close(p.done)
	return p
}

func rejectedCodePromise(err error) *codePromise {
	p := &codePromise{done: make(chan struct{}), err: err}
	close(p.done)
	return p
}

func (p *codePromise) await() (any, error) {
	if p == nil {
		return codeUndefined, nil
	}
	<-p.done
	return p.value, p.err
}

var blockedCodeModeMembers = map[string]bool{"__proto__": true, "prototype": true, "constructor": true}

func truthy(value any) bool {
	if value == nil || isUndefined(value) {
		return false
	}
	switch v := value.(type) {
	case bool:
		return v
	case string:
		return v != ""
	case float64:
		return v != 0 && !math.IsNaN(v)
	case float32:
		return v != 0 && !math.IsNaN(float64(v))
	case int:
		return v != 0
	case int64:
		return v != 0
	}
	return true
}

