type codeModeMutationQueue struct {
	mu    sync.Mutex
	locks map[string]*sync.Mutex
}

func newCodeModeMutationQueue() *codeModeMutationQueue {
	return &codeModeMutationQueue{locks: map[string]*sync.Mutex{}}
}

func (q *codeModeMutationQueue) lockKeys(keys []string) func() {
	uniqueSet := map[string]bool{}
	for _, key := range keys {
		if key != "" {
			uniqueSet[key] = true
		}
	}
	unique := make([]string, 0, len(uniqueSet))
	for key := range uniqueSet {
		unique = append(unique, key)
	}
	sort.Strings(unique)
	locks := make([]*sync.Mutex, 0, len(unique))
	q.mu.Lock()
	for _, key := range unique {
		lock := q.locks[key]
		if lock == nil {
			lock = &sync.Mutex{}
			q.locks[key] = lock
		}
		locks = append(locks, lock)
	}
	q.mu.Unlock()
	for _, lock := range locks {
		lock.Lock()
	}
	return func() {
		for i := len(locks) - 1; i >= 0; i-- {
			locks[i].Unlock()
		}
	}
}

type codeModeToolRuntime struct {
	registry    *ToolRegistry
	allowed     map[string]bool
	workspace   string
	executionID string
	limits      CodeModeLimits
	ctx         context.Context

	projected     map[string]*projectedTool
	children      map[string]map[string]bool
	semaphore     chan struct{}
	mutationQueue *codeModeMutationQueue

	mu         sync.Mutex
	callCount  int
	receipts   []ToolCallReceipt
	pending    map[*codePromise]bool
	mediaBytes int
	mediaItems int
}

func newCodeModeToolRuntime(ctx context.Context, registry *ToolRegistry, allowed map[string]bool, workspace, executionID string, limits CodeModeLimits) *codeModeToolRuntime {
	concurrency := limits.MaxConcurrentToolCalls
	if concurrency < 1 {
		concurrency = 1
	}
	r := &codeModeToolRuntime{
		registry: registry, allowed: allowed, workspace: workspace, executionID: executionID, limits: limits, ctx: ctx,
		projected: map[string]*projectedTool{}, children: map[string]map[string]bool{}, semaphore: make(chan struct{}, concurrency),
		mutationQueue: newCodeModeMutationQueue(), pending: map[*codePromise]bool{}, receipts: []ToolCallReceipt{},
	}
	used := map[string]bool{}
	for i := range registry.Entries {
		definition := &registry.Entries[i]
		if allowed != nil && !allowed[definition.Name] {
			continue
		}
		var base []string
		if strings.EqualFold(definition.Namespace, "mcp") {
			raw := definition.Name
			lower := strings.ToLower(raw)
			for _, prefix := range []string{"mcp_", "mcp-", "mcp:"} {
				if strings.HasPrefix(lower, prefix) {
					raw = raw[len(prefix):]
					break
				}
			}
			base = []string{"mcp", safeToolSegment(raw)}
		} else {
			base = []string{safeToolSegment(definition.Name)}
		}
		candidate := append([]string(nil), base...)
		suffix := 2
		for used[strings.Join(candidate, ".")] {
			candidate = append([]string(nil), base...)
			candidate[len(candidate)-1] = fmt.Sprintf("%s_%d", base[len(base)-1], suffix)
			suffix++
		}
		key := strings.Join(candidate, ".")
		used[key] = true
		projected := &projectedTool{definition: definition, path: candidate, expression: "tools." + key}
		r.projected[key] = projected
		for index := range candidate {
			parent := strings.Join(candidate[:index], ".")
			if r.children[parent] == nil {
				r.children[parent] = map[string]bool{}
			}
			r.children[parent][candidate[index]] = true
		}
	}
	if r.children[""] == nil {
		r.children[""] = map[string]bool{}
	}
	r.children[""]["$codemode"] = true
	r.children["$codemode"] = map[string]bool{"search": true}
	return r
}

func (r *codeModeToolRuntime) unavailableAllowedTool() string {
	if r.allowed == nil {
		return ""
	}
	for name := range r.allowed {
		if !r.allowed[name] {
			continue
		}
		found := false
		for _, tool := range r.projected {
			if tool.definition.Name == name {
				found = true
				break
			}
		}
		if !found {
			return name
		}
	}
	return ""
}

func (r *codeModeToolRuntime) root() *toolReference { return &toolReference{path: []string{}} }

func (r *codeModeToolRuntime) keys(reference *toolReference) []string {
	set := r.children[strings.Join(reference.path, ".")]
	out := make([]string, 0, len(set))
	for name := range set {
		out = append(out, name)
	}
	sort.Strings(out)
	return out
}

func (r *codeModeToolRuntime) member(reference *toolReference, name string, node ast.Node) (*toolReference, error) {
	if blockedCodeModeMembers[name] {
		return nil, cmError("TypeError", fmt.Sprintf("Property '%s' is not available in Code Mode.", name), node)
	}
	next := append(append([]string(nil), reference.path...), name)
	key := strings.Join(next, ".")
	if r.projected[key] != nil || r.children[key] != nil || key == "$codemode.search" {
		return &toolReference{path: next}, nil
	}
	available := r.keys(reference)
	if len(available) > 8 {
		available = available[:8]
	}
	suggestions := []string{"Use tools.$codemode.search(...) for discovery."}
	if len(available) > 0 {
		suggestions = []string{fmt.Sprintf("Available here: %s. Use tools.$codemode.search(...) for discovery.", strings.Join(available, ", "))}
	}
	return nil, cmError("UnknownTool", "Unknown Code Mode capability tools."+key+".", node, suggestions...)
}

func (r *codeModeToolRuntime) call(reference *toolReference, args []any, node ast.Node) (*codePromise, error) {
	key := strings.Join(reference.path, ".")
	if key == "$codemode.search" {
		if len(args) > 1 {
			return nil, cmError("InvalidToolArguments", "tools.$codemode.search expects at most one input value.", node)
		}
		var input any = map[string]any{}
		if len(args) == 1 {
			input = args[0]
		}
		result, err := r.search(input, node)
		if err != nil {
			return nil, err
		}
		return resolvedCodePromise(internalizeData(result)), nil
	}
	tool := r.projected[key]
	if tool == nil {
		return nil, cmError("UnknownTool", "tools."+key+" is not callable.", node)
	}
	if len(args) != 1 {
		return nil, cmError("InvalidToolArguments", tool.expression+" expects exactly one input value.", node)
	}
	input, err := hostData(args[0], "Arguments for "+tool.expression)
	if err != nil {
		if runtimeErr, ok := err.(*codeModeRuntimeError); ok {
			runtimeErr.Node = node
		}
		return nil, err
	}
	p := startCodePromise(func() (any, error) { return r.execute(tool, input) })
	r.track(p)
	return p, nil
}

func (r *codeModeToolRuntime) track(p *codePromise) {
	r.mu.Lock()
	r.pending[p] = true
	r.mu.Unlock()
	go func() { <-p.done; r.mu.Lock(); delete(r.pending, p); r.mu.Unlock() }()
}

func (r *codeModeToolRuntime) drain() {
	for {
		r.mu.Lock()
		pending := make([]*codePromise, 0, len(r.pending))
		for p := range r.pending {
			pending = append(pending, p)
		}
		r.mu.Unlock()
		if len(pending) == 0 {
			return
		}
		for _, p := range pending {
			<-p.done
		}
	}
}

func (r *codeModeToolRuntime) getReceipts() []ToolCallReceipt {
	r.mu.Lock()
	defer r.mu.Unlock()
	return append([]ToolCallReceipt(nil), r.receipts...)
}

func (r *codeModeToolRuntime) search(input any, node ast.Node) (map[string]any, error) {
	data, err := hostData(input, "Code Mode search input")
	if err != nil {
		return nil, err
	}
	record, ok := data.(map[string]any)
	if !ok {
		return nil, cmError("InvalidToolArguments", "tools.$codemode.search expects an object.", node)
	}
	query := ""
	if value, ok := record["query"].(string); ok {
		query = strings.ToLower(strings.TrimSpace(value))
	}
	namespace := ""
	if value, ok := record["namespace"].(string); ok {
		namespace = strings.ToLower(strings.TrimSpace(value))
	}
	limit := 10
	if value, ok := record["limit"]; ok {
		limit = int(numberValue(value))
		if limit < 1 {
			limit = 1
		}
		if limit > 50 {
			limit = 50
		}
	}
	offset := 0
	if value, ok := record["offset"]; ok {
		offset = int(numberValue(value))
		if offset < 0 {
			offset = 0
		}
	}
	terms := strings.Fields(query)
	type scored struct {
		tool  *projectedTool
		score int
	}
	matches := []scored{}
	for _, tool := range r.projected {
		toolNS := strings.ToLower(tool.definition.Namespace)
		if namespace != "" && toolNS != namespace {
			continue
		}
		name := strings.ToLower(tool.definition.Name)
		description := strings.ToLower(tool.definition.Description)
		score := 0
		for _, term := range terms {
			if name == term {
				score += 100
			} else if strings.Contains(name, term) {
				score += 50
			}
			if toolNS == term {
				score += 30
			} else if strings.Contains(toolNS, term) {
				score += 15
			}
			if strings.Contains(description, term) {
				score += 10
			}
		}
		if namespace != "" {
			score += 1000
		}
		if query == "" || score > 0 {
			matches = append(matches, scored{tool: tool, score: score})
		}
	}
	sort.Slice(matches, func(i, j int) bool {
		if matches[i].score == matches[j].score {
			return matches[i].tool.expression < matches[j].tool.expression
		}
		return matches[i].score > matches[j].score
	})
	if offset > len(matches) {
		offset = len(matches)
	}
	end := offset + limit
	if end > len(matches) {
		end = len(matches)
	}
	items := make([]any, 0, end-offset)
	for _, match := range matches[offset:end] {
		items = append(items, map[string]any{
			"path":        match.tool.expression,
			"description": match.tool.definition.Description,
			"namespace":   match.tool.definition.Namespace,
			"signature":   match.tool.definition.Signature,
		})
	}
	remaining := len(matches) - end
	var next any = nil
	if remaining > 0 {
		next = map[string]any{"offset": float64(end)}
	}
	return map[string]any{"items": items, "remaining": float64(remaining), "next": next}, nil
}

func (r *codeModeToolRuntime) mutationKeys(tool *projectedTool, input any) []string {
	if tool.definition.Name == "apply_patch" {
		return []string{"__workspace_patch__"}
	}
	if !mutatingCodeModeTools[tool.definition.Name] {
		return nil
	}
	record, ok := input.(map[string]any)
	if !ok {
		return []string{"__workspace_mutation__"}
	}
	raw, ok := record["path"].(string)
	if !ok || strings.TrimSpace(raw) == "" {
		return []string{"__workspace_mutation__"}
	}
