	body := "import x from " + escapedDouble + "react" + escapedDouble + ";\n<div className=" + escapedDouble + "card" + escapedDouble + " />"
	want := "import x from \"react\";\n<div className=\"card\" />"
	if got := decodeRedundantTripleQuoteDelimiterEscapes(body, '"'); got != want {
		t.Fatalf("redundant JSX quote escapes not removed: %q", got)
	}

	realQuote := string('"')
	intentional := "const message = " + realQuote + "He said " + escapedDouble + "hello" + escapedDouble + realQuote + ";"
	if got := decodeRedundantTripleQuoteDelimiterEscapes(intentional, '"'); got != intentional {
		t.Fatalf("intentional escaped quotes changed: %q", got)
	}

	backslashes := "const re = /\\w+/;\nconst path = 'C:\\tmp\\x';"
	if got := decodeRedundantTripleQuoteDelimiterEscapes(backslashes, '"'); got != backslashes {
		t.Fatalf("non-quote backslashes changed: %q", got)
	}

	escapedSingle := string([]byte{'\\', '\''})
	singleBody := "<div data-kind=" + escapedSingle + "card" + escapedSingle + ">value</div>"
	if got := decodeRedundantTripleQuoteDelimiterEscapes(singleBody, '\''); got != "<div data-kind='card'>value</div>" {
