const oauthMaxBodyBytes = 128 * 1024

func writeOAuthJSON(w http.ResponseWriter, status int, value any, headers map[string]string) {
	body, err := json.Marshal(value)
	if err != nil {
		http.Error(w, "OAuth response serialization failed", http.StatusInternalServerError)
		return
	}
	for key, value := range headers {
		w.Header().Set(key, value)
	}
	if w.Header().Get("Cache-Control") == "" {
		w.Header().Set("Cache-Control", "no-store")
	}
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.Header().Set("Content-Length", strconv.Itoa(len(body)))
	w.WriteHeader(status)
	_, _ = w.Write(body)
}

func writeOAuthError(w http.ResponseWriter, status int, code, description string, headers map[string]string) {
	writeOAuthJSON(w, status, map[string]any{"error": code, "error_description": description}, headers)
}

func writeOAuthHTML(w http.ResponseWriter, status int, body string, headers map[string]string) {
	for key, value := range headers {
		w.Header().Set(key, value)
	}
	w.Header().Set("Cache-Control", "no-store")
	w.Header().Set("Content-Length", strconv.Itoa(len([]byte(body))))
	w.Header().Set("Content-Security-Policy", "default-src 'none'; base-uri 'none'; frame-ancestors 'none'; script-src 'none'; style-src 'unsafe-inline'")
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Referrer-Policy", "no-referrer")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	w.Header().Set("X-Frame-Options", "DENY")
	w.WriteHeader(status)
	_, _ = io.WriteString(w, body)
}

func oauthRedirect(w http.ResponseWriter, target string) {
	w.Header().Set("Cache-Control", "no-store")
	w.Header().Set("Location", target)
	w.WriteHeader(http.StatusFound)
}

func readOAuthBody(w http.ResponseWriter, r *http.Request) (string, error) {
	if r.ContentLength > oauthMaxBodyBytes {
		return "", errors.New("Request body is too large.")
	}
	reader := http.MaxBytesReader(w, r.Body, oauthMaxBodyBytes)
	defer reader.Close()
	body, err := io.ReadAll(reader)
	if err != nil {
		var tooLarge *http.MaxBytesError
		if errors.As(err, &tooLarge) {
			return "", errors.New("Request body is too large.")
		}
		return "", err
	}
	return string(body), nil
}

func parseRequestedOAuthScopes(raw string, config embeddedOAuthConfig) ([]string, error) {
	if strings.TrimSpace(raw) == "" {
		raw = "planner:read"
	}
	scopes := uniqueScopes(strings.Fields(raw))
	allowed := map[string]bool{}
	for _, scope := range config.AllowedScopes {
		allowed[scope] = true
	}
	containsRead := false
	for _, scope := range scopes {
		if scope == "planner:read" {
			containsRead = true
		}
		if !allowed[scope] {
			return nil, errors.New("The requested scope is not allowed.")
		}
	}
	if !containsRead {
		scopes = append(scopes, "planner:read")
	}
	return scopes, nil
}

func oauthLoginPage(config embeddedOAuthConfig, sessionID string, session oauthLoginSession, message string) string {
	messageHTML := ""
	if message != "" {
