}

func redirectOAuthError(w http.ResponseWriter, redirectURI, code, description, state string) {
	target, _ := url.Parse(redirectURI)
	query := target.Query()
	query.Set("error", code)
	query.Set("error_description", description)
	if state != "" {
		query.Set("state", state)
	}
	target.RawQuery = query.Encode()
	oauthRedirect(w, target.String())
}

func oauthClientCredentials(r *http.Request, form url.Values) (clientID, clientSecret string, secretSupplied bool) {
	authorization := r.Header.Get("Authorization")
	if strings.HasPrefix(authorization, "Basic ") {
		decoded, err := base64.StdEncoding.DecodeString(strings.TrimPrefix(authorization, "Basic "))
		if err != nil {
			return "", "", false
		}
		value := string(decoded)
		if separator := strings.IndexByte(value, ':'); separator >= 0 {
			return value[:separator], value[separator+1:], true
		}
	}
	clientID = form.Get("client_id")
	values, present := form["client_secret"]
	if present && len(values) > 0 {
		return clientID, values[0], true
	}
	return clientID, "", false
}

func oauthCookieValue(r *http.Request, name string) string {
	cookie, err := r.Cookie(name)
	if err != nil {
		return ""
	}
	value, err := url.QueryUnescape(cookie.Value)
	if err != nil {
		return ""
	}
	return value
}

func oauthLoginThrottleKey(r *http.Request, username string) string {
	remote := r.RemoteAddr
	if host, _, err := net.SplitHostPort(remote); err == nil {
		remote = host
	}
	if remote == "" {
		remote = "unknown"
	}
	return remote + ":" + strings.ToLower(username)
}

func oauthClientRegistrationResponse(client oauthClient, clientSecret string) map[string]any {
	response := map[string]any{
