func (provider *EmbeddedOAuthProvider) authorizationEndpoint(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		w.Header().Set("Allow", "GET")
		writeOAuthError(w, http.StatusMethodNotAllowed, "method_not_allowed", "The authorization endpoint accepts GET requests.", nil)
		return
	}
	query := r.URL.Query()
	clientID := query.Get("client_id")
	redirectURI := query.Get("redirect_uri")
	state := query.Get("state")
	client, ok := provider.store.getClient(clientID)
	validRedirect := false
	if ok && redirectURI != "" && validOAuthRedirectURI(redirectURI) {
		for _, configured := range client.RedirectURIs {
			if configured == redirectURI {
				validRedirect = true
				break
			}
		}
	}
	if !ok || !validRedirect {
		writeOAuthError(w, http.StatusBadRequest, "invalid_request", "The client_id or redirect_uri is invalid.", nil)
