		writeOAuthError(w, http.StatusBadRequest, "invalid_request", "The authorization session is no longer valid.", nil)
		return
	}
	code, err := provider.store.createAuthorizationCode(oauthAuthorizationCode{
		ClientID:      consumed.Authorization.ClientID,
		RedirectURI:   consumed.Authorization.RedirectURI,
		CodeChallenge: consumed.Authorization.CodeChallenge,
		Scope:         consumed.Authorization.Scope,
		Resource:      consumed.Authorization.Resource,
		Username:      provider.config.Username,
