			return
		}
		if embeddedProvider != nil && embeddedProvider.HandleRequest(w, r) {
			return
		}
		if authRuntime != nil && handleOAuthMetadataHTTP(w, r, authRuntime) {
			return
		}
		if options.AdditionalHandler != nil && additionalPathRoot != "" && strings.HasPrefix(r.URL.Path, additionalPathRoot) {
			options.AdditionalHandler.ServeHTTP(w, r)
			return
		}
		if r.URL.Path != path {
			writeJSON(w, 404, map[string]any{"error": "Not found."})
			return
		}
		if r.Method != http.MethodGet && r.Method != http.MethodPost {
			w.Header().Set("Allow", "GET, POST, OPTIONS")
			writeJSON(w, 405, map[string]any{"error": "The MCP endpoint accepts GET and POST requests."})
			return
		}
		if authRuntime != nil {
			AuthenticatePlannerHTTP(authRuntime, handler).ServeHTTP(w, r)
			return
		}
		handler.ServeHTTP(w, r)
	})
	httpServer := &http.Server{Handler: baseHandler, ReadHeaderTimeout: 10 * time.Second}
	running := &RunningHTTPServer{Server: httpServer, listener: listener, terminal: terminal}
	running.Address.Host = actualHost
	running.Address.Port = actualPort
	go func() { _ = httpServer.Serve(listener) }()
	runningCloseState.Store(running, func() {
		closingMu.Lock()
		closing = true
		closingMu.Unlock()
	})
	return running, nil
}

var runningCloseState sync.Map

func (r *RunningHTTPServer) Close() error {
	if r == nil {
		return nil
	}
	var first error
	r.closeOnce.Do(func() {
		if v, ok := runningCloseState.LoadAndDelete(r); ok {
			v.(func())()
		}
		if r.terminal != nil {
			if e := r.terminal.Close(); e != nil && first == nil {
				first = e
			}
		}
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		if r.Server != nil {
			if e := r.Server.Shutdown(ctx); e != nil && first == nil {
				first = e
			}
		}
	})
	return first
}

