func (v *JWTAccessTokenVerifier) keyFor(token *jwt.Token) (any, error) {
	kid, _ := token.Header["kid"].(string)
	if key := v.staticKeys[kid]; key != nil {
		return key, nil
	}
	v.mu.RLock()
	key := v.keys[kid]
