func scopesFromClaims(c jwt.MapClaims) ScopeSet {
	out := ScopeSet{}
	if s, ok := c["scope"].(string); ok {
		for _, x := range strings.Fields(s) {
			out[x] = true
		}
	}
	switch s := c["scp"].(type) {
	case string:
		for _, x := range strings.Fields(s) {
			out[x] = true
		}
	case []any:
		for _, x := range s {
			if str, ok := x.(string); ok {
				out[str] = true
			}
		}
	}
	return out
}
func (v *JWTAccessTokenVerifier) VerifyAccessToken(raw string) (*PlannerAuthInfo, error) {
	parser := jwt.NewParser(jwt.WithValidMethods([]string{"RS256", "RS384", "RS512", "PS256", "PS384", "PS512", "ES256", "ES384", "ES512", "EdDSA"}), jwt.WithIssuer(v.Issuer), jwt.WithAudience(v.Audience), jwt.WithExpirationRequired())
	claims := jwt.MapClaims{}
	token, err := parser.ParseWithClaims(raw, claims, v.keyFor)
	if err != nil || !token.Valid {
		if err == nil {
			err = errors.New("invalid access token")
		}
		return nil, err
	}
	clientID, _ := claims["sub"].(string)
	if clientID == "" {
		clientID, _ = claims["client_id"].(string)
	}
	var exp int64
	switch x := claims["exp"].(type) {
	case float64:
		exp = int64(x)
	case json.Number:
		exp, _ = x.Int64()
	}
	return &PlannerAuthInfo{ClientID: clientID, Scopes: scopesFromClaims(claims), Token: raw, ExpiresAt: exp}, nil
}

func AuthenticatePlannerHTTP(runtime *PlannerAuthRuntime, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		auth := strings.TrimSpace(r.Header.Get("Authorization"))
		if !strings.HasPrefix(strings.ToLower(auth), "bearer ") {
			writeBearerChallenge(w, runtime, http.StatusUnauthorized, "invalid_token", "Bearer token is required")
			return
		}
		token := strings.TrimSpace(auth[len("Bearer "):])
		info, err := runtime.Verifier.VerifyAccessToken(token)
		if err != nil {
			writeBearerChallenge(w, runtime, http.StatusUnauthorized, "invalid_token", "Access token is invalid")
			return
		}
		for _, s := range runtime.RequiredScopes {
			if !info.Scopes[s] {
				writeBearerChallenge(w, runtime, http.StatusForbidden, "insufficient_scope", "Required OAuth scope is missing")
				return
			}
		}
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), plannerAuthContextKey{}, info)))
	})
}
func writeBearerChallenge(w http.ResponseWriter, runtime *PlannerAuthRuntime, status int, code, description string) {
	value := fmt.Sprintf("Bearer resource_metadata=\"%s\", error=\"%s\", error_description=\"%s\"", runtime.ResourceMetadataURL, code, description)
	if len(runtime.RequiredScopes) > 0 {
		value += fmt.Sprintf(", scope=\"%s\"", strings.Join(runtime.RequiredScopes, " "))
	}
	w.Header().Set("WWW-Authenticate", value)
	writeJSON(w, status, map[string]any{"error": code, "error_description": description})
}
func handleOAuthMetadataHTTP(w http.ResponseWriter, r *http.Request, runtime *PlannerAuthRuntime) bool {
	resourcePath := func() string { u, _ := url.Parse(runtime.ResourceMetadataURL); return u.Path }()
	isProtectedResource := r.URL.Path == resourcePath || r.URL.Path == "/.well-known/oauth-protected-resource"
	isAuthorizationServer := r.URL.Path == "/.well-known/oauth-authorization-server"
	if !isProtectedResource && !isAuthorizationServer {
		return false
	}
	if r.Method != http.MethodGet {
		w.Header().Set("Allow", "GET, OPTIONS")
		writeJSON(w, http.StatusMethodNotAllowed, map[string]any{"error": "OAuth metadata endpoints accept GET requests."})
		return true
	}
	if isAuthorizationServer {
		writeJSON(w, http.StatusOK, oauthMetadataDocument(runtime.OAuth))
		return true
	}
	writeJSON(w, http.StatusOK, map[string]any{
		"resource":                 runtime.ResourceServerURL,
		"authorization_servers":    []string{runtime.OAuth.Issuer},
		"scopes_supported":         uniqueScopes(runtime.RequiredScopes, []string{runtime.MemoryScope, runtime.PlanScope, runtime.SourceMutationScope, runtime.TerminalExecutionScope}),
		"resource_name":            runtime.ResourceName,
		"bearer_methods_supported": []string{"header"},
	})
	return true
}

