package relay

import (
	"context"
	"crypto/rand"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"sort"
	"strings"
	"sync"
	"time"
)

type DeviceConfig struct {
	DeviceID   string
	DeviceName string
	Secret     string
}

type BrokerOptions struct {
	HeartbeatTTL time.Duration
	JobTimeout   time.Duration
	QueueSize    int
}

type DeviceInfo struct {
	DeviceID        string    `json:"device_id"`
	Name            string    `json:"name"`
	Status          string    `json:"status"`
	LastSeen        time.Time `json:"last_seen,omitempty"`
	AgentVersion    string    `json:"agent_version,omitempty"`
	TidecodeVersion string    `json:"tidecode_version,omitempty"`
}

type Job struct {
	RequestID string         `json:"request_id"`
	DeviceID  string         `json:"device_id"`
	Method    string         `json:"method"`
	Arguments map[string]any `json:"arguments"`
	CreatedAt time.Time      `json:"created_at"`
	Deadline  time.Time      `json:"deadline"`
}

type JobResult struct {
	RawResult json.RawMessage
	Error     string
}

type deviceState struct {
	id              string
	configuredName  string
	announcedName   string
	secretHash      [32]byte
	lastSeen        time.Time
	agentVersion    string
	tidecodeVersion string
	queue           chan *Job
}

type jobState struct {
	job      *Job
	status   string
	resultCh chan JobResult
}

type Broker struct {
	mu           sync.Mutex
	devices      map[string]*deviceState
	jobs         map[string]*jobState
	heartbeatTTL time.Duration
	jobTimeout   time.Duration
}

func NewBroker(configs []DeviceConfig, options BrokerOptions) (*Broker, error) {
	heartbeatTTL := options.HeartbeatTTL
	if heartbeatTTL <= 0 {
		heartbeatTTL = 45 * time.Second
	}
	jobTimeout := options.JobTimeout
	if jobTimeout <= 0 {
		jobTimeout = 90 * time.Second
	}
	queueSize := options.QueueSize
	if queueSize <= 0 {
		queueSize = 8
	}

	broker := &Broker{
		devices:      make(map[string]*deviceState, len(configs)),
		jobs:         map[string]*jobState{},
		heartbeatTTL: heartbeatTTL,
		jobTimeout:   jobTimeout,
	}
	for _, config := range configs {
		id := strings.TrimSpace(config.DeviceID)
		secret := strings.TrimSpace(config.Secret)
		if id == "" {
			return nil, errors.New("device_id must be non-empty")
		}
		if secret == "" {
			return nil, fmt.Errorf("device %s has an empty secret", id)
		}
		if _, exists := broker.devices[id]; exists {
			return nil, fmt.Errorf("duplicate device_id %s", id)
		}
		broker.devices[id] = &deviceState{
			id:             id,
			configuredName: strings.TrimSpace(config.DeviceName),
			secretHash:     sha256.Sum256([]byte(secret)),
			queue:          make(chan *Job, queueSize),
		}
	}
	return broker, nil
}

func (b *Broker) Authenticate(deviceID, secret string) bool {
	b.mu.Lock()
	device := b.devices[strings.TrimSpace(deviceID)]
	b.mu.Unlock()
	if device == nil {
		return false
	}
	candidate := sha256.Sum256([]byte(secret))
	return subtle.ConstantTimeCompare(device.secretHash[:], candidate[:]) == 1
}

func (b *Broker) Touch(deviceID, announcedName, agentVersion, tidecodeVersion string) error {
	b.mu.Lock()
	defer b.mu.Unlock()
	device := b.devices[deviceID]
	if device == nil {
		return errors.New("unknown device")
	}
	device.lastSeen = time.Now().UTC()
	if name := strings.TrimSpace(announcedName); name != "" {
		device.announcedName = name
	}
	if version := strings.TrimSpace(agentVersion); version != "" {
		device.agentVersion = version
	}
	if version := strings.TrimSpace(tidecodeVersion); version != "" {
		device.tidecodeVersion = version
	}
	return nil
}

func (b *Broker) deviceOnlineLocked(device *deviceState, now time.Time) bool {
	return device != nil && !device.lastSeen.IsZero() && now.Sub(device.lastSeen) <= b.heartbeatTTL
}

func (b *Broker) ListDevices() []DeviceInfo {
	b.mu.Lock()
	defer b.mu.Unlock()
	now := time.Now().UTC()
	out := make([]DeviceInfo, 0, len(b.devices))
	for _, device := range b.devices {
		name := device.configuredName
		if name == "" {
			name = device.announcedName
		}
		if name == "" {
			name = device.id
		}
		status := "offline"
		if b.deviceOnlineLocked(device, now) {
			status = "online"
		}
		out = append(out, DeviceInfo{
			DeviceID:        device.id,
			Name:            name,
			Status:          status,
			LastSeen:        device.lastSeen,
			AgentVersion:    device.agentVersion,
			TidecodeVersion: device.tidecodeVersion,
		})
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].Name == out[j].Name {
			return out[i].DeviceID < out[j].DeviceID
		}
		return out[i].Name < out[j].Name
	})
	return out
}

func newRequestID() (string, error) {
	var raw [16]byte
	if _, err := rand.Read(raw[:]); err != nil {
		return "", err
	}
	return "req_" + hex.EncodeToString(raw[:]), nil
}

func allowedMethod(method string) bool {
	switch method {
	case "tcode_mode", "write", "apply_patch":
		return true
	default:
		return false
	}
}

func (b *Broker) Submit(ctx context.Context, deviceID, method string, arguments map[string]any) (JobResult, error) {
	if !allowedMethod(method) {
		return JobResult{}, fmt.Errorf("unsupported relay method %q", method)
	}
	requestID, err := newRequestID()
	if err != nil {
		return JobResult{}, err
	}
	now := time.Now().UTC()
	deadline := now.Add(b.jobTimeout)
	if callerDeadline, ok := ctx.Deadline(); ok && callerDeadline.Before(deadline) {
		deadline = callerDeadline
	}

	b.mu.Lock()
	device := b.devices[deviceID]
	if device == nil {
		b.mu.Unlock()
		return JobResult{}, errors.New("unknown device_id")
	}
	if !b.deviceOnlineLocked(device, now) {
		b.mu.Unlock()
		return JobResult{}, errors.New("device is offline")
	}
	job := &Job{
		RequestID: requestID,
		DeviceID:  deviceID,
		Method:    method,
		Arguments: arguments,
		CreatedAt: now,
		Deadline:  deadline,
	}
	state := &jobState{job: job, status: "queued", resultCh: make(chan JobResult, 1)}
	b.jobs[requestID] = state
	queue := device.queue
	b.mu.Unlock()

	select {
	case queue <- job:
	default:
		b.mu.Lock()
		delete(b.jobs, requestID)
		b.mu.Unlock()
		return JobResult{}, errors.New("device job queue is full")
	}

	waitCtx, cancel := context.WithDeadline(ctx, deadline)
	defer cancel()
	select {
	case result := <-state.resultCh:
		return result, nil
	case <-waitCtx.Done():
		b.mu.Lock()
		if current := b.jobs[requestID]; current == state {
			delete(b.jobs, requestID)
			state.status = "cancelled"
		}
		b.mu.Unlock()
		if errors.Is(waitCtx.Err(), context.DeadlineExceeded) {
			return JobResult{}, errors.New("device request timed out")
		}
		return JobResult{}, waitCtx.Err()
	}
}

func (b *Broker) Claim(ctx context.Context, deviceID string, maxWait time.Duration) (*Job, error) {
	b.mu.Lock()
	device := b.devices[deviceID]
	b.mu.Unlock()
	if device == nil {
		return nil, errors.New("unknown device")
	}
	if maxWait <= 0 {
		maxWait = 20 * time.Second
	}
	if maxWait > 25*time.Second {
		maxWait = 25 * time.Second
	}
	timer := time.NewTimer(maxWait)
	defer timer.Stop()
	for {
		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case <-timer.C:
			return nil, nil
		case job := <-device.queue:
			now := time.Now().UTC()
			b.mu.Lock()
			state := b.jobs[job.RequestID]
			if state == nil || state.status != "queued" || now.After(job.Deadline) {
				if state != nil {
					delete(b.jobs, job.RequestID)
					state.status = "expired"
				}
				b.mu.Unlock()
				continue
			}
			state.status = "claimed"
			b.mu.Unlock()
			copyJob := *job
			return &copyJob, nil
		}
	}
}

func (b *Broker) Complete(deviceID, requestID string, rawResult json.RawMessage) error {
	if len(rawResult) == 0 {
		return errors.New("result payload is empty")
	}
	return b.finish(deviceID, requestID, JobResult{RawResult: append(json.RawMessage(nil), rawResult...)})
}

func (b *Broker) Fail(deviceID, requestID, message string) error {
	message = strings.TrimSpace(message)
	if message == "" {
		message = "agent execution failed"
	}
	return b.finish(deviceID, requestID, JobResult{Error: message})
}

func (b *Broker) finish(deviceID, requestID string, result JobResult) error {
	b.mu.Lock()
	state := b.jobs[requestID]
	if state == nil {
		b.mu.Unlock()
		return errors.New("request is not pending")
	}
	if state.job.DeviceID != deviceID {
		b.mu.Unlock()
		return errors.New("request belongs to another device")
	}
	if state.status != "claimed" {
		b.mu.Unlock()
		return fmt.Errorf("request is %s, not claimed", state.status)
	}
	state.status = "completed"
	delete(b.jobs, requestID)
	b.mu.Unlock()

	select {
	case state.resultCh <- result:
		return nil
	default:
		return errors.New("request result was already delivered")
	}
}

