const DefaultHTTPHost = "127.0.0.1"
const DefaultHTTPPort = 3000
const DefaultMCPPath = "/mcp"

type HTTPServerOptions struct {
	Auth               *PlannerAuthRuntime
	DisableAuth        bool
	Environment        map[string]string
	Host               string
