func envValue(env map[string]string, key string) string {
	if env != nil {
		return strings.TrimSpace(env[key])
	}
	return strings.TrimSpace(os.Getenv(key))
}

func normalizeRoute(route, fallback string) string {
	v := strings.TrimSpace(route)
	if v == "" {
		v = fallback
	}
	if !strings.HasPrefix(v, "/") {
		v = "/" + v
	}
	return v
}

func normalizeHostname(host string) string {
	return strings.ToLower(strings.Trim(strings.TrimSpace(host), "[]"))
}
func loopbackHost(host string) bool {
	h := normalizeHostname(host)
	return h == "localhost" || h == "127.0.0.1" || h == "::1"
}

func hostHeaderName(hostport string) string {
	if hostport == "" {
		return ""
	}
	h, _, err := net.SplitHostPort(hostport)
	if err == nil {
		return normalizeHostname(h)
	}
	if strings.HasPrefix(hostport, "[") && strings.Contains(hostport, "]") {
		return normalizeHostname(hostport[1:strings.Index(hostport, "]")])
	}
	return normalizeHostname(strings.Split(hostport, ":")[0])
}

func allowedHost(r *http.Request, bound string, public *url.URL, env map[string]string) bool {
	requestHost := hostHeaderName(r.Host)
	if requestHost == "" {
		return false
	}
	bound = normalizeHostname(bound)
	if loopbackHost(bound) {
		return loopbackHost(requestHost)
	}
	allowed := map[string]bool{bound: true}
	if public != nil {
		allowed[strings.ToLower(public.Hostname())] = true
	}
	for _, v := range strings.Split(envValue(env, "MCP_ALLOWED_HOSTS"), ",") {
		if x := normalizeHostname(v); x != "" {
			allowed[x] = true
		}
	}
	return allowed[requestHost]
}

func allowedOrigin(r *http.Request) bool {
	origin := strings.TrimSpace(r.Header.Get("Origin"))
	if origin == "" {
		return true
	}
	for _, allowed := range strings.Split(os.Getenv("MCP_ALLOWED_ORIGINS"), ",") {
		if strings.EqualFold(strings.TrimSpace(allowed), origin) {
			return true
		}
	}
	u, err := url.Parse(origin)
	if err != nil || (u.Scheme != "http" && u.Scheme != "https") {
		return false
	}
	requestHost := hostHeaderName(r.Host)
	originHost := strings.ToLower(u.Hostname())
	return originHost == requestHost || (loopbackHost(originHost) && loopbackHost(requestHost))
}

func corsHeaders(w http.ResponseWriter, r *http.Request) {
	origin := r.Header.Get("Origin")
	if origin == "" {
		origin = "*"
	} else {
		w.Header().Add("Vary", "Origin")
	}
	w.Header().Set("Access-Control-Allow-Origin", origin)
	w.Header().Set("Access-Control-Allow-Headers", "Authorization, Content-Type, MCP-Protocol-Version, Mcp-Session-Id, Last-Event-ID, X-Tidecode-Device-ID")
	w.Header().Set("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
	w.Header().Set("Access-Control-Expose-Headers", "Mcp-Session-Id, MCP-Protocol-Version, WWW-Authenticate")
}

func writeJSON(w http.ResponseWriter, status int, value any) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(value)
}

func publicURLFor(options HTTPServerOptions, host string, port int, path string) (*url.URL, error) {
	configured := strings.TrimSpace(options.PublicURL)
	if configured == "" {
		configured = envValue(options.Environment, "MCP_PUBLIC_URL")
	}
	if configured != "" {
		u, err := url.Parse(configured)
		if err != nil {
			return nil, err
		}
		if u.Path != path {
			return nil, fmt.Errorf("MCP_PUBLIC_URL must end with the configured MCP path %s.", path)
		}
		return u, nil
	}
	h := host
	if strings.Contains(h, ":") && !strings.HasPrefix(h, "[") {
		h = "[" + h + "]"
	}
	return url.Parse(fmt.Sprintf("http://%s:%d%s", h, port, path))
}

func StartHTTPServer(options HTTPServerOptions) (*RunningHTTPServer, error) {
	host := strings.TrimSpace(options.Host)
	if host == "" {
		host = envValue(options.Environment, "MCP_HTTP_HOST")
	}
	if host == "" {
		host = DefaultHTTPHost
