func validateGatewayTransport(value string) (string, error) {
	mode := strings.ToLower(strings.TrimSpace(value))
	if mode == "" {
		return "", nil
	}
	switch mode {
	case gatewayTransportDirect, gatewayTransportBrowser, gatewayTransportAuto:
		return mode, nil
	default:
		return "", fmt.Errorf("unsupported gateway transport %q; expected direct, browser, or auto", value)
	}
}

func effectiveGatewayTransport(value, browserRelayListen string) (string, error) {
	mode, err := validateGatewayTransport(value)
	if err != nil {
		return "", err
	}
	if mode != "" {
		return mode, nil
	}
	if strings.TrimSpace(browserRelayListen) != "" {
		return gatewayTransportAuto, nil
	}
