	config.DeviceSecret = strings.TrimSpace(config.DeviceSecret)
	config.LocalMCPURL = strings.TrimSpace(config.LocalMCPURL)
	if config.GatewayURL == "" {
		return nil, errors.New("gateway URL is required")
	}
	parsedGateway, err := url.Parse(config.GatewayURL)
	if err != nil || (parsedGateway.Scheme != "http" && parsedGateway.Scheme != "https") || parsedGateway.Host == "" {
		return nil, errors.New("gateway URL must be an absolute HTTP or HTTPS URL")
	}
	if config.DeviceID == "" {
		return nil, errors.New("device ID is required")
	}
	if config.DeviceSecret == "" {
		return nil, errors.New("device secret is required")
	}
	if config.DeviceName == "" {
		config.DeviceName = config.DeviceID
	}
	if config.LocalMCPURL == "" {
		config.LocalMCPURL = "http://127.0.0.1:3009/mcp"
	}
	parsedLocal, err := url.Parse(config.LocalMCPURL)
	if err != nil || parsedLocal.Scheme != "http" || parsedLocal.Host == "" {
		return nil, errors.New("local MCP URL must be an absolute HTTP URL")
	}
	localHost := strings.ToLower(parsedLocal.Hostname())
	localIP := net.ParseIP(localHost)
	if localHost != "localhost" && (localIP == nil || !localIP.IsLoopback()) {
		return nil, errors.New("local MCP URL must use a loopback host")
	}
	if config.PollWait <= 0 {
		config.PollWait = 15 * time.Second
	}
	if config.PollWait > 25*time.Second {
		config.PollWait = 25 * time.Second
	}
	if config.HeartbeatEvery <= 0 {
		config.HeartbeatEvery = 10 * time.Second
	}
	if config.ReconnectMin <= 0 {
		config.ReconnectMin = time.Second
	}
	if config.ReconnectMax <= 0 {
		config.ReconnectMax = 20 * time.Second
	}
	if config.GatewayHTTPClient == nil {
		config.GatewayHTTPClient = &http.Client{Timeout: config.PollWait + 15*time.Second}
	}
	config.BrowserRelayListen = strings.TrimSpace(config.BrowserRelayListen)
	config.BrowserRelayOrigin = strings.TrimSpace(config.BrowserRelayOrigin)
	transportMode, err := effectiveGatewayTransport(config.GatewayTransport, config.BrowserRelayListen)
	if err != nil {
		return nil, err
	}
	config.GatewayTransport = transportMode
	switch transportMode {
	case gatewayTransportDirect:
	case gatewayTransportBrowser:
		if config.BrowserRelayListen == "" {
			return nil, errors.New("browser gateway transport requires browser relay listen address")
