	case gatewayTransportAuto:
		if config.BrowserRelayListen == "" {
			return nil, errors.New("auto gateway transport requires browser relay listen address")
		}
		fallback, err := newBrowserFallbackTransport(BrowserFallbackConfig{
			Listen:        config.BrowserRelayListen,
			AllowedOrigin: config.BrowserRelayOrigin,
		}, config.GatewayHTTPClient.Transport)
		if err != nil {
