	return &Agent{config: config, logf: config.Logf}, nil
}

func (a *Agent) endpoint(path string) string {
	return a.config.GatewayURL + path
}

func (a *Agent) newGatewayRequest(ctx context.Context, method, endpoint string, body io.Reader) (*http.Request, error) {
	req, err := http.NewRequestWithContext(ctx, method, endpoint, body)
	if err != nil {
		return nil, err
	}
	req.Header.Set("Authorization", "Bearer "+a.config.DeviceSecret)
	req.Header.Set("X-Tidecode-Device-ID", a.config.DeviceID)
	if body != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	return req, nil
}

type gatewayHTTPError struct {
	statusCode int
}

func (e *gatewayHTTPError) Error() string {
	if status := http.StatusText(e.statusCode); status != "" {
		return fmt.Sprintf("gateway returned HTTP %d (%s)", e.statusCode, status)
	}
	return fmt.Sprintf("gateway returned HTTP %d", e.statusCode)
}

func responseError(resp *http.Response) error {
	// Drain a bounded amount so the transport can reuse the connection, but do
	// not put a gateway response body in an agent error. Error bodies can contain
	// details that are not appropriate for agent logs.
	_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 32*1024))
	return &gatewayHTTPError{statusCode: resp.StatusCode}
}

func diagnosticError(err error) string {
	if err == nil {
		return "unknown error"
	}
	var gatewayErr *gatewayHTTPError
	if errors.As(err, &gatewayErr) {
		return fmt.Sprintf("HTTP %d", gatewayErr.statusCode)
	}
	if errors.Is(err, context.DeadlineExceeded) {
		return "request timed out"
	}
	if errors.Is(err, context.Canceled) {
		return "request canceled"
	}
	var networkErr net.Error
	if errors.As(err, &networkErr) {
		if networkErr.Timeout() {
			return "network timeout"
		}
		return "network error: " + networkErr.Error()
	}
	message := strings.Join(strings.Fields(err.Error()), " ")
	if len(message) > 256 {
		message = message[:256] + "..."
	}
	return message
}

func (a *Agent) connect(ctx context.Context) error {
	payload, err := json.Marshal(connectRequest{
		DeviceName:   a.config.DeviceName,
		AgentVersion: AgentVersion,
	})
	if err != nil {
		return fmt.Errorf("encode gateway registration: %w", err)
	}
	req, err := a.newGatewayRequest(ctx, http.MethodPost, a.endpoint("/agent/v1/connect"), bytes.NewReader(payload))
	if err != nil {
		return err
	}
	resp, err := a.config.GatewayHTTPClient.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return responseError(resp)
	}
	var result connectResponse
	if err := json.NewDecoder(io.LimitReader(resp.Body, maxAgentBodyBytes)).Decode(&result); err != nil {
		return fmt.Errorf("decode gateway registration response: %w", err)
	}
	if result.DeviceID != a.config.DeviceID || result.Status != "online" {
		return errors.New("gateway returned an invalid registration response")
	}
	return nil
}

func (a *Agent) heartbeat(ctx context.Context) error {
	req, err := a.newGatewayRequest(ctx, http.MethodPost, a.endpoint("/agent/v1/heartbeat"), nil)
	if err != nil {
		return err
	}
	resp, err := a.config.GatewayHTTPClient.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusNoContent {
		return responseError(resp)
	}
	return nil
}

func gatewayTransportError(err error) bool {
	var urlErr *url.Error
	return errors.As(err, &urlErr)
}

func gatewayHTTPStatus(err error, statuses ...int) bool {
	var gatewayErr *gatewayHTTPError
	if !errors.As(err, &gatewayErr) {
		return false
	}
	for _, status := range statuses {
		if gatewayErr.statusCode == status {
			return true
		}
	}
