	}

	defaultHost := yamlConfig.Server.Host
	if defaultHost == "" {
		defaultHost = "127.0.0.1"
	}
	defaultPort := yamlConfig.Server.Port
	if defaultPort == 0 {
		defaultPort = 4000
	}
	defaultPublicURL := yamlConfig.Public.MCPURL

	flags := flag.NewFlagSet("tidecode-gateway", flag.ContinueOnError)
	flags.SetOutput(os.Stdout)
	host := flags.String("host", defaultHost, "gateway HTTP bind host")
	port := flags.Int("port", defaultPort, "gateway HTTP bind port")
	publicURL := flags.String("public-url", defaultPublicURL, "public gateway MCP URL used for OAuth metadata")
	disableAuth := flags.Bool("disable-auth", false, "disable public MCP OAuth; allowed only when binding to loopback")
	if err := flags.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			return nil
		}
		return err
	}

	configs, err := yamlConfig.DeviceConfigs()
	if err != nil {
		return err
	}
	broker, err := relay.NewBroker(configs, relay.BrokerOptions{})
	if err != nil {
		return err
	}
	agentHandler := relay.NewAgentHTTPHandler(broker)
	serverFactory := func(r *http.Request, scopes tidecode.ScopeSet) *mcp.Server {
		return relay.NewGatewayMCPServer(broker, scopes, relay.DefaultGatewayInstructionsPath)
	}

	running, err := tidecode.StartHTTPServer(tidecode.HTTPServerOptions{
		DisableAuth:        *disableAuth,
		Host:               *host,
		Port:               *port,
		PortSet:            true,
		PublicURL:          *publicURL,
		ServerFactory:      serverFactory,
		AdditionalHandler:  agentHandler,
		AdditionalPathRoot: "/agent/v1",
	})
	if err != nil {
		return err
	}
	defer running.Close()
	fmt.Fprintf(os.Stderr, "[gateway] MCP listening on http://%s:%d%s\n", running.Address.Host, running.Address.Port, tidecode.DefaultMCPPath)
	fmt.Fprintf(os.Stderr, "[gateway] agent API available under /agent/v1/\n")

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()
	<-ctx.Done()
	return running.Close()
}

func main() {
	if err := run(os.Args[1:]); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

