func (i *codeModeInterpreter) invokePromise(name string, args []any, node ast.Node) (any, error) {
	var first any = codeUndefined
	if len(args) > 0 {
		first = args[0]
	}
	switch name {
	case "resolve":
		if promise, ok := first.(*codePromise); ok {
			return promise, nil
		}
		return resolvedCodePromise(first), nil
	case "reject":
		return rejectedCodePromise(&programThrow{value: first}), nil
	}
	input, ok := first.(*codeArray)
	if !ok {
		return nil, i.attach(cmError("TypeError", fmt.Sprintf("Promise.%s expects an array.", name), node), node)
	}
	promises := append([]any(nil), input.items...)
	switch name {
	case "all":
		return startCodePromise(func() (any, error) {
			out := newCodeArray()
			for _, item := range promises {
				value, err := i.resolveAwaitable(item, node)
				if err != nil {
					return nil, err
				}
				out.items = append(out.items, value)
			}
			return out, nil
		}), nil
	case "allSettled":
		return startCodePromise(func() (any, error) {
			out := newCodeArray()
			for _, item := range promises {
				value, err := i.resolveAwaitable(item, node)
				record := newCodeObject()
				if err != nil {
					record.props["status"] = "rejected"
					record.props["reason"] = internalizeData(safeErrorValue(err))
				} else {
					record.props["status"] = "fulfilled"
					record.props["value"] = value
				}
				out.items = append(out.items, record)
			}
			return out, nil
		}), nil
	case "race":
		return startCodePromise(func() (any, error) {
			if len(promises) == 0 {
				select {
				case <-i.ctx.Done():
					return nil, cmError("Cancelled", "Code Mode execution was aborted.", node)
				}
			}
			type outcome struct {
				value any
				err   error
			}
			ch := make(chan outcome, len(promises))
			for _, item := range promises {
				candidate := item
				go func() { value, err := i.resolveAwaitable(candidate, node); ch <- outcome{value: value, err: err} }()
			}
			result := <-ch
			return result.value, result.err
		}), nil
	case "any":
		return startCodePromise(func() (any, error) {
			if len(promises) == 0 {
				return nil, cmError("ExecutionError", "All promises were rejected.", node)
			}
			type outcome struct {
				value any
				err   error
			}
			ch := make(chan outcome, len(promises))
			for _, item := range promises {
				candidate := item
				go func() { value, err := i.resolveAwaitable(candidate, node); ch <- outcome{value: value, err: err} }()
			}
			for range promises {
				result := <-ch
				if result.err == nil {
					return result.value, nil
				}
			}
			return nil, cmError("ExecutionError", "All promises were rejected.", node)
		}), nil
	default:
		return nil, i.attach(cmError("TypeError", fmt.Sprintf("Promise.%s is not available in Tidecode Code Mode.", name), node), node)
	}
}

