func serializeCodeModeToolResult(result ToolResult) map[string]any {
	out := map[string]any{"status": result.Status, "summary": result.Summary}
	if result.Body != "" {
		out["body"] = result.Body
	}
	semantics := modelSemantics(result.Semantics)
	if semantics != nil {
		out["semantics"] = semantics
	}
	if result.Subject != nil {
		out["subject"] = map[string]any{"kind": result.Subject.Kind, "path": result.Subject.Path}
	}
