func (i *codeModeInterpreter) evaluateNew(n *ast.NewExpression, env *environment) (any, error) {
	callee, err := i.evaluate(n.Callee, env)
	if err != nil {
		return nil, err
	}
	fn, ok := callee.(*nativeFunction)
	if !ok || !map[string]bool{"Error": true, "TypeError": true, "RangeError": true, "SyntaxError": true, "ReferenceError": true}[fn.name] {
		return nil, unsupportedCodeModeNode(n, "Only standard Error values may be constructed with new in Tidecode Code Mode.")
	}
	args := []any{}
	for _, argument := range n.ArgumentList {
		value, evalErr := i.evaluate(argument, env)
		if evalErr != nil {
			return nil, evalErr
		}
		args = append(args, value)
	}
	return fn.invoke(args, n)
}

func (i *codeModeInterpreter) resolveAwaitable(value any, node ast.Node) (any, error) {
	if promise, ok := value.(*codePromise); ok {
		result, err := promise.await()
		if err != nil {
			return nil, i.attach(err, node)
		}
		return result, nil
	}
	return value, nil
}

func (i *codeModeInterpreter) evaluateUnary(n *ast.UnaryExpression, env *environment) (any, error) {
	op := n.Operator.String()
	if op == "++" || op == "--" {
		current, err := i.readLValue(n.Operand, env)
		if err != nil {
			return nil, err
		}
		old := numberValue(current)
		updated := old + 1
		if op == "--" {
			updated = old - 1
		}
		if err := i.writeLValue(n.Operand, updated, env); err != nil {
			return nil, err
		}
		if n.Postfix {
			return old, nil
		}
		return updated, nil
	}
	if op == "typeof" {
		if id, ok := n.Operand.(*ast.Identifier); ok {
			value, err := env.get(id.Name.String(), id)
			if err != nil {
				if runtimeErr, ok := err.(*codeModeRuntimeError); ok && runtimeErr.Kind == "ReferenceError" {
					return "undefined", nil
				}
				return nil, err
			}
			return i.typeofValue(value), nil
		}
	}
	value, err := i.evaluate(n.Operand, env)
	if err != nil {
		return nil, err
	}
	switch op {
	case "!":
		return !truthy(value), nil
	case "+":
		return numberValue(value), nil
	case "-":
		return -numberValue(value), nil
	case "~":
		return float64(^int32(numberValue(value))), nil
	case "typeof":
		return i.typeofValue(value), nil
	case "void":
		return codeUndefined, nil
	default:
		return nil, unsupportedCodeModeNode(n, fmt.Sprintf("Unary operator '%s' is not supported.", op))
	}
}

func (i *codeModeInterpreter) typeofValue(value any) string {
	switch value.(type) {
	case *codeFunction, *nativeFunction, *intrinsicReference:
		return "function"
	case *toolReference:
		if len(value.(*toolReference).path) == 0 {
			return "object"
		}
		return "function"
	case *globalNamespace:
		name := value.(*globalNamespace).name
		if name == "Math" || name == "JSON" || name == "console" {
			return "object"
		}
		return "function"
	case *codePromise, *codeArray, *codeObject:
		return "object"
	case codeUndefinedValue:
		return "undefined"
	case nil:
		return "object"
	case string:
		return "string"
	case bool:
		return "boolean"
	case float64:
		return "number"
	default:
		return "undefined"
	}
}

func (i *codeModeInterpreter) evaluateBinary(n *ast.BinaryExpression, env *environment) (any, error) {
	op := n.Operator.String()
	if op == "&&" || op == "||" || op == "??" {
		left, err := i.evaluate(n.Left, env)
		if err != nil {
			return nil, err
		}
		if op == "&&" {
			if truthy(left) {
				return i.evaluate(n.Right, env)
			}
			return left, nil
		}
		if op == "||" {
			if truthy(left) {
				return left, nil
			}
			return i.evaluate(n.Right, env)
		}
		if left == nil || isUndefined(left) {
			return i.evaluate(n.Right, env)
		}
		return left, nil
	}
	left, err := i.evaluate(n.Left, env)
	if err != nil {
		return nil, err
	}
	right, err := i.evaluate(n.Right, env)
	if err != nil {
		return nil, err
	}
	switch op {
	case "+":
		if _, ok := left.(string); ok {
			return stringValue(left) + stringValue(right), nil
		}
		if _, ok := right.(string); ok {
			return stringValue(left) + stringValue(right), nil
		}
		return numberValue(left) + numberValue(right), nil
	case "-":
		return numberValue(left) - numberValue(right), nil
	case "*":
		return numberValue(left) * numberValue(right), nil
	case "/":
		return numberValue(left) / numberValue(right), nil
	case "%":
		return math.Mod(numberValue(left), numberValue(right)), nil
	case "**":
		return math.Pow(numberValue(left), numberValue(right)), nil
	case "<":
		return compareValues(left, right) < 0, nil
	case "<=":
		return compareValues(left, right) <= 0, nil
	case ">":
		return compareValues(left, right) > 0, nil
	case ">=":
		return compareValues(left, right) >= 0, nil
	case "===":
		return strictEqual(left, right), nil
	case "!==":
		return !strictEqual(left, right), nil
	case "==":
		return looseEqual(left, right), nil
	case "!=":
		return !looseEqual(left, right), nil
	case "|":
		return float64(int32(numberValue(left)) | int32(numberValue(right))), nil
	case "&":
		return float64(int32(numberValue(left)) & int32(numberValue(right))), nil
	case "^":
		return float64(int32(numberValue(left)) ^ int32(numberValue(right))), nil
	case "<<":
		return float64(int32(numberValue(left)) << uint32(numberValue(right)) & 31), nil
	case ">>":
		return float64(int32(numberValue(left)) >> uint32(numberValue(right)) & 31), nil
	case ">>>":
		return float64(uint32(numberValue(left)) >> uint32(numberValue(right)) & 31), nil
	case "in":
		key := stringValue(left)
		switch object := right.(type) {
		case *codeObject:
			_, ok := object.props[key]
			return ok, nil
		case *codeArray:
			if key == "length" {
				return true, nil
			}
			idx, ok := canonicalArrayIndex(key)
			return ok && idx < len(object.items), nil
		case *toolReference:
			for _, name := range i.tools.keys(object) {
				if name == key {
					return true, nil
				}
			}
			return false, nil
		default:
			return nil, i.attach(cmError("TypeError", "Right-hand side of 'in' must be an object.", n), n)
		}
	default:
		return nil, unsupportedCodeModeNode(n, fmt.Sprintf("Binary operator '%s' is not supported.", op))
	}
}

func compareValues(a, b any) int {
	if _, ok := a.(string); ok {
		left, right := stringValue(a), stringValue(b)
		if left < right {
			return -1
		}
		if left > right {
			return 1
		}
		return 0
	}
	left, right := numberValue(a), numberValue(b)
	if left < right {
		return -1
	}
	if left > right {
		return 1
	}
	return 0
}
func looseEqual(a, b any) bool {
	if strictEqual(a, b) {
		return true
	}
	if (a == nil && isUndefined(b)) || (b == nil && isUndefined(a)) {
		return true
	}
	return numberValue(a) == numberValue(b)
}

func (i *codeModeInterpreter) evaluateAssignment(n *ast.AssignExpression, env *environment) (any, error) {
	op := n.Operator.String()
	current, err := i.readLValue(n.Left, env)
	if err != nil {
		return nil, err
	}
	if op == "&&=" && !truthy(current) {
		return current, nil
	}
	if op == "||=" && truthy(current) {
		return current, nil
	}
	if op == "??=" && current != nil && !isUndefined(current) {
		return current, nil
	}
	right, err := i.evaluate(n.Right, env)
	if err != nil {
		return nil, err
	}
	value := right
	if op != "=" && op != "&&=" && op != "||=" && op != "??=" {
		value, err = i.applyCompound(op, current, right, n)
		if err != nil {
			return nil, err
		}
	}
	if err := i.writeLValue(n.Left, value, env); err != nil {
		return nil, err
	}
	return value, nil
}

func (i *codeModeInterpreter) applyCompound(op string, left, right any, node ast.Node) (any, error) {
	switch op {
	case "+=":
		if _, ok := left.(string); ok {
			return stringValue(left) + stringValue(right), nil
		}
		if _, ok := right.(string); ok {
			return stringValue(left) + stringValue(right), nil
		}
		return numberValue(left) + numberValue(right), nil
	case "-=":
		return numberValue(left) - numberValue(right), nil
	case "*=":
		return numberValue(left) * numberValue(right), nil
	case "/=":
		return numberValue(left) / numberValue(right), nil
	case "%=":
		return math.Mod(numberValue(left), numberValue(right)), nil
	case "**=":
		return math.Pow(numberValue(left), numberValue(right)), nil
	case "|=":
		return float64(int32(numberValue(left)) | int32(numberValue(right))), nil
	case "&=":
		return float64(int32(numberValue(left)) & int32(numberValue(right))), nil
	case "^=":
		return float64(int32(numberValue(left)) ^ int32(numberValue(right))), nil
	case "<<=":
		return float64(int32(numberValue(left)) << uint32(numberValue(right)) & 31), nil
	case ">>=":
		return float64(int32(numberValue(left)) >> uint32(numberValue(right)) & 31), nil
	case ">>>=":
		return float64(uint32(numberValue(left)) >> uint32(numberValue(right)) & 31), nil
	default:
		return nil, unsupportedCodeModeNode(node, fmt.Sprintf("Assignment operator '%s' is not supported.", op))
	}
}

