}
func (i *codeModeInterpreter) writeLValue(expression ast.Expression, value any, env *environment) error {
	if id, ok := expression.(*ast.Identifier); ok {
		return env.set(id.Name.String(), value, id)
	}
	lv, err := i.memberLValue(expression, env)
	if err != nil {
		return err
	}
	return lv.set(value)
}
func (i *codeModeInterpreter) memberLValue(expression ast.Expression, env *environment) (*codeLValue, error) {
