	case *ast.BracketExpression:
		receiver, err = i.evaluate(member.Left, env)
		if err == nil {
			raw, evalErr := i.evaluate(member.Member, env)
			err = evalErr
			if err == nil {
				key, err = memberKeyValue(raw, member)
			}
		}
	default:
		return nil, unsupportedCodeModeNode(expression, "Unsupported assignment target.")
	}
	if err != nil {
		return nil, err
	}
	if blockedCodeModeMembers[key] {
		return nil, i.attach(cmError("TypeError", fmt.Sprintf("Property '%s' is not available in Tidecode Code Mode.", key), expression), expression)
	}
	switch target := receiver.(type) {
	case *payloadNamespace:
		return &codeLValue{get: func() any {
			if value, ok := target.values[key]; ok {
				return value
			}
			return codeUndefined
		}, set: func(any) error {
			return i.attach(cmError("TypeError", "Code Mode payloads are read-only.", expression), expression)
		}}, nil
	case *codeObject:
		return &codeLValue{get: func() any {
			if value, ok := target.props[key]; ok {
				return value
			}
			return codeUndefined
		}, set: func(value any) error { target.props[key] = value; return nil }}, nil
	case *codeArray:
		index, ok := canonicalArrayIndex(key)
		if !ok {
			return nil, i.attach(cmError("TypeError", "Array member assignment expects a numeric index.", expression), expression)
		}
