			if index < len(target.items) {
				return target.items[index]
			}
			return codeUndefined
		}, set: func(value any) error {
			for len(target.items) <= index {
				target.items = append(target.items, codeUndefined)
			}
			target.items[index] = value
			return nil
		}}, nil
	default:
		return nil, i.attach(cmError("TypeError", "Member assignment expects an array or data object.", expression), expression)
	}
}

func (i *codeModeInterpreter) evaluateTemplate(n *ast.TemplateLiteral, env *environment) (any, error) {
	if n.Tag != nil {
		return nil, unsupportedCodeModeNode(n, "Tagged template literals are not supported in Tidecode Code Mode.")
	}
	var b strings.Builder
	for index, element := range n.Elements {
		if element.Valid {
			b.WriteString(element.Parsed.String())
		} else {
			b.WriteString(element.Literal)
		}
		if index < len(n.Expressions) {
			value, err := i.evaluate(n.Expressions[index], env)
			if err != nil {
				return nil, err
			}
			b.WriteString(stringValue(value))
		}
	}
	return b.String(), nil
}

