	}
	return i.memberValue(receiver, n.Identifier.Name.String(), n)
}
func (i *codeModeInterpreter) evaluateBracket(n *ast.BracketExpression, env *environment) (any, error) {
	receiver, err := i.evaluate(n.Left, env)
	if err != nil {
		return nil, err
	}
	key, err := i.evaluate(n.Member, env)
	if err != nil {
		return nil, err
	}
	name, err := memberKeyValue(key, n)
	if err != nil {
		return nil, err
	}
	return i.memberValue(receiver, name, n)
}

func (i *codeModeInterpreter) memberValue(receiver any, name string, node ast.Node) (any, error) {
	if blockedCodeModeMembers[name] {
		return nil, i.attach(cmError("TypeError", fmt.Sprintf("Property '%s' is not available in Tidecode Code Mode.", name), node), node)
	}
	switch value := receiver.(type) {
	case *toolReference:
		return i.tools.member(value, name, node)
	case *payloadNamespace:
		if item, ok := value.values[name]; ok {
			return item, nil
		}
		return codeUndefined, nil
	case *codePromise:
		return nil, i.attach(cmError("TypeError", "Promise chaining is not supported. Await the promise first.", node), node)
	case *globalNamespace:
		if value.name == "Math" {
			if constant, ok := mathConstant(name); ok {
				return constant, nil
			}
		}
		return &intrinsicReference{receiver: value, name: name}, nil
	case *codeArray:
		if name == "length" {
			return float64(len(value.items)), nil
		}
		if index, ok := canonicalArrayIndex(name); ok {
			if index < len(value.items) {
				return value.items[index], nil
			}
			return codeUndefined, nil
		}
		if arrayMethodAllowed(name) {
			return &intrinsicReference{receiver: value, name: name}, nil
		}
		return nil, i.attach(cmError("TypeError", fmt.Sprintf("Array method/property '%s' is not available in Tidecode Code Mode.", name), node), node)
	case string:
		runes := []rune(value)
		if name == "length" {
			return float64(len(runes)), nil
		}
		if index, ok := canonicalArrayIndex(name); ok {
			if index < len(runes) {
				return string(runes[index]), nil
			}
			return codeUndefined, nil
		}
		if stringMethodAllowed(name) {
			return &intrinsicReference{receiver: value, name: name}, nil
		}
		return nil, i.attach(cmError("TypeError", fmt.Sprintf("String method/property '%s' is not available in Tidecode Code Mode.", name), node), node)
	case *codeObject:
		if item, ok := value.props[name]; ok {
			return item, nil
		}
		return codeUndefined, nil
	case nil:
		return nil, i.attach(cmError("TypeError", "Cannot read properties of null or undefined.", node), node)
	case codeUndefinedValue:
		return nil, i.attach(cmError("TypeError", "Cannot read properties of null or undefined.", node), node)
	default:
		return nil, i.attach(cmError("TypeError", fmt.Sprintf("Cannot read property '%s' from this value.", name), node), node)
	}
}

func (i *codeModeInterpreter) evaluateCall(n *ast.CallExpression, env *environment) (any, error) {
	callee, err := i.evaluate(n.Callee, env)
	if err != nil {
		return nil, err
	}
	args := []any{}
	for _, argument := range n.ArgumentList {
		if spread, ok := argument.(*ast.SpreadElement); ok {
			value, evalErr := i.evaluate(spread.Expression, env)
			if evalErr != nil {
				return nil, evalErr
			}
			array, ok := value.(*codeArray)
			if !ok {
				return nil, i.attach(cmError("TypeError", "Call spread expects an array.", spread), spread)
			}
			args = append(args, array.items...)
		} else {
			value, evalErr := i.evaluate(argument, env)
			if evalErr != nil {
				return nil, evalErr
			}
			args = append(args, value)
		}
	}
	switch fn := callee.(type) {
	case *toolReference:
		return i.tools.call(fn, args, n)
	case *codeFunction:
		if fn.async {
			return startCodePromise(func() (any, error) { return i.invokeFunction(fn, args, n) }), nil
		}
		return i.invokeFunction(fn, args, n)
	case *nativeFunction:
		return fn.invoke(args, n)
	case *intrinsicReference:
		return i.invokeIntrinsic(fn, args, n)
	default:
		return nil, i.attach(cmError("TypeError", "Attempted to call a value that is not callable in Tidecode Code Mode.", n), n)
	}
}

