			originalEnd := frontmatterEnd(raw)
			if originalEnd >= 0 {
				content = strings.TrimLeft(raw[originalEnd:], "\r\n")
			} else {
				content = afterNormalized
			}
		}
	}

	if name == "" {
		name = filepath.Base(filepath.Dir(location))
	}
	if description == "" {
		for _, line := range strings.Split(content, "\n") {
			trimmed := strings.TrimSpace(strings.TrimSuffix(line, "\r"))
			if trimmed != "" && !strings.HasPrefix(trimmed, "#") {
				description = trimmed
				break
			}
		}
	}
	if description == "" {
		description = "No description provided."
	}
	skillContent := strings.TrimSpace(content)
	if skillContent == "" {
		skillContent = strings.TrimSpace(raw)
	}

	cleanLocation := filepath.Clean(location)
	return Skill{
		Name:          name,
		Description:   description,
		Content:       skillContent,
		Location:      cleanLocation,
		BaseDirectory: filepath.Dir(cleanLocation),
	}
}

func frontmatterEnd(raw string) int {
	if !strings.HasPrefix(raw, "---") {
		return -1
	}
	position := 3
	for position < len(raw) {
		index := strings.Index(raw[position:], "\n---")
		if index < 0 {
			return -1
		}
		end := position + index + 4
		if end == len(raw) || raw[end] == '\n' || raw[end] == '\r' {
			return end
		}
		position = end
	}
	return -1
}

func normalizeWorkspacePath(workspacePath string) string {
	trimmed := strings.TrimSpace(workspacePath)
	if trimmed == "" {
		return ""
	}
	absolute, err := filepath.Abs(trimmed)
	if err != nil {
		return filepath.Clean(trimmed)
	}
	return filepath.Clean(absolute)
}

func skillSearchRoots(workspacePath string) []skillSearchRoot {
	roots := []skillSearchRoot{}
	seen := map[string]bool{}

	addRoot := func(directory, source, sourceLabel string) {
		clean := filepath.Clean(directory)
		key := strings.ToLower(clean)
		if seen[key] {
			return
		}
		seen[key] = true
		roots = append(roots, skillSearchRoot{Directory: clean, Source: source, SourceLabel: sourceLabel})
	}

	normalizedWorkspace := normalizeWorkspacePath(workspacePath)
	if normalizedWorkspace != "" {
		for _, relativeDirectory := range workspaceSkillDirectories {
			addRoot(filepath.Join(normalizedWorkspace, filepath.FromSlash(relativeDirectory)), "workspace", "Workspace")
		}
	}

	home, _ := os.UserHomeDir()
	for _, relativeDirectory := range globalSkillDirectories {
		addRoot(filepath.Join(home, filepath.FromSlash(relativeDirectory)), "global", "Global")
	}

	return roots
}

func collectSkillFiles(root string) ([]string, error) {
	matches := []string{}
	err := filepath.WalkDir(root, func(path string, entry os.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if entry.Type()&os.ModeSymlink != 0 {
			if entry.IsDir() {
				return filepath.SkipDir
			}
			return nil
		}
		if entry.IsDir() {
			return nil
		}
		if entry.Type().IsRegular() && entry.Name() == skillFileName {
			matches = append(matches, filepath.Clean(path))
		}
		return nil
	})
	return matches, err
}

