func readSkillSummary(location string, root skillSearchRoot) (Skill, bool) {
	raw, err := os.ReadFile(location)
	if err != nil {
		return Skill{}, false
	}

	skill := parseSkillDocument(string(raw), location)
	if strings.TrimSpace(skill.Name) == "" {
		return Skill{}, false
	}
	skill.Name = strings.TrimSpace(skill.Name)
	skill.Source = root.Source
	skill.SourceLabel = root.SourceLabel
	return skill, true
}

func discoverAvailableSkills(workspacePath string) SkillDiscovery {
	discovered := []Skill{}

	for _, root := range skillSearchRoots(workspacePath) {
		info, err := os.Stat(root.Directory)
		if os.IsNotExist(err) {
			continue
		}
		if err != nil {
			return SkillDiscovery{Skills: []Skill{}, ErrorMessage: err.Error()}
		}
		if !info.IsDir() {
			continue
		}

		files, err := collectSkillFiles(root.Directory)
		if err != nil {
			return SkillDiscovery{Skills: []Skill{}, ErrorMessage: err.Error()}
		}
		for _, file := range files {
			if skill, ok := readSkillSummary(file, root); ok {
				discovered = append(discovered, skill)
			}
		}
	}

	byName := map[string]Skill{}
	order := []string{}
	for _, skill := range discovered {
		key := strings.ToLower(strings.TrimSpace(skill.Name))
		if key == "" {
			continue
		}
		if _, exists := byName[key]; exists {
			continue
		}
		byName[key] = skill
		order = append(order, key)
	}

	deduped := make([]Skill, 0, len(order))
	for _, key := range order {
		deduped = append(deduped, byName[key])
	}
	sort.Slice(deduped, func(i, j int) bool {
		return deduped[i].Name < deduped[j].Name
	})

	return SkillDiscovery{Skills: deduped}
}

func listAvailableSkills(workspacePath string) SkillDiscovery {
	cacheKey := normalizeWorkspacePath(workspacePath)

	skillCache.Lock()
	cached, ok := skillCache.states[cacheKey]
	if ok && time.Since(cached.At) < 3*time.Second {
		skillCache.Unlock()
		return cached.State
	}
	skillCache.Unlock()

	state := discoverAvailableSkills(workspacePath)

	skillCache.Lock()
	skillCache.states[cacheKey] = cachedSkillDiscovery{At: time.Now(), State: state}
	skillCache.Unlock()
	return state
}

func skillSummaryValue(skill Skill) map[string]any {
	return map[string]any{
		"name":          skill.Name,
		"description":   skill.Description,
		"location":      skill.Location,
		"baseDirectory": skill.BaseDirectory,
		"source":        skill.Source,
		"sourceLabel":   skill.SourceLabel,
	}
}

func skillSummaryValues(skills []Skill) []any {
	values := make([]any, 0, len(skills))
	for _, skill := range skills {
		values = append(values, skillSummaryValue(skill))
	}
	return values
}

func paginateSkills(skills []Skill, page, pageSize int) (currentPage, totalPages int, items []Skill) {
	if pageSize <= 0 {
		pageSize = 10
	}
	if page < 1 {
		page = 1
	}

	totalPages = 1
	if len(skills) > 0 {
		totalPages = (len(skills) + pageSize - 1) / pageSize
	}
	if page > totalPages {
		page = totalPages
	}

	start := (page - 1) * pageSize
	end := start + pageSize
	if end > len(skills) {
		end = len(skills)
	}
	return page, totalPages, skills[start:end]
}

func searchSkills(skills []Skill, query string) []Skill {
	tokens := strings.Fields(strings.ToLower(strings.TrimSpace(query)))
	if len(tokens) == 0 {
		return skills
	}

	matches := []Skill{}
	for _, skill := range skills {
		name := strings.ToLower(skill.Name)
		description := strings.ToLower(skill.Description)
		matched := true
		for _, token := range tokens {
			if !strings.Contains(name, token) && !strings.Contains(description, token) {
				matched = false
				break
			}
		}
		if matched {
			matches = append(matches, skill)
		}
	}
	return matches
}

func (service SkillService) Execute(in SkillInput) (ToolResult, error) {
	state := listAvailableSkills(service.WorkspaceRoot)
	if state.ErrorMessage != "" {
		return failure("Unable to load skills: " + state.ErrorMessage), nil
	}

	switch in.Action {
	case "list":
		page, totalPages, displayed := paginateSkills(state.Skills, in.Page, 10)
		if len(displayed) == 0 {
			result := withBody(success("Listed skills (empty page)"), fmt.Sprintf("No skills found for page %d. Total available skills: %d.", page, len(state.Skills)))
			result.Semantics = map[string]any{"action": "list", "displayed_count": 0, "page": page, "page_size": 10, "skills": []any{}, "total_pages": totalPages, "total_skills": len(state.Skills)}
			return result, nil
		}

		var body strings.Builder
		body.WriteString("### Skills\n\n")
		startIndex := (page - 1) * 10
		for index, skill := range displayed {
			if index > 0 {
				body.WriteString("\n\n")
			}
			body.WriteString(fmt.Sprintf("%d. **%s**\n   %s", startIndex+index+1, skill.Name, skill.Description))
		}
		body.WriteString("\n\n")
		if page < totalPages {
			body.WriteString(fmt.Sprintf("Page %d of %d — To view page %d, run `skill` with `action: \"list\", page: %d`.", page, totalPages, page+1, page+1))
		} else {
			body.WriteString(fmt.Sprintf("Page %d of %d", page, totalPages))
		}

		result := withBody(success(fmt.Sprintf("Listed %d skills (Page %d/%d)", len(displayed), page, totalPages)), body.String())
		result.Semantics = map[string]any{"action": "list", "displayed_count": len(displayed), "page": page, "page_size": 10, "skills": skillSummaryValues(displayed), "total_pages": totalPages, "total_skills": len(state.Skills)}
		return result, nil

	case "search":
		query := strings.TrimSpace(in.Query)
		if query == "" {
			return failure("Search query parameter \"query\" is required for search mode."), nil
		}

		matches := searchSkills(state.Skills, query)
		if len(matches) == 0 {
			result := withBody(success(fmt.Sprintf("Searched skills for %q (0 matches)", query)), fmt.Sprintf("No skills matching %q were found.", query))
			result.Semantics = map[string]any{"action": "search", "displayed_count": 0, "query": query, "skills": []any{}, "total_matches": 0}
			return result, nil
		}

		var body strings.Builder
		body.WriteString(fmt.Sprintf("### Search Results for %q (%d match", query, len(matches)))
		if len(matches) != 1 {
			body.WriteString("es")
		}
		body.WriteString(")\n\n")
		for index, skill := range matches {
			if index > 0 {
				body.WriteString("\n\n")
			}
			body.WriteString(fmt.Sprintf("%d. **%s**\n   %s", index+1, skill.Name, skill.Description))
		}

		result := withBody(success(fmt.Sprintf("Searched skills for %q (%d matches)", query, len(matches))), body.String())
		result.Semantics = map[string]any{"action": "search", "displayed_count": len(matches), "query": query, "skills": skillSummaryValues(matches), "total_matches": len(matches)}
		return result, nil

	case "load":
		name := strings.TrimSpace(in.Name)
		if name == "" {
			return failure("Skill name parameter \"name\" is required for load mode."), nil
		}

		var selected *Skill
		for index := range state.Skills {
			if strings.EqualFold(strings.TrimSpace(state.Skills[index].Name), name) {
				selected = &state.Skills[index]
				break
			}
		}
		if selected == nil {
			result := withBody(failure(fmt.Sprintf("Skill %q is unavailable.", name)), "Use action: \"search\" or action: \"list\" to check available skills.")
			return result, nil
		}

		raw, err := os.ReadFile(selected.Location)
		if err != nil {
			return failure("Unable to load skill: " + err.Error()), nil
		}
		loaded := parseSkillDocument(string(raw), selected.Location)
		loaded.Source = selected.Source
		loaded.SourceLabel = selected.SourceLabel
		body := strings.Join([]string{
			"Skill file: " + loaded.Location,
			"Skill directory: " + loaded.BaseDirectory,
			"Resolve relative resource and script paths from the skill directory above.",
			"",
			strings.TrimSpace(loaded.Content),
		}, "\n")
		result := withBody(success("Loaded skill "+loaded.Name), body)
		result.Semantics = map[string]any{"skill_directory": loaded.BaseDirectory, "skill_file": loaded.Location, "skill_name": loaded.Name}
		return withSubject(result, "file", loaded.Location), nil

	default:
		return failure(fmt.Sprintf("Invalid action %q. Supported actions: list, search, load.", in.Action)), nil
	}
}

