package tidecode

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"sync"
)

type ApplyPatchService struct{}

type applyPatchTarget struct {
	AbsolutePath string
	RelativePath string
}

type resolvedApplyPatchHunk struct {
	Hunk       applyPatchHunk
	Source     applyPatchTarget
	MoveTarget *applyPatchTarget
}

type applyPatchChange struct {
	AlreadyApplied        bool
	Autofixed             bool
	AbsolutePath          string
	NextAbsolutePath      string
	NewContent            string
	OldContent            string
	OldContentPresent     bool
	RelativePath          string
	SourceRelativePath    string
	Type                  string
	UpdateChunkStartLines []int
}

type stagedPatchFile struct {
	Target  applyPatchTarget
	Content *string
}

type patchFileSnapshot struct {
	AbsolutePath string
	Content      string
	Existed      bool
}

func resolveApplyPatchTarget(root, candidate string) (applyPatchTarget, error) {
	absolutePath, err := resolveMutationPath(root, candidate)
	if err != nil {
		return applyPatchTarget{}, err
	}
	workspace, err := resolveWorkspace(root)
	if err != nil {
		return applyPatchTarget{}, err
	}
	return applyPatchTarget{AbsolutePath: absolutePath, RelativePath: slashRelative(workspace, absolutePath)}, nil
}

func resolveApplyPatchHunks(root string, parsed parsedApplyPatch) ([]resolvedApplyPatchHunk, error) {
	resolved := make([]resolvedApplyPatchHunk, 0, len(parsed.Hunks))
	for _, hunk := range parsed.Hunks {
		source, err := resolveApplyPatchTarget(root, hunk.Path)
		if err != nil {
			return nil, fmt.Errorf("Invalid patch path %q: %w", hunk.Path, err)
		}
		item := resolvedApplyPatchHunk{Hunk: hunk, Source: source}
		if hunk.MovePath != "" {
			moveTarget, err := resolveApplyPatchTarget(root, hunk.MovePath)
			if err != nil {
				return nil, fmt.Errorf("Invalid patch move path %q: %w", hunk.MovePath, err)
			}
			item.MoveTarget = &moveTarget
		}
		resolved = append(resolved, item)
	}
	return resolved, nil
}

func lockApplyPatchTargets(hunks []resolvedApplyPatchHunk) func() {
	byKey := map[string]*sync.Mutex{}
	for _, hunk := range hunks {
		byKey[mutationLockKey(hunk.Source.AbsolutePath)] = mutationLock(hunk.Source.AbsolutePath)
		if hunk.MoveTarget != nil {
			byKey[mutationLockKey(hunk.MoveTarget.AbsolutePath)] = mutationLock(hunk.MoveTarget.AbsolutePath)
		}
	}
	keys := make([]string, 0, len(byKey))
	for key := range byKey {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	for _, key := range keys {
		byKey[key].Lock()
	}
	return func() {
		for index := len(keys) - 1; index >= 0; index-- {
			byKey[keys[index]].Unlock()
		}
	}
}

func stagePatchFile(staged map[string]*stagedPatchFile, order *[]string, target applyPatchTarget, content *string) {
	key := mutationLockKey(target.AbsolutePath)
	if _, exists := staged[key]; !exists {
		*order = append(*order, key)
	}
	staged[key] = &stagedPatchFile{Target: target, Content: content}
}

func readRequiredPatchContent(staged map[string]*stagedPatchFile, target applyPatchTarget, operation string) (string, error) {
	if stagedFile, exists := staged[mutationLockKey(target.AbsolutePath)]; exists {
		if stagedFile.Content == nil {
			return "", fmt.Errorf("Failed to read file for %s %s: file is deleted by this patch", operation, target.RelativePath)
		}
		return *stagedFile.Content, nil
	}
	content, err := os.ReadFile(target.AbsolutePath)
	if err != nil {
		return "", fmt.Errorf("Failed to read file for %s %s: %w", operation, target.RelativePath, err)
	}
	return string(content), nil
}

func readPatchFileSnapshot(absolutePath string) (patchFileSnapshot, error) {
	content, err := os.ReadFile(absolutePath)
	if err == nil {
		return patchFileSnapshot{AbsolutePath: absolutePath, Content: string(content), Existed: true}, nil
	}
	if os.IsNotExist(err) {
		return patchFileSnapshot{AbsolutePath: absolutePath, Existed: false}, nil
	}
	return patchFileSnapshot{}, err
}

func restorePatchFileSnapshot(snapshot patchFileSnapshot) error {
	if !snapshot.Existed {
		return removeFileWithRetry(snapshot.AbsolutePath, true)
	}
	return writeTextFileAtomically(snapshot.AbsolutePath, snapshot.Content)
}

func commitStagedPatchFiles(staged map[string]*stagedPatchFile, order []string) error {
	snapshots := make(map[string]patchFileSnapshot, len(order))
	for _, key := range order {
		snapshot, err := readPatchFileSnapshot(staged[key].Target.AbsolutePath)
		if err != nil {
			return err
		}
		snapshots[key] = snapshot
	}

	committed := make([]patchFileSnapshot, 0, len(order))
	for _, key := range order {
		stagedFile := staged[key]
		var err error
		if stagedFile.Content == nil {
			err = removeFileWithRetry(stagedFile.Target.AbsolutePath, false)
		} else {
			err = writeTextFileAtomically(stagedFile.Target.AbsolutePath, *stagedFile.Content)
		}
		if err == nil {
			committed = append(committed, snapshots[key])
			continue
		}

		var rollbackErr error
		for index := len(committed) - 1; index >= 0; index-- {
			if restoreErr := restorePatchFileSnapshot(committed[index]); restoreErr != nil && rollbackErr == nil {
				rollbackErr = restoreErr
			}
		}
		if rollbackErr != nil {
			return fmt.Errorf("%v; rollback also failed: %v", err, rollbackErr)
		}
		return err
	}
	return nil
}

func applyPatchInWorkspace(root, patchText string) ([]applyPatchChange, parsedApplyPatch, error) {
	parsed, err := parseApplyPatch(patchText)
	if err != nil {
		return nil, parsedApplyPatch{}, err
	}
	resolved, err := resolveApplyPatchHunks(root, parsed)
	if err != nil {
		return nil, parsed, err
	}
	unlock := lockApplyPatchTargets(resolved)
	defer unlock()

	changes := make([]applyPatchChange, 0, len(resolved))
	staged := map[string]*stagedPatchFile{}
	order := []string{}

	for _, resolvedHunk := range resolved {
		hunk := resolvedHunk.Hunk
		source := resolvedHunk.Source
		switch hunk.Type {
		case "add":
			nextContent := hunk.Contents
			if nextContent != "" && !strings.HasSuffix(nextContent, "\n") {
				nextContent += "\n"
			}
			stagePatchFile(staged, &order, source, &nextContent)
			changes = append(changes, applyPatchChange{AbsolutePath: source.AbsolutePath, NewContent: nextContent, RelativePath: source.RelativePath, Type: "add"})
		case "delete":
			existingContent, err := readRequiredPatchContent(staged, source, "deletion")
			if err != nil {
				return nil, parsed, err
			}
			stagePatchFile(staged, &order, source, nil)
			changes = append(changes, applyPatchChange{AbsolutePath: source.AbsolutePath, OldContent: existingContent, OldContentPresent: true, RelativePath: source.RelativePath, Type: "delete"})
		case "update":
			existingContent, err := readRequiredPatchContent(staged, source, "update")
			if err != nil {
				return nil, parsed, err
			}
			nextContent, startLines, usedAlreadyAppliedRecovery, usedEscapingAutofix, err := applyUpdatePatchChunks(source.RelativePath, existingContent, hunk.Chunks)
			if err != nil {
				return nil, parsed, err
			}
