			if resolvedHunk.MoveTarget != nil {
				writeTarget = *resolvedHunk.MoveTarget
			}
			if resolvedHunk.MoveTarget == nil && nextContent == normalizeText(existingContent) {
				if !usedAlreadyAppliedRecovery {
					return nil, parsed, fmt.Errorf("Patch did not change %s", source.RelativePath)
				}
				changes = append(changes, applyPatchChange{
					AlreadyApplied:        true,
					Autofixed:             usedEscapingAutofix,
					AbsolutePath:          source.AbsolutePath,
					NewContent:            existingContent,
					OldContent:            existingContent,
					OldContentPresent:     true,
					RelativePath:          source.RelativePath,
					SourceRelativePath:    source.RelativePath,
					Type:                  "update",
					UpdateChunkStartLines: startLines,
				})
				continue
			}
			stagePatchFile(staged, &order, writeTarget, &nextContent)
			nextAbsolutePath := ""
			if resolvedHunk.MoveTarget != nil {
				nextAbsolutePath = writeTarget.AbsolutePath
				if mutationLockKey(writeTarget.AbsolutePath) != mutationLockKey(source.AbsolutePath) {
					stagePatchFile(staged, &order, source, nil)
				}
			}
			changes = append(changes, applyPatchChange{
				Autofixed:             usedEscapingAutofix,
				AbsolutePath:          source.AbsolutePath,
				NextAbsolutePath:      nextAbsolutePath,
				NewContent:            nextContent,
				OldContent:            existingContent,
				OldContentPresent:     true,
				RelativePath:          writeTarget.RelativePath,
				SourceRelativePath:    source.RelativePath,
				Type:                  "update",
				UpdateChunkStartLines: startLines,
			})
		default:
			return nil, parsed, fmt.Errorf("Unsupported patch hunk type: %s", hunk.Type)
		}
	}

	if err := commitStagedPatchFiles(staged, order); err != nil {
		return nil, parsed, err
	}
	return changes, parsed, nil
}

func appendUniquePath(paths []string, seen map[string]bool, path string) []string {
	key := strings.ToLower(filepath.ToSlash(path))
	if seen[key] {
		return paths
	}
	seen[key] = true
	return append(paths, filepath.ToSlash(path))
}

func applyPatchToolResult(changes []applyPatchChange) ToolResult {
	changedPaths := []string{}
	alreadyAppliedPaths := []string{}
	autofixedPaths := []string{}
	seen := map[string]bool{}
	alreadySeen := map[string]bool{}
	autofixedSeen := map[string]bool{}
	body := []string{}
	added, updated, deleted := 0, 0, 0

	for _, change := range changes {
		if change.Autofixed {
			autofixedPaths = appendUniquePath(autofixedPaths, autofixedSeen, change.RelativePath)
		}
		switch change.Type {
		case "add":
			added++
			changedPaths = appendUniquePath(changedPaths, seen, change.RelativePath)
			body = append(body, "A "+change.RelativePath)
		case "delete":
			deleted++
			changedPaths = appendUniquePath(changedPaths, seen, change.RelativePath)
			body = append(body, "D "+change.RelativePath)
		case "update":
			if change.AlreadyApplied {
				alreadyAppliedPaths = appendUniquePath(alreadyAppliedPaths, alreadySeen, change.RelativePath)
				label := "= " + change.RelativePath + " (already applied)"
				if change.Autofixed {
					label += " (autofixed escaping)"
				}
				body = append(body, label)
				continue
			}
			if change.NextAbsolutePath != "" && mutationLockKey(change.NextAbsolutePath) != mutationLockKey(change.AbsolutePath) {
				source := change.SourceRelativePath
				added++
				deleted++
				changedPaths = appendUniquePath(changedPaths, seen, source)
				changedPaths = appendUniquePath(changedPaths, seen, change.RelativePath)
				body = append(body, "D "+source, "A "+change.RelativePath)
			} else {
				updated++
				changedPaths = appendUniquePath(changedPaths, seen, change.RelativePath)
				label := "M " + change.RelativePath
				if change.Autofixed {
					label += " (autofixed escaping)"
				}
				body = append(body, label)
			}
		}
	}

	summary := fmt.Sprintf("Applied patch to %d file", len(changedPaths))
	if len(changedPaths) != 1 {
		summary += "s"
	}
	if len(changedPaths) == 0 && len(alreadyAppliedPaths) > 0 {
		summary = fmt.Sprintf("Patch already applied to %d file", len(alreadyAppliedPaths))
		if len(alreadyAppliedPaths) != 1 {
			summary += "s"
		}
	}
	r := withBody(success(summary), strings.Join(body, "\n"))
	if len(changedPaths) == 1 && len(alreadyAppliedPaths) == 0 {
		r = withSubject(r, "file", changedPaths[0])
	} else if len(changedPaths) == 0 && len(alreadyAppliedPaths) == 1 {
		r = withSubject(r, "file", alreadyAppliedPaths[0])
	} else {
		r = withSubject(r, "workspace", ".")
	}
	r.Semantics = map[string]any{
		"operation":             "edit",
		"changed_paths":         changedPaths,
		"already_applied_paths": alreadyAppliedPaths,
		"autofixed_paths":       autofixedPaths,
		"added_path_count":      added,
		"updated_path_count":    updated,
		"deleted_path_count":    deleted,
	}
	return r
}

func (ApplyPatchService) Apply(root, patchText string) (ToolResult, error) {
	changes, _, err := applyPatchInWorkspace(root, patchText)
	if err != nil {
		return failure(err.Error()), nil
	}
	return applyPatchToolResult(changes), nil
}

