func stripANSI(v string) string {
	var b strings.Builder
	esc := false
	csi := false
	stringControl := false
	stringEscape := false
	for _, r := range v {
		if stringControl {
			if stringEscape {
				if r == '\\' {
					stringControl = false
				}
				stringEscape = false
				continue
			}
			if r == 0x07 {
				stringControl = false
				continue
			}
			if r == 0x1b {
				stringEscape = true
			}
			continue
		}
		if esc {
			esc = false
			if r == '[' {
				csi = true
				continue
			}
			if r == ']' || r == 'P' || r == '^' || r == '_' {
				stringControl = true
				continue
