package tidecode

import (
	"crypto/rand"
	"fmt"
	"math/big"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"time"
	"unicode/utf8"
)

const toolOutputMaxBytes = 40_000
const toolOutputMaxLines = 2_000
const toolOutputMaxLineLength = 2_000
const toolOutputPagedReadMaxBytes = 32 * 1024
const toolOutputPreviewReserveBytes = 2_048
const toolOutputRetention = 7 * 24 * time.Hour

var outputIDPattern = regexp.MustCompile(`^\d{5}$`)
var legacyOutputIDPattern = regexp.MustCompile(`(?i)^[a-z0-9_-]{1,160}$`)

func toolOutputDirectory() (string, error) {
	home, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(home, ".tidecode", "tool-output"), nil
}

func persistToolOutput(content string) (string, error) {
	directory, err := toolOutputDirectory()
	if err != nil {
		return "", err
	}
	if err := os.MkdirAll(directory, 0o755); err != nil {
		return "", err
	}
	for attempt := 0; attempt < 100; attempt++ {
		n, err := rand.Int(rand.Reader, big.NewInt(100000))
		if err != nil {
			return "", err
		}
		id := fmt.Sprintf("%05d", n.Int64())
		path := filepath.Join(directory, id+".txt")
		file, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
		if os.IsExist(err) {
			continue
		}
		if err != nil {
			return "", err
		}
		_, writeErr := file.WriteString(content)
		closeErr := file.Close()
		if writeErr != nil {
			_ = os.Remove(path)
			return "", writeErr
		}
		if closeErr != nil {
			_ = os.Remove(path)
			return "", closeErr
		}
		go cleanupStaleToolOutputs(directory)
		return id, nil
	}
	return "", fmt.Errorf("unable to allocate a tool output id")
}

func cleanupStaleToolOutputs(directory string) {
	entries, err := os.ReadDir(directory)
	if err != nil {
		return
	}
	cutoff := time.Now().Add(-toolOutputRetention)
	for _, entry := range entries {
		if entry.IsDir() || !strings.HasSuffix(strings.ToLower(entry.Name()), ".txt") {
			continue
		}
		id := strings.TrimSuffix(entry.Name(), filepath.Ext(entry.Name()))
		if !outputIDPattern.MatchString(id) && !legacyOutputIDPattern.MatchString(id) {
			continue
		}
		path := filepath.Join(directory, entry.Name())
		info, err := entry.Info()
		if err == nil && info.ModTime().Before(cutoff) {
			_ = os.Remove(path)
		}
	}
}

func validateOutputID(raw string) (string, error) {
	id := strings.TrimSpace(raw)
	if !outputIDPattern.MatchString(id) && !legacyOutputIDPattern.MatchString(id) {
		return "", fmt.Errorf("invalid tool output id")
	}
	return id, nil
}

type ReadToolOutputService struct{}

func (ReadToolOutputService) Read(outputID string, offset, limit int) (ToolResult, error) {
	id, err := validateOutputID(outputID)
	if err != nil {
		return failure("Invalid arguments for read_tool_output: invalid output_id"), nil
	}
	if offset < 1 {
		offset = 1
	}
	if limit < 1 {
		limit = 200
	}
	if limit > 500 {
		limit = 500
	}
	directory, err := toolOutputDirectory()
	if err != nil {
		return ToolResult{}, err
	}
	data, err := os.ReadFile(filepath.Join(directory, id+".txt"))
	if err != nil {
		return ToolResult{}, err
	}
	lines := strings.Split(normalizeText(string(data)), "\n")
	if len(lines) == 0 && len(data) == 0 {
		lines = []string{""}
	}
	visible := make([]string, 0, limit)
	used := 0
	for index := offset - 1; index < len(lines) && len(visible) < limit; index++ {
		line := lines[index]
		lineBytes := len([]byte(line))
		if len(visible) > 0 {
			lineBytes++
		}
		if len(visible) > 0 && used+lineBytes > toolOutputPagedReadMaxBytes {
			break
		}
		visible = append(visible, line)
		used += lineBytes
	}
	endLine := offset - 1
	if len(visible) > 0 {
		endLine = offset + len(visible) - 1
	}
	var next any = nil
	if endLine < len(lines) {
		next = endLine + 1
	}
	result := withBody(success("Read persisted tool output "+id), strings.Join(visible, "\n"))
	result.Semantics = map[string]any{
		"output_id":           id,
		"start_line":          offset,
		"end_line":            endLine,
		"returned_line_count": len(visible),
		"line_count":          len(lines),
		"next_offset":         next,
	}
	return result, nil
}

func truncateToolOutputLine(line string) string {
	if utf8.RuneCountInString(line) <= toolOutputMaxLineLength {
		return line
	}
	marker := "... (middle of line truncated) ..."
	budget := toolOutputMaxLineLength - utf8.RuneCountInString(marker)
	headLen := budget / 2
	tailLen := budget - headLen
	runes := []rune(line)
	return string(runes[:headLen]) + marker + string(runes[len(runes)-tailLen:])
}

type visibleOutputLine struct {
	number int
	text   string
}

func collectOutputHead(lines []string, maxLines, maxBytes int) []visibleOutputLine {
	out := []visibleOutputLine{}
	used := 0
	for index, line := range lines {
		if len(out) >= maxLines {
			break
		}
		text := truncateToolOutputLine(line)
		size := len([]byte(text))
		if len(out) > 0 {
			size++
		}
		if used+size > maxBytes {
			break
		}
		out = append(out, visibleOutputLine{number: index + 1, text: text})
		used += size
	}
	return out
}

func collectOutputTail(lines []string, firstAllowed, maxLines, maxBytes int) []visibleOutputLine {
	reversed := []visibleOutputLine{}
	used := 0
	for index := len(lines) - 1; index >= firstAllowed && len(reversed) < maxLines; index-- {
		text := truncateToolOutputLine(lines[index])
		size := len([]byte(text))
		if len(reversed) > 0 {
			size++
		}
		if used+size > maxBytes {
			break
		}
		reversed = append(reversed, visibleOutputLine{number: index + 1, text: text})
		used += size
	}
	out := make([]visibleOutputLine, len(reversed))
	for i := range reversed {
		out[len(reversed)-1-i] = reversed[i]
	}
	return out
}

func projectToolOutput(value, outputID string) (string, bool) {
	lines := strings.Split(normalizeText(value), "\n")
	longLine := false
	for _, line := range lines {
		if utf8.RuneCountInString(line) > toolOutputMaxLineLength {
			longLine = true
			break
		}
	}
	if len([]byte(value)) <= toolOutputMaxBytes && len(lines) <= toolOutputMaxLines && !longLine {
		return value, false
	}
	previewBudget := toolOutputMaxBytes - toolOutputPreviewReserveBytes
	visibleBudget := toolOutputMaxLines - 10
	headLimit := (visibleBudget + 1) / 2
	tailLimit := visibleBudget - headLimit
	head := collectOutputHead(lines, headLimit, previewBudget/2)
	firstAllowed := 0
	if len(head) > 0 {
		firstAllowed = head[len(head)-1].number
	}
	tail := collectOutputTail(lines, firstAllowed, tailLimit, previewBudget-previewBudget/2)
	omittedStart := firstAllowed + 1
	omittedEnd := len(lines)
	if len(tail) > 0 {
		omittedEnd = tail[0].number - 1
	}
	omitted := ""
	if omittedEnd >= omittedStart {
		omitted = fmt.Sprintf(" Omitted lines %d-%d.", omittedStart, omittedEnd)
	}
	recovery := "Re-run the original tool with narrower arguments only if omitted content is needed."
	if outputID != "" {
		recovery = fmt.Sprintf("output_id: %q. Use read_tool_output with this output_id and a narrow offset/limit only if omitted content is needed.", outputID)
	}
	sections := []string{}
	if len(head) > 0 {
		parts := make([]string, len(head))
		for i, x := range head {
			parts[i] = x.text
		}
		sections = append(sections, strings.Join(parts, "\n"))
	}
	sections = append(sections, fmt.Sprintf("[Output truncated.%s %s]", omitted, recovery))
	if len(tail) > 0 {
		parts := make([]string, len(tail))
		for i, x := range tail {
			parts[i] = x.text
		}
		sections = append(sections, strings.Join(parts, "\n"))
	}
	return strings.Join(sections, "\n"), true
}

func prepareToolResultForModel(toolName string, result ToolResult) ToolResult {
	if result.Body == "" {
		return result
	}
	if (toolName == "read" || toolName == "read_tool_output") && len([]byte(result.Body)) <= toolOutputPagedReadMaxBytes {
		return result
	}
	_, truncated := projectToolOutput(result.Body, "")
	if !truncated {
		return result
	}
	outputID := ""
	if result.Semantics != nil {
		outputID, _ = result.Semantics["output_id"].(string)
	}
	if outputID == "" {
		if id, err := persistToolOutput(result.Body); err == nil {
			outputID = id
		}
	}
	projected, _ := projectToolOutput(result.Body, outputID)
	result.Body = projected
	if result.Semantics == nil {
		result.Semantics = map[string]any{}
	}
	if outputID != "" {
		result.Semantics["output_id"] = outputID
	}
	result.Truncated = true
	return result
}

