	}
	return CodeModeResult{
		Status:      status,
		Summary:     formatted,
		ToolCalls:   toolCalls,
		ExecutionID: id,
		Engine:      "v2",
		Steps:       steps,
		Diagnostic:  &diagnostic,
		Error:       formatted,
	}
}

