func formatCodeModeOutput(value any, calls []ToolCallReceipt) string {
	if text, ok := value.(string); ok {
		return text
	}

	formatter := codeModeOutputFormatter{
		calls:         calls,
		sectionByCall: map[int]int{},
	}
	formatted := formatter.detachToolBodies(value)
	if len(formatter.sections) == 0 {
		return prettyJSON(value)
	}

	var output strings.Builder
	output.WriteString(prettyJSON(formatted))
	for index, section := range formatter.sections {
		output.WriteString("\n\n---\n")
		fmt.Fprintf(&output, "Tool body %d (%s):\n", index+1, section.name)
		output.WriteString(section.body)
	}
	return output.String()
}

func (formatter *codeModeOutputFormatter) detachToolBodies(value any) any {
	switch item := value.(type) {
	case []any:
		out := make([]any, len(item))
		for index, child := range item {
			out[index] = formatter.detachToolBodies(child)
		}
		return out
	case map[string]any:
		return formatter.detachToolResultBody(item)
	default:
		return value
	}
}

func (formatter *codeModeOutputFormatter) detachToolResultBody(value map[string]any) map[string]any {
	callIndex := formatter.matchingCall(value)
	out := make(map[string]any, len(value))
	for key, child := range value {
		if key == "body" && callIndex >= 0 {
			section := formatter.sectionForCall(callIndex)
			out[key] = fmt.Sprintf("[tool body %d rendered below]", section+1)
			continue
		}
		out[key] = formatter.detachToolBodies(child)
	}
	return out
}

func (formatter *codeModeOutputFormatter) matchingCall(value map[string]any) int {
	body, bodyOK := value["body"].(string)
	status, statusOK := value["status"].(string)
	summary, summaryOK := value["summary"].(string)
	if !bodyOK || body == "" || !statusOK || !summaryOK {
		return -1
	}
	for index, call := range formatter.calls {
		if call.Body == body && call.Status == status && call.Summary == summary {
			return index
		}
	}
	return -1
}

func (formatter *codeModeOutputFormatter) sectionForCall(callIndex int) int {
	if section, ok := formatter.sectionByCall[callIndex]; ok {
		return section
	}
	section := len(formatter.sections)
	formatter.sectionByCall[callIndex] = section
	formatter.sections = append(formatter.sections, codeModeBodySection{
		name: formatter.calls[callIndex].Name,
		body: formatter.calls[callIndex].Body,
	})
	return section
}

