func newEnvironment(parent *environment, functionBoundary ...bool) *environment {
	boundary := false
	if len(functionBoundary) > 0 {
		boundary = functionBoundary[0]
	}
	return &environment{parent: parent, functionBoundary: boundary, bindings: map[string]*binding{}}
}

func (e *environment) declare(name string, value any, mutable bool) error {
	e.mu.Lock()
	defer e.mu.Unlock()
	if _, exists := e.bindings[name]; exists {
		return cmError("ReferenceError", fmt.Sprintf("Identifier '%s' has already been declared.", name), nil)
	}
	e.bindings[name] = &binding{value: value, mutable: mutable, initialized: true}
	return nil
}

func (e *environment) nearestFunctionScope() *environment {
	if e.functionBoundary || e.parent == nil {
		return e
	}
	return e.parent.nearestFunctionScope()
}

func (e *environment) declareVar(name string, value any) {
	scope := e.nearestFunctionScope()
	scope.mu.Lock()
	defer scope.mu.Unlock()
	if current, ok := scope.bindings[name]; ok {
		if current.mutable {
			current.value = value
		}
		return
	}
	scope.bindings[name] = &binding{value: value, mutable: true, initialized: true}
}

func (e *environment) get(name string, node ast.Node) (any, error) {
	e.mu.RLock()
	if current, ok := e.bindings[name]; ok {
		defer e.mu.RUnlock()
		if !current.initialized {
			return nil, cmError("ReferenceError", fmt.Sprintf("Cannot access '%s' before initialization.", name), node)
		}
		return current.value, nil
	}
	e.mu.RUnlock()
	if e.parent != nil {
		return e.parent.get(name, node)
	}
	return nil, cmError("ReferenceError", name+" is not defined.", node)
}

func (e *environment) set(name string, value any, node ast.Node) error {
	e.mu.Lock()
	if current, ok := e.bindings[name]; ok {
		defer e.mu.Unlock()
		if !current.initialized {
			return cmError("ReferenceError", fmt.Sprintf("Cannot access '%s' before initialization.", name), node)
		}
		if !current.mutable {
			return cmError("TypeError", fmt.Sprintf("Assignment to constant variable '%s'.", name), node)
		}
		current.value = value
		return nil
	}
	e.mu.Unlock()
	if e.parent != nil {
		return e.parent.set(name, value, node)
	}
	return cmError("ReferenceError", name+" is not defined.", node)
}

