func (r *codeModeToolRuntime) root() *toolReference { return &toolReference{path: []string{}} }

func (r *codeModeToolRuntime) keys(reference *toolReference) []string {
	set := r.children[strings.Join(reference.path, ".")]
	out := make([]string, 0, len(set))
	for name := range set {
		out = append(out, name)
	}
	sort.Strings(out)
	return out
}

func (r *codeModeToolRuntime) member(reference *toolReference, name string, node ast.Node) (*toolReference, error) {
	if blockedCodeModeMembers[name] {
		return nil, cmError("TypeError", fmt.Sprintf("Property '%s' is not available in Code Mode.", name), node)
	}
	next := append(append([]string(nil), reference.path...), name)
	key := strings.Join(next, ".")
	if r.projected[key] != nil || r.children[key] != nil || key == "$codemode.search" {
		return &toolReference{path: next}, nil
	}
	available := r.keys(reference)
	if len(available) > 8 {
		available = available[:8]
	}
	suggestions := []string{"Use tools.$codemode.search(...) for discovery."}
	if len(available) > 0 {
		suggestions = []string{fmt.Sprintf("Available here: %s. Use tools.$codemode.search(...) for discovery.", strings.Join(available, ", "))}
	}
	return nil, cmError("UnknownTool", "Unknown Code Mode capability tools."+key+".", node, suggestions...)
}

func (r *codeModeToolRuntime) call(reference *toolReference, args []any, node ast.Node) (*codePromise, error) {
	key := strings.Join(reference.path, ".")
	if key == "$codemode.search" {
		if len(args) > 1 {
			return nil, cmError("InvalidToolArguments", "tools.$codemode.search expects at most one input value.", node)
		}
		var input any = map[string]any{}
		if len(args) == 1 {
			input = args[0]
		}
		result, err := r.search(input, node)
		if err != nil {
			return nil, err
		}
		return resolvedCodePromise(internalizeData(result)), nil
	}
	tool := r.projected[key]
	if tool == nil {
		return nil, cmError("UnknownTool", "tools."+key+" is not callable.", node)
	}
	if len(args) != 1 {
		return nil, cmError("InvalidToolArguments", tool.expression+" expects exactly one input value.", node)
	}
	input, err := hostData(args[0], "Arguments for "+tool.expression)
	if err != nil {
		if runtimeErr, ok := err.(*codeModeRuntimeError); ok {
			runtimeErr.Node = node
		}
		return nil, err
	}
	p := startCodePromise(func() (any, error) { return r.execute(tool, input) })
	r.track(p)
	return p, nil
}

func (r *codeModeToolRuntime) track(p *codePromise) {
	r.mu.Lock()
	r.pending[p] = true
	r.mu.Unlock()
	go func() { <-p.done; r.mu.Lock(); delete(r.pending, p); r.mu.Unlock() }()
}

func (r *codeModeToolRuntime) drain() {
	for {
		r.mu.Lock()
		pending := make([]*codePromise, 0, len(r.pending))
		for p := range r.pending {
			pending = append(pending, p)
		}
		r.mu.Unlock()
		if len(pending) == 0 {
			return
		}
		for _, p := range pending {
			<-p.done
		}
	}
}

func (r *codeModeToolRuntime) getReceipts() []ToolCallReceipt {
	r.mu.Lock()
	defer r.mu.Unlock()
	return append([]ToolCallReceipt(nil), r.receipts...)
}

func (r *codeModeToolRuntime) search(input any, node ast.Node) (map[string]any, error) {
	data, err := hostData(input, "Code Mode search input")
	if err != nil {
		return nil, err
	}
	record, ok := data.(map[string]any)
	if !ok {
		return nil, cmError("InvalidToolArguments", "tools.$codemode.search expects an object.", node)
	}
	query := ""
	if value, ok := record["query"].(string); ok {
		query = strings.ToLower(strings.TrimSpace(value))
	}
	namespace := ""
	if value, ok := record["namespace"].(string); ok {
		namespace = strings.ToLower(strings.TrimSpace(value))
	}
	limit := 10
	if value, ok := record["limit"]; ok {
		limit = int(numberValue(value))
		if limit < 1 {
			limit = 1
		}
		if limit > 50 {
			limit = 50
		}
	}
	offset := 0
	if value, ok := record["offset"]; ok {
		offset = int(numberValue(value))
		if offset < 0 {
			offset = 0
		}
	}
	terms := strings.Fields(query)
	type scored struct {
		tool  *projectedTool
		score int
	}
	matches := []scored{}
	for _, tool := range r.projected {
		toolNS := strings.ToLower(tool.definition.Namespace)
		if namespace != "" && toolNS != namespace {
			continue
		}
		name := strings.ToLower(tool.definition.Name)
		description := strings.ToLower(tool.definition.Description)
		score := 0
		for _, term := range terms {
			if name == term {
				score += 100
			} else if strings.Contains(name, term) {
				score += 50
			}
			if toolNS == term {
				score += 30
			} else if strings.Contains(toolNS, term) {
				score += 15
			}
			if strings.Contains(description, term) {
				score += 10
			}
		}
		if namespace != "" {
			score += 1000
		}
		if query == "" || score > 0 {
			matches = append(matches, scored{tool: tool, score: score})
		}
	}
	sort.Slice(matches, func(i, j int) bool {
		if matches[i].score == matches[j].score {
			return matches[i].tool.expression < matches[j].tool.expression
		}
		return matches[i].score > matches[j].score
	})
	if offset > len(matches) {
		offset = len(matches)
	}
	end := offset + limit
	if end > len(matches) {
		end = len(matches)
	}
	items := make([]any, 0, end-offset)
	for _, match := range matches[offset:end] {
		items = append(items, map[string]any{
			"path":        match.tool.expression,
			"description": match.tool.definition.Description,
			"namespace":   match.tool.definition.Namespace,
			"signature":   match.tool.definition.Signature,
		})
	}
	remaining := len(matches) - end
	var next any = nil
	if remaining > 0 {
		next = map[string]any{"offset": float64(end)}
	}
	return map[string]any{"items": items, "remaining": float64(remaining), "next": next}, nil
}

func (r *codeModeToolRuntime) mutationKeys(tool *projectedTool, input any) []string {
	if tool.definition.Name == "apply_patch" {
		return []string{"__workspace_patch__"}
	}
	if !mutatingCodeModeTools[tool.definition.Name] {
		return nil
	}
	record, ok := input.(map[string]any)
	if !ok {
		return []string{"__workspace_mutation__"}
	}
	raw, ok := record["path"].(string)
	if !ok || strings.TrimSpace(raw) == "" {
		return []string{"__workspace_mutation__"}
	}
	resolved := raw
	if !filepath.IsAbs(resolved) {
		resolved = filepath.Join(r.workspace, resolved)
	}
	if absolute, err := filepath.Abs(resolved); err == nil {
		resolved = absolute
	}
	if canonical, err := filepath.EvalSymlinks(resolved); err == nil {
		resolved = canonical
	}
	resolved = filepath.Clean(resolved)
	if runtime.GOOS == "windows" {
		resolved = strings.ToLower(resolved)
	}
	return []string{resolved}
}

func (r *codeModeToolRuntime) acquireSemaphore() error {
	select {
	case r.semaphore <- struct{}{}:
		return nil
	case <-r.ctx.Done():
		return cmError("Cancelled", "Code Mode execution was aborted.", nil)
	}
}

func (r *codeModeToolRuntime) execute(tool *projectedTool, input any) (any, error) {
	select {
	case <-r.ctx.Done():
		return nil, cmError("Cancelled", "Code Mode execution was aborted.", nil)
	default:
	}
	r.mu.Lock()
	if r.callCount >= r.limits.MaxToolCalls {
		r.mu.Unlock()
		return nil, cmError("ToolCallLimitExceeded", fmt.Sprintf("Code Mode exceeded the %d-tool-call limit.", r.limits.MaxToolCalls), nil)
	}
	callIndex := r.callCount
	r.callCount++
	r.mu.Unlock()

	started := time.Now()
	if err := r.acquireSemaphore(); err != nil {
		return nil, err
	}
	defer func() { <-r.semaphore }()
	unlock := r.mutationQueue.lockKeys(r.mutationKeys(tool, input))
	defer unlock()
	select {
	case <-r.ctx.Done():
		return nil, cmError("Cancelled", "Code Mode execution was aborted.", nil)
	default:
	}

	var result ToolResult
	var executeErr error
	arguments := input
	if tool.definition.ExecuteRaw != nil {
		raw, ok := input.(string)
		if !ok {
			result = failure("Invalid arguments for " + tool.definition.Name + ": expected raw string")
		} else {
			result, executeErr = tool.definition.ExecuteRaw(raw)
		}
	} else {
		object, ok := input.(map[string]any)
		if !ok {
			result = failure("Invalid arguments for " + tool.definition.Name + ": expected object")
		} else {
			result, executeErr = tool.definition.Execute(object)
		}
	}
	if executeErr != nil {
		result = failure(executeErr.Error())
	}
	result = prepareToolResultForModel(tool.definition.Name, result)
	duration := time.Since(started).Milliseconds()

	if len(result.Media) > 0 {
		bytes := 0
		for _, media := range result.Media {
			bytes += len(media.Data)
		}
		r.mu.Lock()
		if r.mediaItems+len(result.Media) > defaultMediaItems || r.mediaBytes+bytes > defaultMediaBytes {
			result = failure(fmt.Sprintf("Code Mode media output exceeds limit of %d items or %d bytes", defaultMediaItems, defaultMediaBytes))
		} else {
			r.mediaItems += len(result.Media)
			r.mediaBytes += bytes
		}
		r.mu.Unlock()
	}

	receipt := ToolCallReceipt{Name: tool.definition.Name, Arguments: arguments, Status: result.Status, Summary: result.Summary, Body: result.Body, DurationMS: duration, Semantics: result.Semantics, Subject: result.Subject, Media: result.Media, CallIndex: callIndex}
	r.mu.Lock()
	r.receipts = append(r.receipts, receipt)
	r.mu.Unlock()
	if result.Status == "error" {
		return nil, classifyToolFailure(tool.definition.Name, result)
	}
	return internalizeData(serializeCodeModeToolResult(result)), nil
}

func classifyToolFailure(name string, result ToolResult) error {
	message := strings.TrimSpace(result.Summary)
	if message == "" {
		message = strings.TrimSpace(result.Body)
	}
	if message == "" {
		message = "Tool '" + name + "' failed."
	}
	lower := strings.ToLower(message)
	if strings.Contains(lower, "invalid arguments") || strings.Contains(lower, "input validation") {
		return cmError("InvalidToolArguments", message, nil)
	}
	if strings.Contains(lower, "permission") || strings.Contains(lower, "not permitted") || strings.Contains(lower, "denied") || strings.Contains(lower, "read-only") || strings.Contains(lower, "read only") {
		return cmError("PermissionDenied", message, nil)
	}
	return cmError("ToolExecutionError", message, nil)
}

