func (i *codeModeInterpreter) executeBindings(bindings []*ast.Binding, kind string, env *environment) error {
	for _, binding := range bindings {
		value := any(codeUndefined)
		var err error
		if binding.Initializer != nil {
			value, err = i.evaluate(binding.Initializer, env)
			if err != nil {
				return err
			}
		}
		if err = i.bindTarget(binding.Target, value, env, kind, binding.Initializer); err != nil {
			return err
		}
	}
	return nil
}

func (i *codeModeInterpreter) executeSwitch(n *ast.SwitchStatement, env *environment) error {
	value, err := i.evaluate(n.Discriminant, env)
	if err != nil {
		return err
	}
	matched := false
	for _, item := range n.Body {
		if !matched {
			if item.Test == nil {
				matched = true
			} else {
				test, evalErr := i.evaluate(item.Test, env)
				if evalErr != nil {
					return evalErr
				}
				matched = strictEqual(value, test)
			}
		}
		if !matched {
			continue
		}
		if err := i.executeStatements(item.Consequent, newEnvironment(env)); err != nil {
			if _, ok := err.(*breakSignal); ok {
				return nil
			}
			return err
		}
	}
	return nil
}

func (i *codeModeInterpreter) executeFor(n *ast.ForStatement, env *environment) error {
	loop := newEnvironment(env)
	if n.Initializer != nil {
		switch init := n.Initializer.(type) {
		case *ast.ForLoopInitializerExpression:
			if _, err := i.evaluate(init.Expression, loop); err != nil {
				return err
			}
		case *ast.ForLoopInitializerVarDeclList:
			if err := i.executeBindings(init.List, "var", loop); err != nil {
				return err
			}
		case *ast.ForLoopInitializerLexicalDecl:
			if err := i.executeBindings(init.LexicalDeclaration.List, init.LexicalDeclaration.Token.String(), loop); err != nil {
				return err
			}
		default:
			return unsupportedCodeModeNode(init, "")
		}
	}
	for {
		if err := i.tick(n); err != nil {
			return err
		}
		if n.Test != nil {
			test, err := i.evaluate(n.Test, loop)
			if err != nil {
				return err
			}
			if !truthy(test) {
				return nil
			}
		}
		err := i.executeStatement(n.Body, loop)
		if err != nil {
			if _, ok := err.(*breakSignal); ok {
				return nil
			}
			if _, ok := err.(*continueSignal); !ok {
				return err
			}
		}
		if n.Update != nil {
			if _, err := i.evaluate(n.Update, loop); err != nil {
				return err
			}
		}
	}
}

func (i *codeModeInterpreter) executeForOf(n *ast.ForOfStatement, env *environment, _ bool) error {
	right, err := i.evaluate(n.Source, env)
	if err != nil {
		return err
	}
	values := []any{}
	switch value := right.(type) {
	case *codeArray:
		values = append(values, value.items...)
	case string:
		for _, r := range []rune(value) {
			values = append(values, string(r))
		}
	default:
		return i.attach(cmError("TypeError", "for...of expects an array or string in Tidecode Code Mode.", n), n)
	}
	for _, value := range values {
		if err := i.tick(n); err != nil {
			return err
		}
		iteration := newEnvironment(env)
		if err := i.bindForInto(n.Into, value, iteration); err != nil {
			return err
		}
		err := i.executeStatement(n.Body, iteration)
		if err != nil {
			if _, ok := err.(*breakSignal); ok {
				return nil
			}
			if _, ok := err.(*continueSignal); ok {
				continue
			}
			return err
		}
	}
	return nil
}

func (i *codeModeInterpreter) executeForIn(n *ast.ForInStatement, env *environment) error {
	right, err := i.evaluate(n.Source, env)
	if err != nil {
		return err
	}
	keys := []string{}
	switch value := right.(type) {
	case *toolReference:
		keys = i.tools.keys(value)
	case *payloadNamespace:
		for key := range value.values {
			keys = append(keys, key)
		}
		sortStrings(keys)
	case *codeArray:
		for index := range value.items {
			keys = append(keys, strconv.Itoa(index))
		}
	case *codeObject:
		for key := range value.props {
			keys = append(keys, key)
		}
		sortStrings(keys)
	default:
		return i.attach(cmError("TypeError", "for...in expects a data object, array, or tools namespace.", n), n)
	}
	for _, key := range keys {
		if err := i.tick(n); err != nil {
			return err
		}
		iteration := newEnvironment(env)
		if err := i.bindForInto(n.Into, key, iteration); err != nil {
			return err
		}
		err := i.executeStatement(n.Body, iteration)
		if err != nil {
			if _, ok := err.(*breakSignal); ok {
				return nil
			}
			if _, ok := err.(*continueSignal); ok {
				continue
			}
			return err
		}
	}
	return nil
}

func (i *codeModeInterpreter) bindForInto(into ast.ForInto, value any, env *environment) error {
	switch left := into.(type) {
	case *ast.ForIntoExpression:
		return i.assignPattern(left.Expression, value, env)
	case *ast.ForIntoVar:
		return i.bindTarget(left.Binding.Target, value, env, "var", left.Binding.Initializer)
	case *ast.ForDeclaration:
		kind := "let"
		if left.IsConst {
			kind = "const"
		}
		return i.bindTarget(left.Target, value, env, kind, nil)
	default:
		return unsupportedCodeModeNode(into, "")
	}
