func canonicalArrayIndex(name string) (int, bool) {
	if name == "0" {
		return 0, true
	}
	if name == "" || name[0] == '0' {
		return 0, false
	}
	for _, r := range name {
		if r < '0' || r > '9' {
			return 0, false
		}
	}
	index, err := strconv.Atoi(name)
	return index, err == nil && index >= 0
}

func memberKeyValue(value any, node ast.Node) (string, error) {
	switch key := value.(type) {
	case string:
		if blockedCodeModeMembers[key] {
			return "", cmError("TypeError", fmt.Sprintf("Property '%s' is not available in Tidecode Code Mode.", key), node)
		}
		return key, nil
	case float64:
		if math.Trunc(key) != key {
			return stringValue(key), nil
		}
		return strconv.FormatInt(int64(key), 10), nil
	default:
		return "", cmError("TypeError", "Member keys must resolve to strings or numbers.", node)
	}
}

