package tidecode

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

const managedDir = ".tidecode"

func resolveWorkspace(root string) (string, error) {
	if strings.TrimSpace(root) == "" || !filepath.IsAbs(root) {
		return "", errors.New("workspace_path must be an absolute path")
	}
	abs, err := filepath.Abs(root)
	if err != nil {
		return "", err
	}
	st, err := os.Stat(abs)
	if err != nil {
		return "", fmt.Errorf("selected workspace is not accessible: %w", err)
	}
	if !st.IsDir() {
		return "", errors.New("selected workspace must be a directory")
	}
	real, err := filepath.EvalSymlinks(abs)
	if err != nil {
		return "", err
	}
	return filepath.Clean(real), nil
}

func inside(root, candidate string) bool {
	rel, err := filepath.Rel(root, candidate)
	if err != nil {
		return false
	}
	return rel == "." || (rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator)) && !filepath.IsAbs(rel))
}

func privateRelative(root, candidate string) bool {
	rel, err := filepath.Rel(root, candidate)
	if err != nil {
		return false
	}
	if rel == "." {
		return false
	}
	for _, p := range strings.FieldsFunc(rel, func(r rune) bool { return r == '/' || r == '\\' }) {
		if strings.EqualFold(p, managedDir) {
			return true
		}
	}
	return false
}

func genericReadVisible(root, candidate string) bool {
	if !privateRelative(root, candidate) {
		return true
	}
	rel, err := filepath.Rel(root, candidate)
	if err != nil {
		return false
	}
	normalized := strings.ToLower(filepath.ToSlash(filepath.Clean(rel)))
	return normalized == ".tidecode" ||
		normalized == ".tidecode/plans" ||
		strings.HasPrefix(normalized, ".tidecode/plans/")
}

func cleanInputPath(input string, rootCapable bool) (string, error) {
	if strings.TrimSpace(input) == "" {
		if rootCapable {
			return ".", nil
		}
		return "", errors.New("path must be non-empty")
	}
	return input, nil
}

func lexicalCandidate(root, input string, rootCapable bool) (string, error) {
	p, err := cleanInputPath(input, rootCapable)
	if err != nil {
		return "", err
	}
	var c string
	if filepath.IsAbs(p) {
		c = filepath.Clean(p)
	} else {
		c = filepath.Clean(filepath.Join(root, p))
	}
	if !inside(root, c) {
		return "", errors.New("path is outside the selected workspace")
	}
	if privateRelative(root, c) {
		return "", errors.New("planner-private .tidecode paths are private and cannot be accessed by generic filesystem tools")
	}
	return c, nil
}

func rejectLinksFromRoot(root, candidate string, allowMissing bool) error {
	rel, err := filepath.Rel(root, candidate)
	if err != nil {
		return err
	}
	cur := root
	if rel == "." {
		return nil
	}
	parts := strings.FieldsFunc(rel, func(r rune) bool { return r == '/' || r == '\\' })
	for _, part := range parts {
		cur = filepath.Join(cur, part)
		fi, err := os.Lstat(cur)
		if err != nil {
			if allowMissing && os.IsNotExist(err) {
				return nil
			}
			return err
		}
		if fi.Mode()&os.ModeSymlink != 0 {
			return fmt.Errorf("symbolic links or junctions are not allowed in structured paths: %s", cur)
		}
	}
	return nil
}

func resolveReadPath(root, input string, rootCapable bool) (string, error) {
	workspace, err := resolveWorkspace(root)
	if err != nil {
		return "", err
	}
	p, err := cleanInputPath(input, rootCapable)
	if err != nil {
		return "", err
	}
	var c string
	if filepath.IsAbs(p) {
		c = filepath.Clean(p)
	} else {
		c = filepath.Clean(filepath.Join(workspace, p))
	}
	if !inside(workspace, c) {
		return "", errors.New("path is outside the selected workspace")
	}
	if !genericReadVisible(workspace, c) {
		return "", errors.New("planner-private .tidecode paths are private and cannot be accessed by generic filesystem tools")
	}
	if err != nil {
		return "", err
	}
	if err := rejectLinksFromRoot(workspace, c, false); err != nil {
		return "", err
	}
	real, err := filepath.EvalSymlinks(c)
	if err != nil {
		return "", err
	}
	if !inside(workspace, real) {
		return "", errors.New("Resolved path is outside the selected workspace")
	}
	if !genericReadVisible(workspace, real) {
		return "", errors.New("planner-private .tidecode paths are private")
	}
	return real, nil
}

func resolveMutationPath(root, input string) (string, error) {
	workspace, err := resolveWorkspace(root)
	if err != nil {
		return "", err
	}
	if strings.TrimSpace(input) == "" {
		return "", errors.New("path must be non-empty")
	}
	normalized := strings.ReplaceAll(input, "\\", "/")
	if strings.HasPrefix(strings.ToLower(normalized), ".tidecode/plans/") {
		return "", errors.New("generic mutations cannot modify .tidecode/plans; use plan tools")
	}
	c, err := lexicalCandidate(workspace, input, false)
	if err != nil {
		return "", err
	}
	if err := rejectLinksFromRoot(workspace, c, true); err != nil {
		return "", err
	}
	parent := c
	for {
		_, e := os.Lstat(parent)
		if e == nil {
			break
		}
		if !os.IsNotExist(e) {
			return "", e
		}
		next := filepath.Dir(parent)
		if next == parent {
			break
		}
		parent = next
	}
	real, err := filepath.EvalSymlinks(parent)
	if err != nil {
		return "", err
	}
	if !inside(workspace, real) {
		return "", errors.New("resolved mutation parent is outside the selected workspace")
	}
	return c, nil
}

func slashRelative(root, p string) string {
	r, _ := filepath.Rel(root, p)
	return filepath.ToSlash(r)
}

func ensureManagedPathNoLinks(root, relative string) (string, error) {
	workspace, err := resolveWorkspace(root)
	if err != nil {
		return "", err
	}
	candidate := filepath.Join(workspace, filepath.FromSlash(relative))
	if !inside(workspace, candidate) {
		return "", errors.New("managed path escaped workspace")
	}
	if err := rejectLinksFromRoot(workspace, candidate, true); err != nil {
		return "", err
	}
	return candidate, nil
}

