func TestExplorerRejectsLinkEscape(t *testing.T) {
	root := tempWorkspace(t)
	outside := tempWorkspace(t)
	_ = os.WriteFile(filepath.Join(outside, "secret.txt"), []byte("secret\n"), 0o644)
	link := filepath.Join(root, "escape")
	err := os.Symlink(outside, link)
	if err != nil {
		if runtime.GOOS == "windows" {
			t.Skipf("symlink unavailable: %v", err)
		}
		t.Fatal(err)
	}
	_, err = (ReadService{}).Read(root, filepath.Join("escape", "secret.txt"))
	if err == nil {
		t.Fatal("expected link escape rejection")
	}
	msg := strings.ToLower(err.Error())
	if !strings.Contains(msg, "symbolic") && !strings.Contains(msg, "junction") && !strings.Contains(msg, "resolved path") {
		t.Fatalf("unexpected error: %v", err)
	}
}

