func walkVisible(workspace, root string, fn func(string, os.DirEntry) bool) error {
	return filepath.WalkDir(root, func(path string, d os.DirEntry, err error) error {
		if err != nil {
			return nil
		}
		if path == root {
			return nil
		}
		if !genericReadVisible(workspace, path) {
			if d.IsDir() {
				return filepath.SkipDir
