	}})
	add(ToolDefinition{Name: "read_terminal", Title: "Read terminal", Namespace: "terminal", Scope: "planner:terminal", Signature: "tools.read_terminal({ session_id, wait_seconds? })", Description: "Read incremental output from a persistent terminal session.", Execute: func(m map[string]any) (ToolResult, error) {
		id := numInt(m["session_id"])
		if id == 0 {
			return failure("Invalid arguments for read_terminal: session_id is required"), nil
		}
		wait := 15
		if _, ok := m["wait_seconds"]; ok {
			wait = numInt(m["wait_seconds"])
		}
		return terminal.Read(owner, TerminalReadInput{SessionID: id, WaitSeconds: wait, WorkspacePath: root})
	}})
	add(ToolDefinition{Name: "interact_terminal", Title: "Interact terminal", Namespace: "terminal", Scope: "planner:terminal", Signature: "tools.interact_terminal({ session_id, text?, keys?, cols?, rows?, wait_seconds? })", Description: "Send input, control keys, or resize a terminal session.", Execute: func(m map[string]any) (ToolResult, error) {
		var in TerminalInteractInput
		if e := decodeMap(m, &in); e != nil {
			return failure("Invalid arguments for interact_terminal: " + e.Error()), nil
		}
		in.WorkspacePath = root
		if _, ok := m["wait_seconds"]; !ok && in.Text == "" && len(in.Keys) == 0 && in.Cols == 0 && in.Rows == 0 {
			in.WaitSeconds = 15
		}
		return terminal.Interact(owner, in)
	}})
	add(ToolDefinition{Name: "terminate_terminal", Title: "Terminate terminal", Namespace: "terminal", Scope: "planner:terminal", Signature: "tools.terminate_terminal({ session_id })", Description: "Terminate a persistent terminal session.", Execute: func(m map[string]any) (ToolResult, error) {
		id := numInt(m["session_id"])
		if id == 0 {
			return failure("Invalid arguments for terminate_terminal: session_id is required"), nil
		}
		return terminal.Terminate(owner, root, id)
	}})
	registry := newRegistry(entries)
	toolSearch := ToolDefinition{Name: "tool_search", Title: "Search internal Tidecode tools", Namespace: "workspace", Scope: "planner:read", Signature: "tools.tool_search({ query, namespace?, limit? })", Description: "Find internal Tidecode APIs available inside tcode_mode. Returns compact tools.<name>({ ... }) signatures.", Execute: func(m map[string]any) (ToolResult, error) {
		if !scopes.Allows("planner:read") {
			return failure("Missing required scope: planner:read"), nil
		}
		clean, sanitizeErr := sanitizeBuiltinToolArgs("tool_search", m)
		if sanitizeErr != nil {
			return failure(sanitizeErr.Error()), nil
		}
		m = clean
		q, e := requireString(m, "query", false)
		if e != nil {
			return failure("Invalid arguments for tool_search: " + e.Error()), nil
		}
		namespace, _ := m["namespace"].(string)
		limit := 10
		if _, ok := m["limit"]; ok {
			limit = numInt(m["limit"])
			if limit < 1 || limit > 20 {
				return failure("Invalid arguments for tool_search: limit must be between 1 and 20"), nil
			}
		}
		matches := registry.SearchWithOptions(q, namespace, limit)
		tools := make([]map[string]any, 0, len(matches))
		for _, d := range matches {
			tools = append(tools, map[string]any{"name": d.Name, "title": d.Title, "description": d.Description, "signature": d.Signature, "namespace": d.Namespace})
		}
		b, _ := json.Marshal(map[string]any{"query": q, "tools": tools})
		r := withBody(success(fmt.Sprintf("Found %d internal tools for %s", len(tools), q)), string(b))
		r.Semantics = map[string]any{"match_count": len(tools), "operation": "tool_search", "query": q}
		return r, nil
	}}
	registry.Entries = append(registry.Entries, toolSearch)
	registry.byName[toolSearch.Name] = &registry.Entries[len(registry.Entries)-1]
	return registry
}

func bindCodeModeRegistry(root, owner string, terminal *TerminalService, scopes ScopeSet) *ToolRegistry {
	return bindRegistryFiltered(root, owner, terminal, scopes, map[string]bool{
		"apply_patch": true,
		"write":       true,
	})
}

func registryContract(r *ToolRegistry) string {
	var b strings.Builder
	for _, d := range r.Entries {
		b.WriteString("- " + d.Signature + ": " + d.Description + "\n")
	}
	return b.String()
}

