func tempWorkspace(t *testing.T) string {
	t.Helper()
	p, err := os.MkdirTemp("", "tidecode-go-test-")
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = os.RemoveAll(p) })
	return p
}

func TestExplorerWorkspaceSafety(t *testing.T) {
	root := tempWorkspace(t)
	outside := filepath.Join(filepath.Dir(root), filepath.Base(root)+"-outside.txt")
	t.Cleanup(func() { _ = os.Remove(outside) })
	if err := os.MkdirAll(filepath.Join(root, "src"), 0o755); err != nil {
		t.Fatal(err)
	}
	_ = os.WriteFile(filepath.Join(root, "src", "server.ts"), []byte("export const answer = 42\n"), 0o644)
	_ = os.WriteFile(filepath.Join(root, "README.md"), []byte("# Planner\n"), 0o644)
	_ = os.WriteFile(outside, []byte("outside secret\n"), 0o644)
	read := ReadService{}
	search := SearchService{}
	r, err := read.Read(root, "src/server.ts")
	if err != nil {
		t.Fatal(err)
	}
	if r.Status != "success" || !strings.Contains(r.Body, "1: export const answer = 42") {
		t.Fatalf("bad read: %#v", r)
	}
	l, err := search.List(root, ".")
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(l.Body, "src/") || !strings.Contains(l.Body, "README.md") {
		t.Fatalf("bad list %q", l.Body)
