func safeToolSegment(raw string) string {
	var b strings.Builder
	for i, r := range raw {
		valid := (r >= 'A' && r <= 'Z') || (r >= 'a' && r <= 'z') || r == '_' || r == '$' || (i > 0 && r >= '0' && r <= '9')
		if valid {
			b.WriteRune(r)
		} else {
			b.WriteByte('_')
		}
	}
	value := b.String()
	if value == "" {
		value = "_tool"
	}
	first := value[0]
	if first >= '0' && first <= '9' {
		value = "_" + value
	}
	if blockedCodeModeMembers[value] {
		value = "_" + value
	}
	return value
}

type projectedTool struct {
	definition *ToolDefinition
	path       []string
	expression string
