	add(ToolDefinition{Name: "read", Title: "Read", Namespace: "workspace", Scope: "planner:read", Signature: "tools.read({ path, offset?, limit?, full_file? })", Description: "Read a workspace text file with line numbers, list a directory, or return supported images as visual MCP content. Managed plan documents under .tidecode/plans are readable; other .tidecode managed state remains private. Treat a file path as known only when the user supplied it or a prior workspace tool returned that exact path. Never invent a likely filename from project conventions. If the exact path is unknown, discover it with list, glob, or grep before read or mutation. Omitted path or empty string means workspace root.", Execute: func(m map[string]any) (ToolResult, error) {
		p, _ := m["path"].(string)
