	add(ToolDefinition{Name: "list", Title: "List", Namespace: "workspace", Scope: "planner:read", Signature: "tools.list({ path?, offset?, limit? })", Description: "List visible entries. Omitted path or empty string means workspace root.", Execute: func(m map[string]any) (ToolResult, error) {
