	add(ToolDefinition{Name: "apply_patch", Title: "Apply patch", Namespace: "workspace", Scope: "planner:write", Signature: "tools.apply_patch(input: string)", Description: "Primary API for targeted source changes. Apply one raw Codex patch string with add, update, move, and delete hunks. Use *** Add File only for a new path; every file-content line in an Add File hunk must start with +, including an added blank line represented as +. Use *** Update File for edits to an existing path. Complete patch template literals passed to apply_patch are normalized as literal patch data before JavaScript evaluation, so nested backticks, ${...}, backslash sequences such as \\n, regex escapes, and Windows paths do not require double-escaping or a write fallback. If a generated update anchor has exactly one extra backslash-escaping layer, it is auto-repaired only when one unique non-overlapping source candidate exists; ambiguous or genuinely stale anchors still reject without mutation. The full patch is parsed, matched, staged, and verified before any file changes are committed; unique already-applied update hunks are accepted on safe retries, and commit failures roll back earlier installs.", ExecuteRaw: func(input string) (ToolResult, error) {
		return patch.Apply(root, input)
	}})
	add(ToolDefinition{Name: "memory", Title: "Memory", Namespace: "planner", Scope: "planner:memory", Signature: "tools.memory({ action, folder?, name?, title?, content?, old_text?, new_text? })", Description: "Read and maintain planner memory under .tidecode/memory using logical identifiers.", Execute: func(m map[string]any) (ToolResult, error) {
