	add(ToolDefinition{Name: "skill", Title: "Skill", Namespace: "planner", Scope: "planner:read", Signature: "tools.skill({ action, query?, name?, page? })", Description: "List, search, or load available workspace and global skills.", Execute: func(m map[string]any) (ToolResult, error) {
