	add(ToolDefinition{Name: "read_terminal", Title: "Read terminal", Namespace: "terminal", Scope: "planner:terminal", Signature: "tools.read_terminal({ session_id, wait_seconds? })", Description: "Read incremental output from a persistent terminal session.", Execute: func(m map[string]any) (ToolResult, error) {
		id := numInt(m["session_id"])
		if id == 0 {
			return failure("Invalid arguments for read_terminal: session_id is required"), nil
		}
		wait := 15
		if _, ok := m["wait_seconds"]; ok {
