	add(ToolDefinition{Name: "interact_terminal", Title: "Interact terminal", Namespace: "terminal", Scope: "planner:terminal", Signature: "tools.interact_terminal({ session_id, text?, keys?, cols?, rows?, wait_seconds? })", Description: "Send input, control keys, or resize a terminal session.", Execute: func(m map[string]any) (ToolResult, error) {
		var in TerminalInteractInput
		if e := decodeMap(m, &in); e != nil {
