	add(ToolDefinition{Name: "terminate_terminal", Title: "Terminate terminal", Namespace: "terminal", Scope: "planner:terminal", Signature: "tools.terminate_terminal({ session_id })", Description: "Terminate a persistent terminal session.", Execute: func(m map[string]any) (ToolResult, error) {
