	registry := newRegistry(entries)
	toolSearch := ToolDefinition{Name: "tool_search", Title: "Search internal Tidecode tools", Namespace: "workspace", Scope: "planner:read", Signature: "tools.tool_search({ query, namespace?, limit? })", Description: "Find internal Tidecode APIs available inside tcode_mode. Returns compact tools.<name>({ ... }) signatures.", Execute: func(m map[string]any) (ToolResult, error) {
