			return failure("Missing required scope: planner:read"), nil
		}
		clean, sanitizeErr := sanitizeBuiltinToolArgs("tool_search", m)
		if sanitizeErr != nil {
			return failure(sanitizeErr.Error()), nil
		}
		m = clean
		q, e := requireString(m, "query", false)
		if e != nil {
			return failure("Invalid arguments for tool_search: " + e.Error()), nil
		}
		namespace, _ := m["namespace"].(string)
		limit := 10
		if _, ok := m["limit"]; ok {
			limit = numInt(m["limit"])
			if limit < 1 || limit > 20 {
				return failure("Invalid arguments for tool_search: limit must be between 1 and 20"), nil
			}
		}
		matches := registry.SearchWithOptions(q, namespace, limit)
		tools := make([]map[string]any, 0, len(matches))
		for _, d := range matches {
			tools = append(tools, map[string]any{"name": d.Name, "title": d.Title, "description": d.Description, "signature": d.Signature, "namespace": d.Namespace})
		}
		b, _ := json.Marshal(map[string]any{"query": q, "tools": tools})
		r := withBody(success(fmt.Sprintf("Found %d internal tools for %s", len(tools), q)), string(b))
		r.Semantics = map[string]any{"match_count": len(tools), "operation": "tool_search", "query": q}
		return r, nil
	}}
	registry.Entries = append(registry.Entries, toolSearch)
	registry.byName[toolSearch.Name] = &registry.Entries[len(registry.Entries)-1]
	return registry
}

func bindCodeModeRegistry(root, owner string, terminal *TerminalService, scopes ScopeSet) *ToolRegistry {
	return bindRegistryFiltered(root, owner, terminal, scopes, map[string]bool{
		"apply_patch": true,
		"write":       true,
	})
}

func registryContract(r *ToolRegistry) string {
	var b strings.Builder
	for _, d := range r.Entries {
		b.WriteString("- " + d.Signature + ": " + d.Description + "\n")
	}
	return b.String()
}

